def country_table():
    """ISO 3166-1 국가·지역을 한국어 이름으로 표시합니다."""
    result = {}
    for country in pycountry.countries:
        alpha3 = getattr(country, "alpha_3", None)
        alpha2 = getattr(country, "alpha_2", None)
        if not alpha3:
            continue
        # 직접 지정한 한국어 명칭을 우선 사용합니다. Babel 설치 여부에 의존하지 않습니다.
        korean_name = KOREAN_COUNTRY_NAMES.get(alpha3)
        if not korean_name:
            korean_name = getattr(country, "common_name", country.name)
        result[alpha3] = korean_name
    # ISO 목록 밖의 별도 코드가 필요한 경우를 위한 선택적 추가
    result.setdefault("XKX", "코소보")
    return result

def label(iso, names):
    return names.get(iso, iso)


