# 추가 국가 연대기: 주요 사건과 사회·정치적 영향이 드러나도록 설명을 확장했습니다.
# 각 사건은 (연도, 시대, 제목, 설명) 형식입니다.
HISTORY.update({
    "ESP": ("스페인", [
        ("BC 3세기~BC 1세기", "고대", "로마의 이베리아 정복", "로마는 여러 이베리아 세력을 장기간에 걸쳐 정복하고 도로·도시·법률·라틴어를 확산시켰다. 이 과정은 훗날 스페인어와 이베리아 지역의 도시 문화가 형성되는 토대가 되었다."),
        ("711", "중세", "이슬람 세력의 이베리아 진출", "북아프리카에서 건너온 이슬람 세력이 이베리아 대부분을 장악했다. 알안달루스에서는 이슬람·기독교·유대교 문화가 교류했으며, 수학·의학·철학·건축의 발전에도 영향을 주었다."),
        ("722경~1492", "중세", "레콩키스타", "북부의 기독교 왕국들이 이슬람 세력의 지배 지역을 점차 되찾아 간 장기적인 과정이다. 지역과 시기에 따라 전쟁뿐 아니라 동맹과 교류도 있었으며, 1492년 그라나다 함락으로 주요 국면이 마무리되었다."),
        ("1469", "근세", "카스티야·아라곤 왕실 결합", "이사벨 1세와 페르난도 2세의 결혼은 두 왕국의 정치적 협력을 강화했다. 두 왕국의 제도가 즉시 하나로 합쳐진 것은 아니지만, 훗날 스페인 왕권이 통합되는 중요한 계기가 되었다."),
        ("1492", "근세", "그라나다 함락과 대서양 항해", "그라나다 왕국이 항복하면서 레콩키스타의 주요 국면이 끝났고, 같은 해 콜럼버스의 항해가 시작되었다. 이후 스페인은 아메리카에 식민지를 확대했고, 대서양 무역과 은 유입이 세계 경제에 큰 변화를 일으켰다."),
        ("16세기", "근세", "스페인 제국의 확대", "아메리카와 유럽의 여러 지역을 지배하면서 스페인은 유럽의 강대국이 되었다. 식민지에서 은과 자원이 유입되었지만 원주민 사회의 붕괴, 강제노동, 질병 확산 등 심각한 피해도 발생했다."),
        ("1588", "근세", "무적함대 원정 실패", "스페인은 잉글랜드를 압박하기 위해 대규모 함대를 보냈으나 원정에 실패했다. 이 사건 하나만으로 스페인의 쇠퇴가 결정된 것은 아니지만, 해상 패권과 국가 재정의 한계를 보여 주는 상징적 사건이 되었다."),
        ("1808~1814", "근대", "반도전쟁", "나폴레옹 군대의 침입과 왕위 교체에 맞서 스페인에서 저항과 게릴라전이 이어졌다. 전쟁은 경제와 사회를 크게 파괴했으며, 스페인령 아메리카에서 독립운동이 확대되는 배경 중 하나가 되었다."),
        ("1936~1939", "현대", "스페인 내전", "공화파와 프랑코를 중심으로 한 반란 세력이 싸웠고, 독일·이탈리아·소련 등 외부 세력도 개입했다. 전쟁은 막대한 인명 피해와 정치적 분열을 남겼으며, 프랑코 독재 체제로 이어졌다."),
        ("1975~1978", "현대", "민주화와 헌법 제정", "프랑코 사망 뒤 후안 카를로스 1세와 정치 세력들이 민주 체제로의 전환을 추진했다. 1978년 헌법은 의회 민주주의와 자치 지역 제도의 기초를 마련했다."),
    ]),
    "PRT": ("포르투갈", [
        ("1139~1143", "중세", "포르투갈 왕국의 성립", "아폰수 1세가 독자적인 왕권을 세우고 레온 왕국과의 관계 속에서 독립을 인정받았다. 이후 왕국은 이베리아 서쪽에서 국경을 넓히며 현재 포르투갈의 기본 영역을 형성했다."),
        ("1415", "근세", "세우타 정복", "포르투갈이 북아프리카의 세우타를 점령하면서 대서양과 아프리카 연안으로 향하는 팽창이 본격화되었다. 왕실은 무역과 항해 지식을 지원했고, 이후 유럽의 해외 진출 경쟁에 앞장섰다."),
        ("1488", "근세", "희망봉 항해", "바르톨로뮤 디아스가 아프리카 남단을 돌아 인도양으로 이어지는 항로의 가능성을 확인했다. 이는 유럽과 아시아 사이의 해상 무역로 개척에 중요한 전환점이었다."),
        ("1498", "근세", "바스쿠 다 가마의 인도 도착", "다 가마의 항해는 유럽에서 아프리카 남단을 거쳐 인도에 이르는 해상 항로를 연결했다. 포르투갈은 향신료 무역 거점을 확보했지만, 무역 통제 과정에서 군사력과 폭력도 사용했다."),
        ("1500", "근세", "브라질 도착", "페드루 알바르스 카브랄의 원정대가 브라질 해안에 도착해 포르투갈의 권리를 주장했다. 이후 사탕수수 플랜테이션과 노예무역이 확대되어 브라질의 사회 구조에 오랫동안 영향을 주었다."),
        ("1580~1640", "근세", "이베리아 연합", "포르투갈 왕위 계승 위기 뒤 스페인 국왕이 포르투갈 왕위를 겸했다. 포르투갈은 일부 제도와 식민지를 유지했지만, 스페인의 전쟁에 휘말리면서 해외 거점이 공격받기도 했다."),
        ("1755", "근대", "리스본 대지진", "대지진과 화재·해일이 리스본을 크게 파괴했다. 폼발 후작은 도시 재건과 행정 개혁을 추진했고, 재난을 관찰하고 설명하려는 계몽주의적 논의에도 영향을 주었다."),
        ("1910", "근대", "공화정 수립", "혁명으로 군주제가 폐지되고 공화국이 선포되었다. 새 정권은 세속화와 제도 개혁을 추진했지만 정치적 불안정이 계속되었다."),
        ("1974~1976", "현대", "카네이션 혁명과 민주화", "군부 내부의 움직임에서 시작된 혁명으로 독재 정권이 무너졌다. 포르투갈은 민주 제도를 정비하고 아프리카 식민지들의 독립을 인정하는 방향으로 전환했다."),
        ("1986", "현대", "유럽공동체 가입", "포르투갈은 유럽공동체에 가입해 경제·사회 제도를 유럽 통합 과정과 연결했다. 이후 인프라와 산업 발전에 변화가 있었고 유럽 내 이동과 교류도 확대되었다."),
    ]),
    "NLD": ("네덜란드", [
        ("1568~1648", "근세", "네덜란드 독립 전쟁", "저지대 지역의 여러 세력이 합스부르크 스페인의 통치에 맞서 장기간 싸웠다. 종교 갈등과 지방 자치 문제도 얽혀 있었으며, 전쟁 끝에 네덜란드 공화국의 독립이 국제적으로 인정되었다."),
        ("1602", "근세", "네덜란드 동인도회사 설립", "동인도회사는 아시아 무역을 독점적으로 수행하고 군사·외교 권한까지 행사했다. 네덜란드는 세계 무역과 금융에서 영향력을 키웠지만, 식민지 지배와 강제 노동을 통해 큰 이익을 얻기도 했다."),
        ("17세기", "근세", "네덜란드 황금시대", "암스테르담을 중심으로 무역·금융·조선업이 성장했고 렘브란트와 베르메르 같은 화가들이 활동했다. 번영은 국제 무역망에 기반했으며 식민지 착취와 노예무역도 그 일부였다."),
        ("1672", "근세", "재난의 해", "프랑스와 여러 적대 세력이 네덜란드를 공격하면서 공화국은 심각한 위기에 빠졌다. 이 사건은 해상 무역과 국방의 중요성을 드러내고 정치적 권력 구도에도 영향을 주었다."),
        ("1795", "근대", "바타비아 공화국", "프랑스 혁명군의 영향으로 옛 공화국이 무너지고 바타비아 공화국이 세워졌다. 이후 네덜란드는 프랑스의 영향 아래 정치 제도를 개편했고, 왕정 수립으로 이어지는 변화를 겪었다."),
        ("1815", "근대", "네덜란드 왕국 성립", "나폴레옹 전쟁 이후 유럽의 질서를 재편하는 과정에서 네덜란드 왕국이 만들어졌다. 벨기에와의 결합은 오래가지 못했고, 1830년 벨기에 혁명으로 분리되었다."),
        ("1940~1945", "현대", "독일 점령과 해방", "나치 독일이 네덜란드를 점령했고 유대인 공동체를 포함한 많은 주민이 박해와 추방을 당했다. 저항 운동과 연합군의 진격 끝에 해방되었으며, 전후 재건과 유럽 협력이 중요한 과제가 되었다."),
        ("1957", "현대", "유럽경제공동체 창설 참여", "네덜란드는 유럽경제공동체 창설국 중 하나로 참여했다. 전쟁 이후 경제 협력과 공동 시장을 통해 유럽의 평화와 번영을 추구하는 통합 과정에 기여했다."),
    ]),
    "POL": ("폴란드", [
        ("966", "중세", "미에슈코 1세의 기독교 수용", "통치자가 기독교를 받아들인 사건은 폴란드 국가 형성의 상징적인 출발점으로 여겨진다. 기독교 수용은 외교 관계와 문자 문화, 왕권의 정당성에 큰 영향을 주었다."),
        ("1025", "중세", "폴란드 왕국 성립", "볼레스와프 1세가 왕으로 즉위하면서 왕국의 위상이 높아졌다. 이후 폴란드는 주변 세력과 경쟁하면서 영토와 왕권을 강화하거나 분열을 겪었다."),
        ("1385~1386", "중세", "폴란드·리투아니아 결합", "크레보 조약과 야기에우워의 즉위로 두 지역의 왕조적 결합이 이루어졌다. 이 결합은 동유럽의 세력 균형을 바꾸고 이후 강력한 폴란드·리투아니아 연방으로 발전하는 기반이 되었다."),
        ("1410", "중세", "그룬발트 전투", "폴란드·리투아니아 연합군이 튜턴 기사단을 크게 물리쳤다. 전투는 발트해 지역의 권력 관계에 영향을 주었고 폴란드·리투아니아의 군사적 위상을 높였다."),
        ("1569", "근세", "루블린 연합", "폴란드 왕국과 리투아니아 대공국이 폴란드·리투아니아 연방을 구성했다. 연방은 넓은 영토와 귀족 의회 정치를 특징으로 했지만, 정치적 합의 구조가 국가 운영의 어려움으로 이어지기도 했다."),
        ("1795", "근대", "폴란드 분할과 국가 소멸", "러시아·프로이센·오스트리아가 여러 차례 영토를 나누어 점령하면서 폴란드는 독립 국가로서 지도에서 사라졌다. 폴란드인들은 망명과 봉기, 문화 활동을 통해 국가 회복의 열망을 이어 갔다."),
        ("1918", "현대", "독립 회복", "제1차 세계대전과 주변 제국의 붕괴 뒤 폴란드는 독립을 되찾았다. 새 국가는 국경을 정하고 정치 제도를 세우는 과정에서 주변국과 충돌을 겪었다."),
        ("1939~1945", "현대", "독일·소련의 침공과 점령", "독일과 소련의 침공으로 폴란드는 다시 분할 점령되었다. 나치의 유대인 학살과 민간인 탄압으로 엄청난 피해가 발생했고, 전후 국경과 정치 체제도 크게 달라졌다."),
        ("1980~1989", "현대", "연대노조와 민주화", "레흐 바웬사가 상징한 연대노조는 노동자의 권리와 정치적 자유를 요구했다. 계엄령과 탄압을 겪었지만 협상과 선거를 거쳐 공산당 지배가 끝나는 동유럽 변화의 중요한 사례가 되었다."),
        ("2004", "현대", "유럽연합 가입", "폴란드는 유럽연합에 가입해 경제·법 제도와 유럽 시장의 연결을 강화했다. 가입은 무역과 이동을 확대했지만 지역 간 격차와 정책 갈등 같은 과제도 함께 가져왔다."),
    ]),
    "AUT": ("오스트리아", [
        ("976", "중세", "오스트리아 변경백령", "신성로마제국의 동쪽 변경 지역으로 기록되며 오스트리아의 역사적 형성 과정이 시작되었다. 바벤베르크와 합스부르크 가문의 지배 아래 지역의 정치적 중요성이 커졌다."),
        ("1278", "중세", "합스부르크의 오스트리아 지배", "루돌프 1세가 보헤미아의 오타카르 2세를 물리치면서 합스부르크 가문이 오스트리아에서 영향력을 확대했다. 이후 이 가문은 여러 유럽 왕위와 영토를 차지하며 강력한 왕조가 되었다."),
        ("1526", "근세", "합스부르크의 중부 유럽 영향력 확대", "모하치 전투 이후 헝가리와 보헤미아의 왕위 계승 문제가 합스부르크와 연결되었다. 오스트리아는 오스만 제국과의 경쟁 속에서 중부 유럽의 주요 권력 중심지로 성장했다."),
        ("1683", "근세", "빈 포위전", "오스만 군대의 빈 포위가 폴란드·리투아니아군 등을 포함한 구원군에 의해 해제되었다. 이 사건은 중부 유럽의 세력 균형에 영향을 주었으며 이후 합스부르크의 동쪽 영토 확대가 이어졌다."),
        ("1804~1806", "근대", "오스트리아 제국과 신성로마제국 해체", "나폴레옹 전쟁 속에서 합스부르크는 오스트리아 제국을 선포했고, 1806년 신성로마제국은 해체되었다. 이는 중세부터 이어진 유럽의 정치 질서가 크게 바뀌었음을 보여 준다."),
        ("1867", "근대", "오스트리아-헝가리 이중제국", "헝가리와의 타협으로 두 정부가 하나의 군주 아래 공존하는 체제가 만들어졌다. 다양한 민족과 언어 집단을 포함했지만 민족주의 갈등은 계속되었다."),
        ("1918", "현대", "제국 해체와 공화국", "제1차 세계대전 패전으로 합스부르크 군주제가 무너지고 오스트리아 공화국이 수립되었다. 제국의 여러 민족 지역이 독립하면서 오스트리아의 영토와 국제적 역할이 크게 축소되었다."),
        ("1938", "현대", "안슐루스", "나치 독일이 오스트리아를 병합했고, 오스트리아의 독립은 사라졌다. 유대인과 정권 반대자들이 박해를 받았으며 오스트리아인들도 나치 체제에 협력하거나 저항하는 등 다양한 경험을 했다."),
        ("1955", "현대", "국가조약과 중립 선언", "점령국과의 국가조약으로 오스트리아의 주권이 회복되었다. 오스트리아는 영구 중립을 선언하고 동서 냉전 사이에서 중립국 외교를 발전시켰다."),
    ]),
    "CHE": ("스위스", [
        ("1291", "중세", "구스위스 동맹의 전통적 기원", "우리·슈비츠·운터발덴 지역의 동맹 문서가 스위스 연방의 상징적 출발점으로 여겨진다. 이후 여러 지역이 동맹에 참여하면서 자치와 공동 방위의 전통이 발전했다."),
        ("1499", "근세", "슈바벤 전쟁", "스위스 연합은 합스부르크와의 전쟁에서 사실상 자치권을 강화했다. 1648년 베스트팔렌 조약은 신성로마제국으로부터의 독립을 국제적으로 확인하는 데 중요한 역할을 했다."),
        ("1515", "근세", "마리냐노 전투", "스위스 용병군이 프랑스군에 패배한 뒤 스위스는 대외 팽창을 자제하는 방향으로 나아갔다. 이후 중립 외교의 전통이 발전하는 역사적 배경 중 하나로 언급된다."),
        ("1648", "근세", "베스트팔렌 조약과 독립 인정", "유럽의 30년 전쟁을 끝낸 조약은 스위스 연합의 제국으로부터의 독립을 인정했다. 이는 유럽의 주권 국가 질서가 정비되는 과정과 연결된다."),
        ("1798", "근대", "헬베티아 공화국", "프랑스의 침공으로 기존 연방 체제가 무너지고 중앙집권적 공화국이 세워졌다. 개혁은 평등과 중앙 정부를 강조했지만 지역 자치 전통과 충돌해 불안정이 이어졌다."),
        ("1848", "근대", "연방 헌법 제정", "내전 이후 새로운 연방 헌법이 마련되어 현대 스위스 국가의 틀이 형성되었다. 연방제와 양원제, 직접민주주의 제도가 발전하면서 다양한 언어·종교 집단의 공존을 추구했다."),
        ("1914~1918", "현대", "제1차 세계대전 중 무장 중립", "스위스는 전쟁에 직접 참전하지 않았지만 동원과 경제적 어려움을 겪었다. 중립 정책은 인도주의 활동과 외교의 기반이 되었으나 국내 계층 간 갈등도 나타났다."),
        ("2002", "현대", "유엔 가입", "스위스는 국민투표를 거쳐 유엔에 가입했다. 오랫동안 국제기구의 본부와 외교 회담을 유치해 왔으며, 중립 정책과 국제 협력 사이의 관계를 새롭게 조정했다."),
    ]),
    "SWE": ("스웨덴", [
        ("1397", "중세", "칼마르 동맹", "덴마크·노르웨이·스웨덴이 한 군주 아래 결합했으나 각 왕국의 이해관계가 충돌했다. 동맹은 북유럽 정치의 협력과 갈등을 보여 주며, 스웨덴 독립 운동의 배경이 되었다."),
        ("1523", "근세", "구스타브 바사와 독립", "구스타브 바사가 덴마크 중심의 칼마르 동맹에서 벗어나 스웨덴 왕으로 즉위했다. 왕권과 국가 재정이 강화되고 종교개혁이 진행되면서 근대 스웨덴 국가의 기초가 마련되었다."),
        ("1611~1721", "근세", "스웨덴 제국 시대", "스웨덴은 발트해 주변에서 군사적 영향력을 확대해 유럽의 강국이 되었다. 전쟁과 징세 부담이 컸으며, 1700~1721년 대북방전쟁의 패배로 제국의 지위가 약화되었다."),
        ("1809", "근대", "핀란드 상실과 헌법 변화", "러시아와의 전쟁에서 패한 스웨덴은 핀란드를 잃었다. 같은 해 헌법 개혁은 왕권을 제한하고 의회와 행정의 역할을 재정비하는 계기가 되었다."),
        ("1814", "근대", "노르웨이와의 연합", "나폴레옹 전쟁 이후 스웨덴과 노르웨이가 군주를 공유하는 연합을 이루었다. 노르웨이는 자체 헌법과 의회를 유지했으며, 연합은 1905년 평화적으로 해체되었다."),
        ("19세기 후반~20세기 초", "근현대", "산업화와 대규모 이민", "산업화와 농업 구조 변화가 진행되는 동안 많은 스웨덴인이 북미 등으로 이주했다. 이후 노동조합과 사회민주주의가 성장해 복지국가 제도의 기반이 만들어졌다."),
        ("1930~1970년대", "현대", "복지국가 발전", "사회민주당 정부와 노동계·기업 간 협력이 복지 제도와 노동시장 정책을 발전시켰다. 보편적 복지와 높은 조세 부담을 결합한 모델은 국제적으로 주목받았다."),
        ("1995", "현대", "유럽연합 가입", "스웨덴은 국민투표 뒤 유럽연합에 가입했다. 다만 유로화 도입은 별도로 국민투표에서 부결되어 자국 통화를 유지했다."),
    ]),
    "NOR": ("노르웨이", [
        ("8~11세기", "중세", "바이킹 시대", "노르웨이와 스칸디나비아의 항해자들은 유럽 여러 지역으로 교역·정착·원정을 나갔다. 바이킹 활동은 해상 네트워크를 넓혔지만 약탈과 노예화도 동반했다."),
        ("872경", "중세", "노르웨이 통일 전승", "하랄 1세가 여러 지역을 통합했다는 전승이 전해진다. 실제 통일은 오랜 과정이었으며, 왕권이 지역 유력자들과 경쟁하며 점차 강화되었다."),
        ("1397", "중세", "칼마르 동맹", "노르웨이는 덴마크·스웨덴과 한 군주 아래 결합했다. 이후 덴마크 왕권의 영향이 커졌고 노르웨이의 독자적인 정치 활동은 제한되었다."),
        ("1814", "근대", "헌법 제정과 스웨덴 연합", "나폴레옹 전쟁 뒤 노르웨이는 독립을 시도하며 헌법을 제정했으나 스웨덴과 연합하게 되었다. 노르웨이는 의회와 헌법을 유지하며 자치권을 넓혔다."),
        ("1905", "근대", "평화적 독립", "국민투표와 협상을 통해 스웨덴과의 연합이 해체되었다. 노르웨이는 독립 왕국으로 국제 사회에 자리 잡았으며, 입헌군주제와 의회 정치를 발전시켰다."),
        ("1940~1945", "현대", "나치 독일의 점령", "독일이 노르웨이를 점령했고 왕실과 정부는 망명해 저항을 이어 갔다. 해상 교통과 전략 자원을 둘러싼 전쟁이 벌어졌고, 전후 안보 정책에 큰 영향을 주었다."),
        ("1969", "현대", "북해 유전 발견", "북해에서 석유가 발견된 뒤 석유·가스 산업이 국가 경제의 중요한 축이 되었다. 자원 수익을 장기적으로 관리하기 위해 국부펀드가 발전했지만 에너지 의존과 환경 문제도 논의되고 있다."),
        ("1994", "현대", "유럽연합 가입 국민투표 부결", "노르웨이는 국민투표에서 유럽연합 가입을 거부했다. 유럽경제지역 협정 등을 통해 경제 협력을 유지하면서도 주요 정책의 자율성을 보존하려는 선택을 했다."),
    ]),
    "DNK": ("덴마크", [
        ("8~11세기", "중세", "바이킹과 북해 교역", "덴마크의 항해자들은 북해와 발트해를 오가며 교역과 원정을 펼쳤다. 이 활동은 북유럽의 정치적 연결을 넓혔지만 약탈과 노예무역도 수반했다."),
        ("965경", "중세", "하랄 블루투스의 기독교 수용", "룬 문자 비문은 하랄 블루투스가 덴마크를 통합하고 기독교를 받아들였다고 전한다. 기독교화는 왕권 강화와 유럽 기독교 세계와의 관계 형성에 기여했다."),
        ("1397", "중세", "칼마르 동맹", "덴마크 왕실을 중심으로 스웨덴과 노르웨이가 결합했다. 동맹은 북유럽의 공동 대응을 목표로 했지만 각 지역의 이해관계가 달라 갈등이 계속되었다."),
        ("1536", "근세", "종교개혁과 루터교 국교화", "덴마크는 종교개혁을 통해 루터교를 국교로 삼고 교회 재산과 권한을 왕권 아래 두었다. 종교 변화는 행정과 교육, 사회생활에도 장기적인 영향을 미쳤다."),
        ("1849", "근대", "입헌군주제 도입", "헌법 제정으로 절대왕정이 끝나고 의회 정치가 발전하기 시작했다. 이후 보통선거 확대와 정당 정치의 발달을 거쳐 현대 민주주의 체제로 나아갔다."),
        ("1864", "근대", "프로이센·오스트리아와의 전쟁", "덴마크는 슐레스비히와 홀슈타인을 둘러싼 전쟁에서 패배해 영토를 잃었다. 패배 이후 덴마크는 군사적 팽창보다 내부 개혁과 농업 협동조합 발전에 집중했다."),
        ("1940~1945", "현대", "독일 점령과 저항", "독일군이 덴마크를 점령했지만 덴마크의 행정 체계는 한동안 제한적으로 유지되었다. 점령 후반에는 저항이 커졌고, 많은 덴마크 유대인이 스웨덴으로 탈출했다."),
        ("1973", "현대", "유럽공동체 가입", "덴마크는 국민투표를 거쳐 유럽공동체에 가입했다. 유럽 시장과의 경제적 연계가 강화되었으나 일부 통합 정책에는 예외와 국내 논쟁이 이어졌다."),
    ]),
    "UKR": ("우크라이나", [
        ("9~13세기", "중세", "키이우 루스", "키이우를 중심으로 동슬라브 지역의 정치·교역 네트워크가 발전했다. 988년 블라디미르 대공의 기독교 수용은 동방 정교 전통과 문자 문화 형성에 중요한 영향을 주었다."),
        ("1240", "중세", "몽골의 키이우 함락", "몽골군의 침공으로 키이우가 파괴되고 루스의 정치 중심이 분산되었다. 이후 우크라이나 지역은 여러 주변 세력의 경쟁과 지배를 경험했다."),
        ("1648", "근세", "흐멜니츠키 봉기", "코사크 지도자 보흐단 흐멜니츠키가 폴란드-리투아니아 연방에 맞서 봉기를 이끌었다. 사회적·종교적 갈등이 얽힌 이 사건은 코사크 국가의 형성과 러시아와의 관계 변화로 이어졌다."),
        ("1654", "근세", "페레야슬라프 협정", "코사크 지도부와 모스크바 차르국 사이의 협정은 이후 러시아와 우크라이나의 관계를 둘러싼 역사 해석에서 중요하게 다뤄진다. 협정의 의미와 주권 관계에 대해서는 역사학계에서도 다양한 해석이 존재한다."),
        ("18~19세기", "근대", "러시아·합스부르크 지배와 민족운동", "우크라이나 영토는 러시아 제국과 합스부르크 제국 등으로 나뉘어 지배되었다. 언어와 문화 활동이 제한되기도 했지만 문학·교육·정치 운동을 통해 근대 민족 정체성이 발전했다."),
        ("1917~1921", "근현대", "독립 시도와 내전", "러시아 제국 붕괴 뒤 여러 우크라이나 정부가 독립을 추구했으나 주변 세력과의 전쟁 및 내전으로 안정적인 국가를 세우기 어려웠다. 이후 대부분 지역은 소련에 편입되었다."),
        ("1932~1933", "현대", "홀로도모르 기근", "강제 집단화와 곡물 징발 등 스탈린 시기 정책 속에서 대규모 기근이 발생해 수많은 사람이 사망했다. 이 비극은 우크라이나 사회의 기억과 소련 체제에 대한 평가에 깊은 영향을 남겼다."),
        ("1986", "현대", "체르노빌 원전 사고", "체르노빌 원자력발전소 사고로 방사성 물질이 확산되어 우크라이나와 주변 지역에 장기적인 환경·보건 문제가 발생했다. 정보 통제와 늦은 대응은 소련 정부에 대한 불신을 키웠다."),
        ("1991", "현대", "독립 선언", "소련 해체 과정에서 우크라이나는 독립을 선언했고 국민투표에서 압도적인 지지를 얻었다. 이후 독립 국가의 제도와 경제를 정비하는 한편 러시아 및 유럽과의 관계를 둘러싼 논쟁이 이어졌다."),
        ("2014~현재", "현대", "크림반도 병합과 전쟁", "2014년 러시아가 크림반도를 병합하고 동부에서 무력 충돌이 시작되었다. 2022년 러시아의 전면 침공으로 전쟁이 크게 확대되어 민간인 피해와 난민, 유럽 안보 질서에 중대한 영향을 미치고 있다."),
    ]),
    "IRN": ("이란", [
        ("BC 550경", "고대", "아케메네스 페르시아 제국", "키루스 2세가 넓은 영토를 통합해 서아시아의 대제국을 세웠다. 여러 민족과 지역의 관습을 활용한 통치와 도로·행정망은 고대 제국 운영의 중요한 사례로 평가된다."),
        ("BC 330", "고대", "알렉산드로스의 페르시아 정복", "마케도니아의 알렉산드로스가 다리우스 3세를 무너뜨리고 페르시아 제국을 정복했다. 이후 헬레니즘 문화가 이란 지역에 유입되었지만 페르시아의 정치·문화 전통도 계속 이어졌다."),
        ("224", "고대", "사산 왕조 성립", "아르다시르 1세가 파르티아를 무너뜨리고 사산 왕조를 세웠다. 사산 왕조는 로마·비잔티움과 경쟁했고 조로아스터교와 페르시아 행정·예술 전통을 발전시켰다."),
        ("651", "중세", "아랍 이슬람 세력의 정복", "사산 왕조가 무너진 뒤 이슬람이 이란 지역에 확산되었다. 시간이 지나면서 페르시아어와 이란 문화는 이슬람 문명에 큰 영향을 주었고, 지역의 정체성도 새로운 종교와 결합해 변화했다."),
        ("1501", "근세", "사파비 왕조와 시아파 국교화", "이스마일 1세가 사파비 왕조를 세우고 열두 이맘파 시아 이슬람을 국가 종교로 삼았다. 이는 오늘날 이란의 종교적 정체성과 주변 수니파 국가들과의 관계를 형성하는 데 중요한 역할을 했다."),
        ("1905~1911", "근대", "입헌혁명", "상인·성직자·지식인 등 다양한 세력이 왕권을 제한하고 의회를 만들 것을 요구했다. 헌법과 의회가 도입되었지만 외세의 간섭과 국내 권력 갈등으로 개혁은 제한적으로 진행되었다."),
        ("1951~1953", "근대", "석유 국유화와 쿠데타", "모하마드 모사데그 총리는 석유 산업 국유화를 추진했으나 영국과 미국의 반발 속에 1953년 쿠데타로 실각했다. 이 사건은 이란의 주권과 외세 개입에 대한 기억에 큰 영향을 남겼다."),
        ("1979", "현대", "이란 혁명", "대규모 시위와 정치적 위기 끝에 팔레비 왕정이 무너지고 이슬람 공화국이 수립되었다. 혁명은 국내 사회 제도와 여성의 권리, 서방과의 관계를 크게 바꾸었다."),
        ("1980~1988", "현대", "이란-이라크 전쟁", "이라크의 침공으로 시작된 전쟁은 장기간 이어져 양국에 막대한 인명·경제적 피해를 남겼다. 전쟁 경험은 이란의 안보 정책과 혁명 체제의 정당성에 지속적인 영향을 주었다."),
    ]),
    "IRQ": ("이라크", [
        ("BC 3500경", "고대", "메소포타미아 도시 문명", "티그리스강과 유프라테스강 사이에서 수메르 도시국가들이 성장했다. 관개 농업과 도시 행정, 쐐기문자 기록은 국가와 문자의 발달을 보여 주는 중요한 사례다."),
        ("BC 2334경", "고대", "아카드 제국", "사르곤이 여러 도시국가를 통합해 초기 영토 국가의 하나를 세웠다. 다양한 지역을 연결한 통치 경험은 메소포타미아 정치사에 중요한 영향을 주었다."),
        ("BC 1792~1750경", "고대", "함무라비와 바빌로니아", "함무라비는 바빌론을 중심으로 세력을 확대하고 법 조항을 새긴 비문을 남겼다. 법전은 당시 사회의 계층과 재산, 가족 관계를 보여 주지만 모든 사람에게 같은 처벌이 적용된 것은 아니었다."),
        ("BC 911~609", "고대", "신아시리아 제국", "아시리아는 강력한 군대와 행정 체계를 통해 서아시아의 넓은 지역을 지배했다. 정복과 강제 이주가 사용되었고, 니네베의 궁전 부조와 문서들은 고대 제국의 권력과 문화를 보여 준다."),
        ("1258", "중세", "몽골의 바그다드 함락", "훌라구가 이끈 몽골군이 바그다드를 점령하면서 아바스 왕조의 칼리프 권력은 종말을 맞았다. 도시는 큰 피해를 입었고 서아시아의 정치·학문 중심 구조가 변화했다."),
        ("1534", "근세", "오스만 제국의 바그다드 장악", "오스만 제국은 사파비 이란과 경쟁하며 이라크 지역을 지배했다. 바그다드는 제국 간 전쟁의 요충지였고, 주민과 도시 경제는 반복되는 전쟁과 통치 변화의 영향을 받았다."),
        ("1920~1932", "근대", "영국 위임통치와 왕국 독립", "제1차 세계대전 후 오스만 제국의 영토가 재편되면서 영국의 영향 아래 이라크 왕국이 만들어졌다. 국경과 국가 제도는 식민 통치의 유산을 안고 있었고 석유와 정치적 대표성 문제가 계속되었다."),
        ("1958", "현대", "왕정 전복과 공화국", "군부 쿠데타로 하심 왕조가 무너지고 공화정이 선포되었다. 이후 이라크에서는 군부와 정당 사이의 권력 투쟁이 이어졌고, 1968년 바트당 집권으로 권위주의 통치가 강화되었다."),
        ("1980~1988", "현대", "이란-이라크 전쟁", "사담 후세인 정권의 이란 침공으로 전쟁이 시작되어 양국에 엄청난 피해가 발생했다. 전쟁은 이라크의 부채를 늘리고 군사화와 국가 통제를 강화하는 계기가 되었다."),
        ("2003", "현대", "이라크 전쟁과 정권 붕괴", "미국 주도 연합군의 침공으로 사담 후세인 정권이 무너졌다. 점령과 국가 기관 해체, 종파 갈등, 무장 단체의 확산은 장기간의 불안정과 민간인 피해로 이어졌다."),
    ]),
    "ISR": ("이스라엘·팔레스타인 지역", [
        ("BC 1천년기", "고대", "고대 이스라엘·유다 왕국", "레반트 지역에 이스라엘과 유다 왕국이 존재했으며, 이후 아시리아와 바빌로니아의 정복을 겪었다. 이 지역은 유대교와 기독교, 이슬람의 역사적 기억에서 중요한 장소가 되었다."),
        ("70", "고대", "예루살렘 제2성전 파괴", "로마에 맞선 유대 반란 진압 과정에서 예루살렘의 제2성전이 파괴되었다. 이는 유대교의 종교생활과 디아스포라 역사에 큰 영향을 준 사건으로 기억된다."),
        ("7세기", "중세", "이슬람 통치의 시작", "아랍 이슬람 세력이 레반트 지역을 정복한 뒤 예루살렘은 이슬람 세계의 중요한 종교 도시가 되었다. 이 지역에는 무슬림·기독교인·유대인 공동체가 시대별로 다른 조건 속에서 공존했다."),
        ("1099~1291", "중세", "십자군 국가와 전쟁", "서유럽에서 온 십자군이 예루살렘을 점령하고 여러 십자군 국가를 세웠다. 전쟁과 정복은 지역 주민들에게 큰 피해를 주었고, 이슬람 세력의 반격과 외교를 거쳐 십자군 지배가 끝났다."),
        ("19세기 후반", "근대", "시온주의와 아랍 민족운동", "유럽의 반유대주의와 민족주의 속에서 유대인의 민족적 고향을 세우려는 시온주의가 발전했다. 동시에 아랍 주민들의 정치적 권리와 자결을 요구하는 움직임도 나타나며 상충하는 민족적 요구가 형성되었다."),
        ("1917~1947", "근대", "영국 위임통치와 이민 확대", "제1차 세계대전 후 영국이 팔레스타인을 위임통치했다. 유대인 이민과 토지·정치 문제를 둘러싼 갈등이 커졌고, 영국의 정책 변화와 아랍·유대인 공동체의 충돌이 이어졌다."),
        ("1947~1949", "현대", "분할안·이스라엘 건국과 전쟁", "유엔은 팔레스타인 분할안을 권고했고 1948년 이스라엘이 건국을 선언한 뒤 주변 아랍 국가들과 전쟁이 벌어졌다. 많은 팔레스타인인이 난민이 되었고, 이 사건은 오늘날까지 이어지는 분쟁의 핵심 배경이다."),
        ("1967", "현대", "6일 전쟁", "이스라엘이 이집트·요르단·시리아와의 전쟁에서 가자지구와 서안지구, 동예루살렘 등 여러 지역을 점령했다. 점령지의 지위와 정착촌, 안보와 팔레스타인 자결권 문제가 이후 평화 협상의 핵심 쟁점이 되었다."),
        ("1993~1995", "현대", "오슬로 협정", "이스라엘과 팔레스타인해방기구가 상호 인정과 제한적 자치를 포함한 협정에 합의했다. 그러나 최종 지위 문제와 폭력, 불신이 해결되지 않아 독립 국가 수립과 평화 정착은 이루어지지 못했다."),
        ("2000~현재", "현대", "분쟁과 평화 협상의 난항", "봉기와 군사 충돌, 봉쇄와 정착촌 문제, 민간인 피해가 반복되었다. 이스라엘의 안보와 팔레스타인인의 자결권, 인도주의적 보호를 함께 고려한 정치적 해결이 국제 사회의 주요 과제로 남아 있다."),
    ]),
    "SAU": ("사우디아라비아", [
        ("1744", "근세", "디리야 동맹", "무함마드 이븐 사우드와 종교 지도자 무함마드 이븐 압둘 와하브의 동맹은 사우드 왕조의 세력 확대에 중요한 기반이 되었다. 종교와 정치 권력의 결합은 이후 사우디 국가 형성 과정에 지속적으로 영향을 주었다."),
        ("1744~1818", "근세", "제1차 사우드 국가", "중앙아라비아에서 사우드 세력이 확대되었으나 오스만 제국의 지원을 받은 이집트군의 원정으로 디리야가 파괴되었다. 이 국가의 흥망은 아라비아반도의 권력 경쟁을 보여 준다."),
        ("1902", "근대", "압둘아지즈의 리야드 탈환", "압둘아지즈 이븐 사우드가 리야드를 장악하고 사우드 왕조의 재건을 시작했다. 그는 부족과 지역 세력들을 통합하고 외교·군사 활동을 통해 국가의 영토를 확대했다."),
        ("1932", "현대", "사우디아라비아 왕국 수립", "압둘아지즈가 여러 지역을 통합해 사우디아라비아 왕국을 선포했다. 왕국은 이슬람 성지 메카와 메디나를 보유한 국가로서 종교적 영향력을 갖게 되었다."),
        ("1938", "현대", "상업적 석유 발견", "동부 지역에서 대규모 석유가 발견되면서 국가 경제와 국제 관계가 크게 변했다. 석유 수출 수익은 인프라와 복지 확대를 가능하게 했지만 세계 에너지 시장과 재정의 변동성에도 영향을 받게 했다."),
        ("1973~1974", "현대", "석유 금수와 에너지 위기", "아랍-이스라엘 전쟁 뒤 석유 수출국들의 금수 조치와 가격 상승이 세계 경제에 충격을 주었다. 사우디아라비아의 에너지 정책은 국제 외교와 석유 시장에서 큰 영향력을 갖게 되었다."),
        ("1990~1991", "현대", "걸프전", "이라크의 쿠웨이트 침공 이후 사우디아라비아는 국제 연합군의 주요 기지가 되었다. 외국군 주둔 문제는 국내 종교·정치 논쟁을 일으키고 이후 안보 정책에도 영향을 주었다."),
        ("2016~현재", "현대", "비전 2030과 경제 다변화", "정부는 석유 의존도를 낮추고 관광·기술·서비스 산업을 육성하는 개혁 계획을 추진하고 있다. 사회 변화와 경제 개방이 진행되는 동시에 노동권, 정치 참여, 인권 문제에 대한 논의도 계속되고 있다."),
    ]),
    "IDN": ("인도네시아", [
        ("7세기", "고대·중세", "스리위자야 해상 왕국", "수마트라를 중심으로 한 스리위자야는 말라카 해협의 교역로를 활용해 번영했다. 불교 학문과 해상 무역의 중심지로 성장하며 인도양과 동남아시아를 연결했다."),
        ("13~16세기", "중세", "마자파힛 왕국", "자바를 중심으로 한 마자파힛은 여러 섬에 영향력을 행사했다. 왕국의 실제 지배 범위는 지역마다 달랐지만, 이후 인도네시아의 역사적 정체성을 설명할 때 중요한 상징으로 활용된다."),
        ("13~16세기", "근세", "이슬람의 확산", "상인과 학자, 술탄국의 활동을 통해 이슬람이 여러 섬으로 확산되었다. 기존 힌두·불교·지역 전통과 결합한 다양한 문화가 형성되었고, 항구 도시가 무역의 중심으로 성장했다."),
        ("1602", "근세", "네덜란드 동인도회사 활동", "네덜란드 동인도회사는 향신료 무역을 통제하고 지역 통치자들과 조약·전쟁을 벌였다. 식민 경제는 수출 작물 생산과 강제 노동을 확대해 현지 사회와 토지 이용을 크게 바꾸었다."),
        ("1825~1830", "근세", "자바 전쟁", "디포네고로 왕자가 네덜란드 식민 통치에 맞서 대규모 전쟁을 이끌었다. 전쟁은 막대한 인명과 재정 피해를 남겼고 네덜란드의 직접 지배와 수탈 체제를 강화하는 결과를 낳았다."),
        ("1908~1942", "근대", "민족운동의 성장", "교육받은 지식인과 노동자·종교 단체가 식민 지배에 반대하는 조직을 만들었다. 수카르노와 하타 등 지도자들이 독립을 주장하며 인도네시아 민족주의가 확대되었다."),
        ("1945~1949", "현대", "독립 선언과 독립 전쟁", "일본의 항복 직후 수카르노와 하타가 독립을 선언했으나 네덜란드는 식민 통치를 되찾으려 했다. 무력 충돌과 외교 협상 끝에 1949년 네덜란드가 주권 이양을 인정했다."),
        ("1965~1967", "현대", "정권 변화와 대규모 폭력", "정치적 위기와 군부의 부상 속에서 공산당과 관련 있다고 여겨진 사람들을 포함한 대규모 학살과 탄압이 발생했다. 수하르토의 신질서 체제가 형성되어 장기간 권위주의 통치가 이어졌다."),
        ("1998", "현대", "수하르토 퇴진과 개혁 시대", "아시아 금융위기와 대중 시위 속에서 수하르토가 사임했다. 이후 선거·언론 자유와 지방분권 개혁이 진행되었지만 부패와 지역 갈등 등 해결해야 할 과제도 남았다."),
    ]),
    "VNM": ("베트남", [
        ("BC 3세기경", "고대", "반랑·어우락 전승", "베트남의 초기 국가에 관한 전승은 홍강 유역의 청동기 문화와 연결된다. 전승과 고고학 자료는 서로 구분해 살펴볼 필요가 있지만, 오늘날 베트남의 기원 서사에서 중요한 의미를 갖는다."),
        ("111 BC~939", "고대·중세", "중국 왕조의 지배와 저항", "한나라의 정복 이후 베트남 북부는 오랫동안 중국 왕조의 지배를 받았다. 행정·문자·유교 문화가 유입되었지만 지역 사회의 전통과 독자적인 정치 질서를 지키려는 저항도 반복되었다."),
        ("939", "중세", "독립 회복", "응오꾸옌이 박당강 전투에서 남한군을 물리치며 중국 왕조의 직접 지배에서 벗어나는 계기를 만들었다. 이후 베트남은 여러 왕조 아래 독립 국가 체제를 발전시켰다."),
        ("1010", "중세", "리 왕조와 탕롱 천도", "리 왕조의 리타이또가 수도를 탕롱(오늘날 하노이)으로 옮겼다. 중앙 행정과 불교 문화가 발전하고, 수도는 베트남 정치사의 중심지로 자리 잡았다."),
        ("13세기", "중세", "몽골·원 침입 격퇴", "쩐 왕조는 몽골과 원의 여러 차례 침입을 막아 냈다. 쩐흥다오가 이끈 저항은 베트남의 독립과 군사적 전통을 상징하는 사건으로 기억된다."),
        ("1858~1884", "근대", "프랑스의 식민 지배 확대", "프랑스군의 공격과 조약을 통해 베트남은 프랑스령 인도차이나에 편입되었다. 식민 경제와 교육 제도가 바뀌는 한편 토지 수탈과 정치적 억압에 반대하는 민족운동이 성장했다."),
        ("1945", "현대", "독립 선언과 8월 혁명", "일본의 항복으로 권력 공백이 생기자 베트민이 봉기를 일으켰고 호찌민이 독립을 선언했다. 그러나 프랑스가 식민 지배를 되찾으려 하면서 전쟁이 이어졌다."),
        ("1954", "현대", "디엔비엔푸 전투와 제네바 협정", "베트민이 프랑스군을 패배시키며 프랑스 식민 지배가 끝나는 계기가 되었다. 제네바 협정은 베트남을 잠정적으로 분할했고, 이후 남북 간 정치적 갈등이 심화되었다."),
        ("1955~1975", "현대", "베트남 전쟁", "북베트남과 남베트남, 미국 및 여러 외부 세력이 전쟁에 참여했다. 폭격과 지상전으로 민간인과 군인의 피해가 컸고, 전쟁은 냉전과 반전 운동, 동남아시아 사회에 큰 영향을 미쳤다."),
        ("1986", "현대", "도이머이 개혁", "베트남 공산당은 경제 개혁·개방 정책을 추진해 시장 요소를 확대하고 외국인 투자를 유치했다. 경제 성장과 국제 교류가 늘었지만 지역 격차와 노동·환경 문제도 중요한 과제가 되었다."),
    ]),
    "THA": ("태국", [
        ("1238경", "중세", "수코타이 왕국", "수코타이는 태국 역사에서 초기 타이족 왕국의 하나로 기억된다. 타이 문자 발전과 상좌부 불교의 후원은 이후 태국의 문화와 국가 정체성에 영향을 주었다."),
        ("1351", "중세", "아유타야 왕국", "아유타야는 동남아시아의 주요 무역·외교 중심지로 성장해 중국, 일본, 유럽 상인들과 교류했다. 왕국은 여러 세기 동안 번영했지만 주변국과의 전쟁도 반복했다."),
        ("1767", "근세", "아유타야 함락", "버마군의 공격으로 아유타야가 파괴되면서 왕국의 수도 체제가 무너졌다. 이후 딱신이 세력을 모아 새 왕조의 기반을 만들었고, 태국의 정치 중심은 재편되었다."),
        ("1782", "근세", "짜끄리 왕조와 방콕 건설", "라마 1세가 짜끄리 왕조를 세우고 수도를 방콕으로 옮겼다. 새 왕조는 행정과 왕권을 정비하고 주변국 및 서구 열강 사이에서 국가를 유지하려 했다."),
        ("19세기", "근대", "몽꿋·출랄롱꼰의 개혁", "시암은 서구 열강의 식민 팽창 속에서 외교와 행정, 군대, 교육 제도를 개혁했다. 영토 일부를 양보했지만 독립을 유지한 경험은 태국 근대 국가 형성의 핵심으로 평가된다."),
        ("1932", "현대", "입헌혁명", "군인과 민간 지식인들이 절대왕정을 끝내고 입헌군주제를 도입했다. 이후 태국 정치는 군부와 민간 정부, 왕실의 관계를 둘러싼 갈등과 쿠데타를 반복적으로 경험했다."),
        ("1941~1945", "현대", "제2차 세계대전과 일본군 진주", "일본군이 태국에 진주했고 태국 정부는 일본과 협력하는 한편 국내 저항 조직도 활동했다. 전후 태국은 미국과의 안보 협력을 강화하며 냉전 질서 속에서 위치를 정했다."),
        ("1997", "현대", "아시아 금융위기", "바트화 가치 하락과 금융 불안이 동남아시아를 넘어 세계 경제에 충격을 주었다. 위기는 금융 감독과 경제 구조의 취약성을 드러냈고 태국의 정치·경제 개혁 논의로 이어졌다."),
    ]),
    "PAK": ("파키스탄", [
        ("BC 2600경", "고대", "인더스 문명", "현재 파키스탄의 모헨조다로와 하라파는 계획도시와 배수 시설, 장거리 교역으로 유명하다. 문자는 아직 완전히 해독되지 않았으며, 이 문명은 남아시아 초기 도시 생활을 이해하는 핵심 자료다."),
        ("712", "중세", "아랍 세력의 신드 진출", "무함마드 빈 카심의 원정으로 신드 지역에 아랍 이슬람 세력이 들어왔다. 이후 이슬람은 여러 시기와 경로를 통해 확산되었으며, 지역의 종교·언어·정치 문화가 다양하게 변화했다."),
        ("1526", "근세", "무굴 제국의 성립", "바부르가 파니파트 전투에서 승리해 무굴 제국의 기반을 세웠다. 오늘날 파키스탄 지역은 무굴의 행정·건축·문화 교류 속에서 중요한 역할을 했다."),
        ("1857~1858", "근대", "세포이 항쟁과 영국 직접 통치", "인도 대반란 뒤 영국 동인도회사의 통치는 끝나고 영국 왕실의 직접 통치가 시작되었다. 식민 행정과 철도·관개 시설이 확대되었지만 정치적 대표성과 경제적 수탈을 둘러싼 갈등도 커졌다."),
        ("1906", "근대", "전인도 무슬림 연맹 창설", "무슬림 정치 지도자들이 별도의 정치 조직을 만들었다. 영국령 인도에서 대표권과 공동체의 권리를 둘러싼 논쟁이 커지면서 이후 파키스탄 건국 운동의 중요한 조직적 기반이 되었다."),
        ("1947", "현대", "파키스탄 독립과 분할", "영국령 인도가 인도와 파키스탄으로 분리 독립하면서 대규모 인구 이동과 종교 공동체 간 폭력이 발생했다. 새 국가는 동서로 떨어진 두 지역으로 구성되었고 정체성과 국가 운영 문제를 안게 되었다."),
        ("1971", "현대", "방글라데시 독립 전쟁", "동파키스탄에서 정치적 대표권과 언어·경제 차별 문제로 갈등이 격화되었다. 전쟁과 인도 개입 뒤 동파키스탄은 방글라데시로 독립해 파키스탄은 현재의 영토 구조가 되었다."),
        ("1977~1988", "현대", "지아 울하크 군사정권", "쿠데타로 집권한 지아 울하크는 이슬람화 정책을 추진하고 정치 활동을 제한했다. 아프가니스탄 전쟁과 냉전 외교가 파키스탄의 군사·사회 구조에 장기적인 영향을 주었다."),
        ("1998", "현대", "핵실험", "인도의 핵실험에 대응해 파키스탄도 핵실험을 실시했다. 남아시아의 핵 억지 관계가 강화되었지만 군비 경쟁과 핵 안전, 지역 안보에 대한 우려도 커졌다."),
    ]),
    "BGD": ("방글라데시", [
        ("8~12세기", "중세", "팔라·세나 왕조", "벵골 지역에서는 팔라 왕조의 불교 후원과 세나 왕조의 통치가 이어졌다. 이 지역은 불교 학문과 힌두 문화, 농업과 강 유역 교역이 만나는 공간이었다."),
        ("13세기", "중세", "벵골의 이슬람 왕조", "델리 술탄조의 영향과 독립적인 벵골 술탄국의 등장 속에서 이슬람이 확산되었다. 농경지 개간과 강 유역 정착이 진행되며 벵골어 문화가 발전했다."),
        ("1757", "근대", "플라시 전투", "영국 동인도회사가 벵골의 나와브 세력을 물리치면서 벵골에 대한 정치·경제적 지배를 확대했다. 세금 징수와 무역 통제의 변화는 식민 경제의 형성과 지역 사회에 큰 영향을 주었다."),
        ("1905·1911", "근대", "벵골 분할과 취소", "영국은 행정 편의를 내세워 벵골을 분할했지만 반대 운동과 정치적 저항이 커졌다. 분할은 취소되었으나 종교·지역 정체성을 둘러싼 정치가 더욱 복잡해졌다."),
        ("1947", "현대", "동파키스탄 편입", "영국령 인도의 분할로 벵골 동부는 파키스탄의 일부가 되었다. 서파키스탄과 지리적으로 떨어져 있었고 언어·경제·정치적 대표권 문제로 갈등이 쌓였다."),
        ("1952", "현대", "벵골어 운동", "우르두어만을 국가 언어로 삼으려는 정책에 반대해 학생과 시민들이 벵골어의 공식 지위를 요구했다. 희생자들은 언어권과 문화적 정체성을 상징하게 되었고, 이후 방글라데시 독립운동에 영향을 주었다."),
        ("1971", "현대", "독립 전쟁과 방글라데시 건국", "총선 결과와 권력 이양 갈등, 군부의 탄압 속에서 독립 전쟁이 발생했다. 인도 개입과 파키스탄군의 항복으로 방글라데시는 독립했으며 전쟁은 막대한 인명 피해와 난민을 남겼다."),
        ("1991", "현대", "의회 민주주의 회복", "대중 시위로 군사 통치가 끝나고 의회 중심의 정치 체제가 회복되었다. 이후 선거 경쟁과 정치적 대립이 이어졌지만 민주 제도와 시민사회가 국가 운영의 중요한 요소가 되었다."),
        ("2000년대~현재", "현대", "의류 산업 성장과 기후 위기", "의류 수출 산업은 고용과 경제 성장에 큰 역할을 했다. 동시에 노동자의 안전과 임금, 홍수·해수면 상승 등 기후 변화에 대한 취약성이 중요한 사회적 과제로 남아 있다."),
    ]),
    "ETH": ("에티오피아", [
        ("BC 1천년기~1세기", "고대", "악숨 문명의 성장", "악숨은 홍해 무역망을 통해 아라비아와 로마 세계를 연결한 왕국으로 성장했다. 비문과 주화, 거대한 석비는 중앙 권력과 교역, 문자 문화의 발달을 보여 준다."),
        ("4세기", "고대", "기독교 수용", "악숨 왕국은 기독교를 받아들여 에티오피아 정교회 전통의 기반을 마련했다. 이 종교 전통은 주변 지역과 구별되는 문화적 정체성 형성에 오랫동안 영향을 주었다."),
        ("13세기", "중세", "솔로몬 왕조", "예쿠노 암락 이후 솔로몬 왕조가 등장해 에티오피아의 왕권과 기독교 전통을 연결했다. 왕조는 종교 기관과 토지 지배를 통해 국가 권력을 유지했다."),
        ("1529~1543", "근세", "아달 술탄국과의 전쟁", "아흐마드 이븐 이브라힘 알가지가 이끈 군대와 에티오피아 왕국 사이에 전쟁이 벌어졌고, 포르투갈 지원군도 개입했다. 전쟁은 지역의 종교·정치 질서와 인구 이동에 큰 영향을 주었다."),
        ("1896", "근대", "아드와 전투", "메넬리크 2세가 이끄는 에티오피아군이 이탈리아군을 물리쳤다. 에티오피아는 유럽 식민 지배를 피한 아프리카 국가의 상징이 되었지만 이후에도 외교적 압박과 내부 개혁 과제를 안고 있었다."),
        ("1935~1941", "근대", "이탈리아의 침공과 점령", "파시스트 이탈리아가 에티오피아를 침공해 점령했고, 주민들은 저항 운동을 이어 갔다. 국제연맹의 대응 실패는 집단 안보 체제의 한계를 드러냈다."),
        ("1974", "현대", "군주제 폐지와 데르그 집권", "군부 중심의 혁명으로 하일레 셀라시에 황제가 폐위되었다. 새 정권은 사회주의 정책과 토지 개혁을 추진했으나 정치적 탄압과 내전, 기근이 이어졌다."),
        ("1983~1985", "현대", "대기근과 국제 구호", "가뭄과 전쟁, 정책 실패가 겹치며 대규모 기근이 발생했다. 국제 구호 활동이 확대되었고, 기근은 농촌 취약성과 정부 정책, 국제 지원의 역할에 대한 논의를 불러왔다."),
        ("1991", "현대", "데르그 정권 붕괴", "반정부 무장 세력이 수도를 장악해 데르그 정권이 무너졌다. 이후 에티오피아는 민족 연방제를 도입했지만 지역 정체성과 중앙 정부 권한을 둘러싼 갈등이 계속되었다."),
    ]),
    "ZAF": ("남아프리카공화국", [
        ("1652", "근세", "케이프 식민 거점", "네덜란드 동인도회사가 케이프에 보급 기지를 세웠다. 유럽인 정착과 토지 점유가 확대되면서 현지 공동체와의 갈등, 노예제와 인종적 위계가 형성되었다."),
        ("1806", "근대", "영국의 케이프 장악", "나폴레옹 전쟁 시기 영국이 케이프를 장악했다. 영국의 통치와 법 제도 변화는 보어인과 아프리카 현지 공동체, 노예제 폐지 문제를 둘러싼 갈등을 키웠다."),
        ("1830~1840년대", "근대", "대이주", "일부 보어인이 영국 지배를 피해 내륙으로 이동해 여러 공화국을 세웠다. 이 과정에서 현지 아프리카 사회와의 전쟁과 토지 점유가 발생해 지역의 정치 지형이 바뀌었다."),
        ("1899~1902", "근대", "보어 전쟁", "영국과 보어 공화국 사이의 전쟁은 금·다이아몬드 자원과 제국 지배를 둘러싼 경쟁과 연결되었다. 전쟁 뒤 영국의 영향력이 확대되었고 민간인 수용소와 인종 정책의 문제도 드러났다."),
        ("1910", "근대", "남아프리카 연방 수립", "영국 식민지와 보어 공화국이 연합해 남아프리카 연방을 만들었다. 자치 정부가 수립되었지만 정치적 권리는 주로 백인에게 제한되었고 흑인 다수의 토지·참정권은 크게 제약되었다."),
        ("1948", "현대", "아파르트헤이트 제도화", "국민당 정부는 인종 분리와 차별을 법과 행정으로 강화했다. 주거·교육·이동·정치 참여가 인종에 따라 제한되었고, 국내 저항과 국제 제재가 확대되었다."),
        ("1960", "현대", "샤프빌 학살", "통행증 법에 반대하는 시위에서 경찰 발포로 많은 사람이 사망했다. 이 사건은 아파르트헤이트에 대한 국제적 비판을 키우고 정부가 저항 단체를 탄압하는 계기가 되었다."),
        ("1990~1994", "현대", "아파르트헤이트 종식과 민주 선거", "넬슨 만델라 석방과 협상으로 인종차별 법제가 해체되었고 1994년 모든 인종이 참여한 민주 선거가 실시되었다. 만델라가 대통령이 되었지만 경제적 불평등과 과거의 상처를 해결하는 과제가 남았다."),
    ]),
    "NGA": ("나이지리아", [
        ("11~19세기", "중세·근세", "하우사·카넴보르누·요루바 국가들", "오늘날 나이지리아 지역에는 여러 도시국가와 왕국이 성장해 사하라 횡단 무역과 농업, 금속 공예를 발전시켰다. 지역마다 언어·종교·정치 제도가 달라 하나의 단일한 역사로만 설명하기 어렵다."),
        ("15~19세기", "근세", "베냉 왕국과 해안 무역", "베냉 왕국은 정교한 청동·황동 조각과 중앙집권적 궁정 문화로 알려져 있다. 대서양 무역이 확대되면서 유럽 상인과의 교류가 늘었고, 지역 사회는 노예무역과 정치적 경쟁의 영향을 받았다."),
        ("16~19세기", "근세", "대서양 노예무역", "나이지리아 해안과 내륙의 여러 정치 세력이 대서양 노예무역에 연결되었다. 수많은 사람이 강제로 끌려갔고 지역 사회의 인구·경제·정치 구조에 장기적인 피해가 남았다."),
        ("1861~1900", "근대", "영국의 식민 지배 확대", "영국은 라고스를 장악한 뒤 내륙으로 영향력을 확대했다. 식민 행정은 지역별 통치 방식을 결합했으며 자원 수탈과 국경 설정이 이후 국가 통합 문제에 영향을 주었다."),
        ("1914", "근대", "북부·남부 보호령 통합", "영국은 북부와 남부 보호령을 하나의 식민 행정 단위로 통합했다. 다양한 민족·종교·언어 집단을 포함한 국경은 독립 이후 정치 대표와 자원 배분 문제에 지속적인 영향을 주었다."),
        ("1960", "현대", "독립", "나이지리아는 영국으로부터 독립했으며 연방제를 통해 다양한 지역을 하나의 국가로 묶으려 했다. 지역 정당과 민족·종교 정체성, 석유 수익 배분이 정치적 갈등의 주요 쟁점이 되었다."),
        ("1967~1970", "현대", "비아프라 전쟁", "동부 지역의 분리 독립 선언으로 내전이 발생했다. 봉쇄와 기근을 포함한 인도주의적 위기가 심각했으며, 전쟁은 국가 통합과 지역 자치 문제에 깊은 상처를 남겼다."),
        ("1960년대 후반~현재", "현대", "석유 산업과 환경·분배 문제", "니제르델타의 석유 개발은 국가 수입을 늘렸지만 오염과 생계 피해, 수익 분배 갈등을 일으켰다. 석유 의존을 줄이고 지역 주민의 권리와 환경을 보호하는 문제가 주요 과제로 남아 있다."),
        ("1999", "현대", "민간 민주 정부 출범", "군사 통치 이후 선거를 통해 민간 정부가 들어섰다. 민주 제도가 지속되고 있지만 부패, 안보 불안, 지역 불평등, 경제 다변화 문제를 해결해야 하는 상황이다."),
    ]),
    "MEX": ("멕시코", [
        ("BC 1200경", "고대", "올멕 문명", "멕시코만 연안에서 올멕 문명이 성장해 거대한 석상과 의례 중심지를 남겼다. 이후 메소아메리카 여러 사회의 종교·예술·정치 문화에 영향을 주었다고 여겨진다."),
        ("250~900", "고대", "마야 문명 전성기", "마야 도시국가들은 정교한 달력과 수학, 문자, 천문 지식을 발전시켰다. 마야 지역은 하나의 통일 제국이 아니라 서로 경쟁하고 교류한 여러 도시국가로 구성되었다."),
        ("1325", "중세", "테노치티틀란 건설", "멕시카인(아즈텍)이 호수 위에 테노치티틀란을 세우고 주변 지역과 동맹·정복을 통해 세력을 키웠다. 도시의 시장과 수로, 조공 체계는 복잡한 도시 문명을 보여 준다."),
        ("1519~1521", "근세", "스페인의 아즈텍 정복", "에르난 코르테스는 원주민 동맹 세력과 함께 아즈텍 제국을 무너뜨렸다. 전쟁과 천연두 등 전염병, 식민 지배로 인구와 사회 구조가 급격히 변화했다."),
        ("1810~1821", "근대", "독립 전쟁", "미겔 이달고의 봉기로 시작된 독립운동은 여러 사회 집단이 참여한 장기 전쟁으로 이어졌다. 1821년 독립이 성립했지만 새 국가의 정치 체제와 사회적 불평등을 둘러싼 갈등은 계속되었다."),
        ("1846~1848", "근대", "미국-멕시코 전쟁", "전쟁에서 패한 멕시코는 과달루페 이달고 조약으로 현재 미국 서남부의 광대한 영토를 넘겼다. 이 사건은 양국 관계와 국경, 멕시코의 국가 정체성에 큰 영향을 주었다."),
        ("1858~1861", "근대", "개혁 전쟁", "자유주의자와 보수주의자가 교회·군대의 특권과 국가 제도를 두고 싸웠다. 베니토 후아레스는 헌법과 세속 국가 원칙을 추진했으며, 이후 프랑스 개입과 제국 수립으로 갈등이 이어졌다."),
        ("1910~1920", "현대", "멕시코 혁명", "독재와 토지 불평등에 반대하는 봉기가 확산되어 마데로, 사파타, 판초 비야 등 여러 세력이 참여했다. 혁명은 헌법과 토지 개혁, 노동권 논의를 바꾸었지만 폭력과 권력 경쟁도 동반했다."),
        ("1994", "현대", "북미자유무역협정 발효와 치아파스 봉기", "북미자유무역협정은 멕시코·미국·캐나다의 경제 통합을 강화했다. 같은 해 치아파스의 사파티스타 봉기는 원주민 권리와 빈곤, 세계화의 혜택 분배 문제를 국제적으로 부각했다."),
    ]),
    "CAN": ("캐나다", [
        ("수천 년 전~현재", "선사·현대", "원주민 사회와 문화", "유럽인이 도착하기 오래전부터 현재 캐나다 지역에는 다양한 원주민 국가와 공동체가 존재했다. 언어·정치 제도·교역망은 지역마다 달랐으며, 식민화 이후 토지 상실과 강제 동화 정책의 영향을 받았다."),
        ("1534", "근세", "자크 카르티에의 탐험", "프랑스 탐험가 카르티에는 세인트로렌스강 유역을 탐사하며 프랑스의 영유권 주장을 강화했다. 이후 프랑스와 영국의 식민 경쟁이 심화되었고 원주민 공동체와의 동맹·갈등도 이어졌다."),
        ("1608", "근세", "퀘벡 건설", "사뮈엘 드 샹플랭이 퀘벡을 세워 프랑스 식민 활동의 거점을 만들었다. 모피 무역과 선교, 원주민 동맹이 식민지의 성장에 중요했으며 프랑스어 문화의 기반이 형성되었다."),
        ("1756~1763", "근세", "7년 전쟁과 영국 지배 확대", "프랑스와 영국의 전쟁에서 프랑스가 패하면서 뉴프랑스 대부분이 영국의 지배 아래 들어갔다. 프랑스어권 주민의 권리와 종교, 법률을 어떻게 보장할지가 이후 캐나다 정치의 중요한 문제로 남았다."),
        ("1867", "근대", "캐나다 연방 성립", "온타리오·퀘벡·노바스코샤·뉴브런즈윅이 연방을 구성했다. 이후 서부와 북부로 영토가 확대되었으며, 연방 정부와 주 정부의 권한 및 프랑스어권·원주민 권리 문제가 계속 논의되었다."),
        ("1885", "근대", "대륙횡단철도 완공과 북서부 저항", "철도는 동부와 서부를 연결해 이주와 무역을 촉진했지만 원주민의 토지와 생활 방식을 크게 바꾸었다. 메티스 공동체의 저항은 연방 정부의 서부 확장과 원주민 권리를 둘러싼 갈등을 드러냈다."),
        ("1914~1918", "현대", "제1차 세계대전 참전", "캐나다군은 영국 제국의 일원으로 전쟁에 참여했고, 전쟁은 캐나다의 국제적 위상과 자치 요구를 강화했다. 동시에 징병제를 둘러싼 프랑스어권과 영어권 사이의 갈등도 나타났다."),
        ("1969", "현대", "공식 언어법", "연방 차원에서 영어와 프랑스어를 공식 언어로 인정하는 정책이 강화되었다. 이는 이중언어 국가 정체성을 제도화하려는 시도였으며 퀘벡의 자치와 언어권 논쟁과 연결되었다."),
        ("1982", "현대", "헌법 귀속과 권리헌장", "캐나다는 영국 의회로부터 헌법 개정 권한을 넘겨받고 캐나다 권리·자유 헌장을 헌법에 포함했다. 시민의 기본권과 연방 체계가 새롭게 정비되었지만 퀘벡의 헌법적 지위 논쟁은 계속되었다."),
    ]),
    "ARG": ("아르헨티나", [
        ("16세기", "근세", "스페인 식민 지배", "스페인은 리오데라플라타 지역에 식민 행정과 교역망을 구축했다. 원주민 사회는 정복과 질병, 토지 점유의 영향을 받았고 식민 경제는 유럽과 대서양 무역에 연결되었다."),
        ("1810", "근대", "5월 혁명", "부에노스아이레스에서 스페인 왕권의 권위가 흔들리는 가운데 자치 정부가 수립되었다. 이 사건은 리오데라플라타 지역의 독립운동을 촉진했지만 독립 이후에도 지방과 중앙의 권력 갈등이 계속되었다."),
        ("1816", "근대", "독립 선언", "투쿠만 회의가 스페인으로부터 독립을 선언했다. 독립 세력은 주변 지역의 해방 전쟁을 이어 갔으며, 새 국가의 경계와 정치 제도를 정하는 과정은 수십 년간 이어졌다."),
        ("1853", "근대", "헌법 제정", "연방 헌법은 중앙 권력과 지방 자치의 관계를 규정하고 국가 통합의 틀을 마련했다. 부에노스아이레스와 내륙 지방 사이의 갈등은 한동안 계속되었지만 이후 수출 경제와 이민이 성장했다."),
        ("1880~1930", "근대", "농축산 수출과 대규모 이민", "육류·곡물 수출과 철도 건설, 유럽 이민으로 아르헨티나 경제와 도시가 빠르게 성장했다. 그러나 토지 소유의 집중과 노동 조건, 원주민 영토 침탈은 불평등과 사회 갈등을 남겼다."),
        ("1946~1955", "현대", "페론주의", "후안 페론 정부는 노동자의 권리와 복지 정책, 국가의 경제 개입을 강조했다. 노동계의 정치적 영향력이 커졌지만 권위주의 논란과 경제 문제, 사회적 양극화도 나타났다."),
        ("1976~1983", "현대", "군사독재와 더러운 전쟁", "군사정권은 반정부 인사와 시민을 불법 구금·실종시키는 탄압을 벌였다. 민주화 이후 진실 규명과 책임자 처벌, 피해자 기억을 위한 노력이 중요한 사회 과제가 되었다."),
        ("1982", "현대", "포클랜드 전쟁", "군사정권은 국내 위기를 만회하려 포클랜드 제도를 침공했으나 영국에 패했다. 패전은 군사정권의 정당성을 약화시키고 민주화 전환을 앞당겼다."),
        ("1983", "현대", "민주주의 회복", "라울 알폰신 정부 출범으로 민간 민주 정부가 회복되었다. 군사정권의 인권 침해를 조사하고 책임을 묻는 재판은 국제 인권사에서 중요한 사례가 되었지만 경제 위기는 계속되었다."),
    ]),
    "CHL": ("칠레", [
        ("고대~근세", "선사·근세", "원주민 사회와 마푸체", "오늘날 칠레 지역에는 아타카마 등 여러 원주민 사회가 존재했고 남부의 마푸체는 잉카와 스페인의 팽창에 저항했다. 지역별 환경에 적응한 생활 방식과 정치 조직이 발달했다."),
        ("1541", "근세", "산티아고 건설", "페드로 데 발디비아가 산티아고를 세우며 스페인 식민 지배의 거점을 만들었다. 스페인 세력은 남부로 확장하려 했지만 마푸체의 저항으로 장기간 전쟁과 국경 갈등이 이어졌다."),
        ("1810~1818", "근대", "독립 전쟁", "스페인 왕권의 위기 속에서 자치 운동이 시작되어 독립 전쟁으로 발전했다. 베르나르도 오이긴스와 호세 데 산마르틴 등이 독립군을 이끌었고, 1818년 독립이 확립되었다."),
        ("1879~1884", "근대", "태평양 전쟁", "칠레는 페루·볼리비아와의 전쟁에서 승리해 질산염이 풍부한 북부 영토를 확보했다. 자원 수출은 경제를 성장시켰지만 볼리비아의 내륙국화와 지역 관계의 긴장을 남겼다."),
        ("1925", "근대", "새 헌법과 정교 분리", "헌법 개정으로 대통령제와 국가 제도가 재정비되고 교회와 국가의 관계가 분리되었다. 그러나 노동 문제와 정치적 양극화가 계속되며 여러 차례 제도 개혁이 논의되었다."),
        ("1970", "현대", "아옌데 정부 출범", "살바도르 아옌데는 선거를 통해 사회주의를 지향하는 정부를 이끌며 구리 산업 국유화와 사회 개혁을 추진했다. 정책과 경제 위기, 국내외 갈등이 심화되면서 정치적 대립이 커졌다."),
        ("1973~1990", "현대", "피노체트 군사독재", "군부 쿠데타로 아옌데 정부가 무너지고 피노체트 정권이 들어섰다. 정권은 정치적 탄압과 인권 침해를 자행했고 시장 중심 경제 개혁을 추진했으며, 민주화 이후 진실 규명과 제도 개혁이 이어졌다."),
        ("1988~1990", "현대", "국민투표와 민주화", "1988년 국민투표에서 피노체트의 집권 연장안이 부결되었고, 이후 선거를 통해 민간 정부가 출범했다. 민주화는 인권 침해의 기억과 경제적 불평등 문제를 해결해야 하는 과제를 남겼다."),
    ]),
    "PER": ("페루", [
        ("BC 900경~BC 200", "고대", "차빈 문화", "안데스 지역의 차빈 문화는 종교 의례와 예술 양식, 교류망으로 넓은 지역에 영향을 주었다. 고대 안데스 사회가 서로 연결되어 있었음을 보여 주는 중요한 고고학 자료다."),
        ("100~800", "고대", "모체 문명", "모체 사회는 관개 농업과 금속 공예, 도자기 제작을 발전시켰다. 무덤과 벽화는 당시의 권력 구조와 의례, 전쟁 문화를 이해하는 자료가 된다."),
        ("1438~1533", "중세·근세", "잉카 제국", "파차쿠티 등 통치자들이 안데스 산맥을 따라 넓은 제국을 형성했다. 도로망과 창고, 노동 동원 체계가 발달했지만 정복 지역의 주민들은 제국에 노동과 자원을 제공해야 했다."),
        ("1532~1572", "근세", "스페인의 잉카 정복", "프란시스코 피사로 일행은 내전과 질병, 현지 동맹을 활용해 잉카 권력을 무너뜨렸다. 식민 통치와 은광 개발, 강제 노동은 원주민 사회와 인구에 심각한 영향을 미쳤다."),
        ("1780~1781", "근세", "투팍 아마루 2세 봉기", "원주민과 메스티소 주민들의 불만 속에서 세금과 강제 노동에 반대하는 대규모 봉기가 일어났다. 봉기는 진압되었지만 식민 지배의 불평등과 독립운동의 배경을 드러냈다."),
        ("1821~1824", "근대", "독립 선언과 독립 전쟁", "호세 데 산마르틴이 독립을 선언하고 시몬 볼리바르의 군대가 전쟁을 이어 갔다. 아야쿠초 전투의 승리로 스페인의 남아메리카 지배가 결정적으로 약화되었다."),
        ("1879~1883", "근대", "태평양 전쟁과 영토 상실", "페루는 칠레와의 전쟁에서 패해 남부의 자원 지역을 잃고 경제적 위기를 겪었다. 패전은 국가 재정과 정치 질서를 흔들었고 군부와 민간 정치 세력의 경쟁을 심화했다."),
        ("1968~1975", "현대", "군사정부의 토지 개혁", "후안 벨라스코 알바라도 정부는 대토지 소유를 개혁하고 일부 산업을 국유화했다. 개혁은 농촌 사회의 권력 관계를 바꾸었지만 경제적 어려움과 정치적 반발도 일으켰다."),
        ("1980~2000", "현대", "내전과 민주주의의 위기", "정부군과 빛나는 길 등 무장 조직의 충돌로 많은 민간인이 피해를 입었다. 빈곤과 차별, 국가 폭력이 얽힌 이 시기의 경험은 진실 규명과 피해자 회복을 위한 과제로 남아 있다."),
    ]),
    "AUS": ("오스트레일리아", [
        ("최소 6만 년 전부터", "선사·현대", "원주민 사회의 역사", "오스트레일리아 원주민과 토레스 해협 섬 주민은 유럽인의 도착 이전부터 다양한 언어와 지식, 토지 관리 전통을 발전시켰다. 식민화 이후 토지 박탈과 강제 동화 정책이 큰 피해를 남겼으며 원주민 권리 회복은 현재도 중요한 과제다."),
        ("1770", "근세", "쿡의 동부 해안 탐사", "제임스 쿡은 영국을 위해 동부 해안을 탐사하고 영유권을 주장했다. 그러나 이 땅에는 이미 원주민 사회가 존재했으며, 유럽의 영유권 주장은 이후 식민 정착과 토지 박탈의 근거로 사용되었다."),
        ("1788", "근대", "영국 식민지 건설", "영국의 죄수 수송선단이 시드니 코브에 도착해 식민 정착을 시작했다. 식민지 확장은 원주민의 토지와 생계에 큰 영향을 주었고 질병·폭력·강제 이주가 발생했다."),
        ("1851~1890년대", "근대", "골드러시와 이민 확대", "금 발견으로 인구가 빠르게 증가하고 도시와 철도, 금융 산업이 성장했다. 다양한 지역에서 이민자가 유입되었지만 중국계 이민자 차별과 원주민 배제도 함께 나타났다."),
        ("1901", "근대", "오스트레일리아 연방 성립", "여러 식민지가 연방으로 통합되어 오스트레일리아 연방이 만들어졌다. 새 국가는 의회 제도를 정비했지만 초기 이민 정책은 백인 중심으로 설계되어 인종 차별을 제도화했다."),
        ("1914~1918", "현대", "제1차 세계대전과 갈리폴리", "오스트레일리아군은 영국 제국의 일원으로 전쟁에 참전했고 갈리폴리 전투는 국가 기억의 상징이 되었다. 전쟁은 국가 정체성과 군 복무 전통을 강화했지만 많은 희생을 남겼다."),
        ("1967", "현대", "원주민 관련 국민투표", "국민투표로 연방 정부가 원주민과 관련한 법률을 만들고 인구 조사에 포함할 수 있도록 헌법이 개정되었다. 이는 권리 확대 운동의 중요한 성과였지만 실질적 불평등 해소는 계속 과제로 남았다."),
        ("1975", "현대", "백인 중심 이민 정책의 종식", "전후 수십 년에 걸쳐 이민 정책이 바뀌면서 인종에 따른 이민 제한이 점차 폐지되었다. 다문화 사회로의 전환이 진행되었고 아시아·중동 등 다양한 지역에서 이민자가 늘어났다."),
        ("2008", "현대", "원주민에 대한 공식 사과", "케빈 러드 총리는 과거 강제 분리 정책으로 피해를 입은 원주민, 특히 도둑맞은 세대에 대해 의회에서 공식 사과했다. 사과는 화해 과정의 상징이 되었지만 건강·교육·사회적 격차 해소는 계속 과제로 남아 있다."),
    ]),
    "NZL": ("뉴질랜드", [
        ("13~14세기경", "중세", "마오리인의 정착", "폴리네시아 항해자들이 뉴질랜드에 정착해 마오리 사회와 부족 공동체를 발전시켰다. 언어·구전 역사·토지와 조상에 대한 관계는 마오리 정체성의 중요한 부분이다."),
        ("1642", "근세", "아벨 타스만의 유럽인 탐사", "네덜란드 항해자 아벨 타스만이 유럽인으로서는 처음으로 뉴질랜드를 기록했다. 이후 유럽과의 접촉은 교역과 선교, 질병 확산, 토지 경쟁을 가져왔다."),
        ("1769", "근세", "제임스 쿡의 탐사", "쿡의 항해는 유럽의 지도 제작과 이후 식민 활동을 확대했다. 유럽인의 기록은 마오리 사회에 대한 정보를 남겼지만, 식민 지배의 관점과 원주민의 관점을 구분해 읽을 필요가 있다."),
        ("1840", "근대", "와이탕이 조약", "영국 왕실과 여러 마오리 족장들이 조약에 서명했다. 영어본과 마오리어본의 표현 차이로 주권과 토지 권리에 대한 해석이 달라졌고, 조약의 의미는 오늘날에도 정치·법적 논쟁의 중심에 있다."),
        ("1860~1870년대", "근대", "뉴질랜드 전쟁", "토지와 주권을 둘러싸고 영국 식민 정부와 마오리 집단 사이에 무력 충돌이 벌어졌다. 전쟁과 몰수로 마오리 공동체는 큰 피해를 입었고 토지 권리 회복 운동의 배경이 되었다."),
        ("1893", "근대", "여성 참정권", "뉴질랜드는 국가 단위 선거에서 여성에게 투표권을 부여한 최초의 자치국가로 알려져 있다. 케이트 셰퍼드 등 참정권 운동가들의 활동은 국제 여성 참정권 운동에 영향을 주었다."),
        ("1907", "근대", "자치령 지위", "뉴질랜드는 대영제국 내 자치령이 되며 자치권을 확대했다. 외교·국방과 헌법 관계가 점진적으로 변화하면서 독립적인 국가 정체성이 발전했다."),
        ("1987", "현대", "마오리어법", "마오리어를 공식 언어로 인정하는 법이 제정되었다. 언어 revitalization과 교육·방송 확대는 식민화 과정에서 약화된 마오리 언어와 문화를 회복하려는 노력의 일부다."),
    ]),
    "MNG": ("몽골", [
        ("1206", "중세", "칭기즈 칸과 몽골 제국", "테무친이 여러 몽골 부족을 통합해 칭기즈 칸으로 추대되었다. 몽골군은 기동력과 조직력을 바탕으로 유라시아에 걸친 제국을 확대했으며, 정복 과정에서 큰 파괴와 인구 피해도 발생했다."),
        ("13세기", "중세", "몽골 제국의 유라시아 교역", "제국의 광대한 영토는 동서 교역과 사절·기술·지식의 이동을 촉진했다. 이른바 팍스 몽골리카 시기에도 지역별 전쟁과 강제 동원, 전염병 확산의 영향이 함께 존재했다."),
        ("1368", "중세", "원나라의 중국 지배 종식", "명나라가 대도를 점령하면서 원 왕조는 중국 본토의 지배를 잃었다. 몽골 세력은 초원 지역에서 계속 정치적 역할을 했으며, 이후 여러 세력으로 분화하고 재편되었다."),
        ("17세기", "근세", "청 제국의 몽골 지배 확대", "몽골의 여러 집단이 청 왕조와 관계를 맺거나 지배 아래 들어갔다. 청은 지역의 종교와 귀족 제도를 활용해 통치했으며, 몽골의 정치적 자율성은 시기와 지역에 따라 달랐다."),
        ("1911", "근대", "독립 선언", "청 왕조가 붕괴하는 가운데 외몽골 지도자들이 독립을 선언했다. 러시아와 중국의 이해관계가 얽혀 독립의 국제적 지위는 복잡했고, 이후 소련의 영향력이 커졌다."),
        ("1921", "근대", "혁명과 독립 유지", "몽골 혁명 세력은 소련의 지원을 받아 중국군과 백군 세력을 몰아냈다. 이후 인민정부가 수립되어 사회주의 국가로 나아가는 기반이 마련되었다."),
        ("1924", "현대", "몽골 인민공화국", "군주제가 폐지되고 몽골 인민공화국이 선포되었다. 소련식 정치·경제 제도가 도입되었으며 종교 기관과 전통 사회는 국가 정책의 큰 영향을 받았다."),
        ("1990~1992", "현대", "민주화와 시장경제 전환", "대중 시위와 정치 개혁으로 일당 지배가 끝나고 다당제 선거와 새 헌법이 도입되었다. 민주화 이후 시장경제 전환과 자원 개발이 진행되었지만 경제 의존과 지역 격차가 과제로 남았다."),
    ]),
    "KHM": ("캄보디아", [
        ("802", "중세", "앙코르 왕조의 시작", "자야바르만 2세가 여러 세력을 결합해 앙코르 왕조의 기초를 세웠다고 전해진다. 이후 크메르 제국은 관개 시설과 사원 건축을 발전시키며 동남아시아의 주요 세력으로 성장했다."),
        ("12세기", "중세", "앙코르와트 건설", "수리야바르만 2세 시기에 건설된 앙코르와트는 힌두교 사원으로 시작해 이후 불교 성지로도 기능했다. 건축과 부조는 크메르 왕권, 종교, 노동 동원과 예술 수준을 보여 준다."),
        ("13~15세기", "중세", "앙코르의 변화와 수도 이동", "환경 변화와 전쟁, 교역 경로의 변화 등 여러 요인이 겹치며 앙코르의 정치적 중심성이 약화되었다. 크메르 사회가 갑자기 사라진 것은 아니며 수도와 권력 중심이 다른 지역으로 이동했다."),
        ("1863", "근대", "프랑스 보호령", "캄보디아 왕실은 시암과 베트남의 압박 속에서 프랑스의 보호를 받아들였다. 프랑스령 인도차이나에 편입되면서 식민 행정과 경제 구조가 바뀌었고 독립운동의 배경이 형성되었다."),
        ("1953", "현대", "독립", "노로돔 시아누크의 외교·정치 활동을 통해 캄보디아는 프랑스로부터 독립했다. 독립 뒤 중립 외교를 추구했지만 베트남 전쟁과 주변국의 충돌이 국내 정치에 영향을 주었다."),
        ("1975~1979", "현대", "크메르 루주 통치와 대량 학살", "폴 포트가 이끈 크메르 루주는 도시 주민을 강제 이주시켜 농업 집단화를 추진했다. 처형·기아·질병과 강제 노동으로 엄청난 인명 피해가 발생했고, 사회와 가족 공동체에 깊은 상처가 남았다."),
        ("1979~1991", "현대", "전쟁과 평화 협상", "베트남군의 개입으로 크메르 루주 정권은 무너졌지만 내전과 국제적 갈등이 계속되었다. 1991년 파리 평화협정은 유엔의 지원 아래 정치적 해결과 선거로 나아가는 길을 열었다."),
        ("1993", "현대", "입헌군주제 복원", "유엔의 지원 아래 선거가 실시되고 입헌군주제가 복원되었다. 전후 재건이 진행되었지만 과거 범죄의 책임 규명과 정치적 자유, 경제적 불평등 문제는 계속 논의되고 있다."),
    ]),
    "PHL": ("필리핀", [
        ("900경", "중세", "라구나 동판 비문", "라구나 동판 비문은 10세기경 필리핀 군도에 문자와 법적·무역 관계가 존재했음을 보여 준다. 이 자료는 유럽 식민지 이전에도 동남아시아와 연결된 복잡한 사회가 있었음을 알려 준다."),
        ("14~16세기", "중세", "항구 공동체와 이슬람 술탄국", "필리핀 군도의 여러 항구 공동체는 중국·말레이 세계와 교역했다. 민다나오와 술루 지역에서는 이슬람 술탄국이 성장했으며, 지역마다 정치·종교 전통이 다양했다."),
        ("1521", "근세", "마젤란 원정대 도착", "마젤란 원정대가 군도에 도착했으나 마젤란은 막탄 전투에서 사망했다. 이 접촉은 이후 스페인의 식민 팽창과 기독교 선교, 지역 저항의 역사로 이어졌다."),
        ("1565~1898", "근세", "스페인 식민 지배", "스페인은 마닐라를 중심으로 식민 통치를 구축하고 멕시코와 연결된 갈레온 무역을 운영했다. 가톨릭이 널리 확산되었지만 세금과 강제 노동, 토지 제도는 지역 사회에 부담을 주었다."),
        ("1896~1898", "근대", "필리핀 혁명", "안드레스 보니파시오와 에밀리오 아기날도 등이 스페인 지배에 맞서 독립운동을 이끌었다. 혁명은 식민 통치에 대한 저항과 필리핀 민족주의의 성장을 보여 주었다."),
        ("1898~1902", "근대", "미국-필리핀 전쟁", "미국은 스페인과의 전쟁 뒤 필리핀을 지배하려 했고 독립 세력과 무력 충돌이 벌어졌다. 전쟁은 민간인 피해와 강제 이주를 낳았으며 미국 식민 통치가 이어지는 계기가 되었다."),
        ("1942~1945", "현대", "일본 점령과 해방", "제2차 세계대전 중 일본군이 필리핀을 점령했고 게릴라 저항과 연합군의 반격이 이어졌다. 마닐라 전투 등으로 큰 피해가 발생했으며 전후 독립과 재건의 과제가 남았다."),
        ("1946", "현대", "독립", "필리핀은 미국으로부터 독립했다. 독립 이후에도 토지 불평등과 농촌 빈곤, 정치 가문의 영향력, 미국과의 안보·경제 관계가 국가 발전의 주요 쟁점으로 남았다."),
        ("1986", "현대", "피플 파워 혁명", "대규모 시민 시위와 군부 일부의 이탈로 페르디난드 마르코스 정권이 무너지고 코라손 아키노 정부가 출범했다. 비폭력 시민 행동의 상징이 되었지만 빈곤과 부패, 정치적 폭력 문제는 계속되었다."),
    ]),
})




# 추가 국가 20개: 역사 사건은 연도·배경·전개·영향을 함께 설명합니다.
HISTORY.update({
    "IRL": ("아일랜드", [
        ("5세기", "고대·중세", "기독교의 확산", "전승에서 성 패트릭과 연결되는 기독교 선교는 아일랜드의 종교 문화와 문자 기록 전통에 영향을 주었다. 수도원은 라틴어 학문과 필사 문화를 보존하는 중심지가 되었으며, 지역 왕국 사이의 경쟁은 계속되었다."),
        ("1169~1171", "중세", "앵글로노르만의 개입", "잉글랜드의 지원을 받은 노르만 세력이 아일랜드에 진출하면서 섬의 정치 구조가 바뀌기 시작했다. 이후 잉글랜드 왕권의 영향은 시기와 지역에 따라 달랐으며, 토지 소유와 종교를 둘러싼 갈등이 장기간 이어졌다."),
        ("1541", "근세", "아일랜드 왕국 선포", "잉글랜드의 헨리 8세는 아일랜드 왕을 자칭하던 지위를 왕국으로 격상했다. 왕권 확대와 개신교 정책은 가톨릭을 믿는 다수 주민 및 게일계 귀족과 충돌했고, 토지 몰수와 정착 정책이 갈등을 키웠다."),
        ("1641~1653", "근세", "반란과 크롬웰 정복", "1641년 반란과 이어진 전쟁 뒤 올리버 크롬웰의 군사 원정 및 토지 몰수가 진행되었다. 많은 주민이 죽거나 이주했고 토지 소유 구조가 바뀌어, 종교·민족·재산의 불평등이 이후 정치에 깊은 흔적을 남겼다."),
        ("1798", "근대", "아일랜드 반란", "연합 아일랜드인 협회는 종파를 넘어 정치 개혁과 독립을 추구하며 봉기를 일으켰다. 반란은 진압되었지만 영국 지배에 대한 저항 전통과 1801년 연합법을 둘러싼 논쟁을 강화했다."),
        ("1845~1852", "근대", "대기근", "감자 역병과 식량·토지 제도의 취약성이 겹치며 대규모 기근이 발생했다. 사망과 해외 이주가 급증했고, 영국 정부의 대응에 대한 비판은 민족주의와 독립운동의 성장에 영향을 주었다."),
        ("1916~1922", "현대", "부활절 봉기와 독립", "1916년 더블린 봉기는 처음에는 지지를 널리 얻지 못했지만 지도자 처형 이후 여론이 바뀌었다. 독립전쟁과 영국-아일랜드 조약을 거쳐 아일랜드 자유국이 수립되었으며, 북아일랜드의 지위와 조약 찬반 문제는 분단과 내전으로 이어졌다."),
        ("1998", "현대", "벨파스트 협정", "북아일랜드의 민족주의·연합주의 세력과 영국·아일랜드 정부가 권력 공유와 협력을 위한 협정에 합의했다. 폭력의 종식을 위한 중요한 기반이 되었지만 정체성, 치안, 국경 문제는 계속 정치적 쟁점으로 남았다."),
    ]),
    "BEL": ("벨기에", [
        ("기원전 1세기", "고대", "로마의 갈리아 정복", "오늘날 벨기에 지역은 로마의 갈리아 속주에 포함되었고 도로·도시·군사 거점이 발달했다. 로마 지배는 라틴 문화와 교역망을 확산시켰지만 지역 사회의 변화는 장소마다 달랐다."),
        ("843", "중세", "베르됭 조약 이후 저지대 지역", "카롤루스 대제의 제국이 분할된 뒤 저지대 지역은 여러 왕국과 공국의 경계에 놓였다. 브뤼헤와 겐트 같은 도시는 직물 생산과 교역으로 성장해 중세 유럽 경제의 중요한 중심지가 되었다."),
        ("15~16세기", "근세", "합스부르크령 네덜란드", "저지대 지역은 합스부르크 왕가의 지배 아래 무역과 예술이 번성했다. 동시에 종교개혁과 중앙집권 정책이 갈등을 일으켰고, 북부와 남부의 정치적 경로가 점차 달라졌다."),
        ("1795~1815", "근대", "프랑스 지배와 나폴레옹 전쟁", "프랑스 혁명기 프랑스가 오늘날 벨기에 지역을 병합하면서 행정·법률·교회 제도가 바뀌었다. 나폴레옹 패전 뒤 빈 회의는 이 지역을 네덜란드와 결합했지만 종교·정치적 불만이 남았다."),
        ("1830~1831", "근대", "벨기에 독립", "브뤼셀의 봉기 뒤 벨기에는 네덜란드로부터 독립을 선언하고 입헌군주제를 채택했다. 유럽 열강의 외교적 합의는 신생 국가의 중립 지위를 뒷받침했으며, 프랑스어권과 네덜란드어권의 관계는 이후 정치의 중요한 쟁점이 되었다."),
        ("1885~1908", "근대", "콩고 자유국과 식민 지배", "레오폴 2세의 사유 지배 아래 콩고에서 고무와 상아 채취가 강압적으로 이루어졌고 폭력과 인권 침해가 발생했다. 국제적 비판 뒤 벨기에 국가가 콩고를 직접 통치했으며, 식민 지배의 유산은 오늘날까지 역사적 책임 논의의 대상이다."),
        ("1914~1918", "현대", "제1차 세계대전 점령", "독일의 벨기에 침공은 중립국 침략으로 국제적 논란을 일으켰다. 전투와 점령으로 민간인이 피해를 입고 산업 기반이 파괴되었으며, 전후 벨기에는 재건과 안보 협력에 힘썼다."),
        ("1957~1993", "현대", "유럽 통합과 연방국가화", "벨기에는 유럽경제공동체 창설에 참여해 브뤼셀이 유럽 기관의 중심지로 성장하는 데 기여했다. 네덜란드어권과 프랑스어권 사이의 언어·지역 갈등을 조정하기 위해 권한을 지역과 공동체로 나누는 연방 개혁이 진행되었다."),
    ]),
    "CZE": ("체코", [
        ("9세기", "중세", "대모라비아와 기독교 문화", "대모라비아는 중부 유럽의 초기 슬라브 정치체 중 하나였다. 키릴과 메토디우스의 선교 전통은 슬라브어 예배와 문자 문화의 역사에서 중요하게 다뤄진다."),
        ("10세기", "중세", "보헤미아 공국", "프르셰미슬 왕조 아래 보헤미아는 신성로마제국과 관계를 맺으며 정치적 기반을 강화했다. 프라하는 종교·무역·행정의 중심지로 성장했고, 기독교 제도와 왕권이 발전했다."),
        ("1346~1378", "중세", "카를 4세 시대", "보헤미아 왕이자 신성로마제국 황제였던 카를 4세는 프라하를 제국의 주요 중심지로 발전시켰다. 프라하 대학교 설립과 건축 사업은 학문과 도시 문화의 성장을 촉진했다."),
        ("1419~1434", "근세", "후스 전쟁", "얀 후스의 종교 개혁 사상과 처형 이후 보헤미아에서 종교·사회적 갈등이 무력 충돌로 번졌다. 전쟁은 교회 권위와 신앙 개혁을 둘러싼 유럽의 논쟁에 영향을 주었다."),
        ("1620", "근세", "백산 전투와 합스부르크 지배 강화", "보헤미아 반란군이 합스부르크군에 패배하면서 왕권과 종교 정책이 재편되었다. 귀족 재산 몰수와 재가톨릭화가 진행되었고, 체코어와 지역 엘리트의 지위에도 장기적 영향을 주었다."),
        ("1918", "현대", "체코슬로바키아 수립", "제1차 세계대전에서 오스트리아-헝가리 제국이 붕괴하면서 체코와 슬로바키아 지도자들은 독립 국가를 세웠다. 새 공화국은 산업 기반과 의회 제도를 갖췄지만 민족 집단 사이의 차이를 조정해야 했다."),
        ("1938~1939", "현대", "뮌헨 협정과 독일 점령", "뮌헨 협정으로 주데텐란트가 독일에 넘어갔고 이듬해 나머지 체코 지역도 독일에 점령되었다. 주권 상실과 나치 탄압은 전쟁 후 국가 재건과 안보 인식에 큰 영향을 주었다."),
        ("1968~1989", "현대", "프라하의 봄과 벨벳 혁명", "알렉산데르 둡체크의 개혁 시도는 바르샤바 조약군의 침공으로 중단되었다. 1989년 대규모 비폭력 시위인 벨벳 혁명으로 공산당 지배가 끝났고, 1993년 체코와 슬로바키아는 평화적으로 분리되었다."),
    ]),
    "HUN": ("헝가리", [
        ("895경~1000", "중세", "마자르 정착과 왕국 수립", "마자르 집단이 카르파티아 분지에 정착한 뒤 이슈트반 1세가 기독교 왕국을 세웠다. 왕권과 교구 조직의 정비는 헝가리를 중세 유럽의 정치·종교 질서에 연결했다."),
        ("1241~1242", "중세", "몽골 침입", "몽골군의 침입은 헝가리의 인구와 정착지에 큰 피해를 주었다. 벨러 4세는 성곽 건설과 도시 재건을 추진했고, 이 경험은 방어 체계와 왕권 정책을 바꾸었다."),
        ("1458~1490", "중세", "마티아시 1세의 통치", "마티아시 코르비누스는 왕권과 군대를 강화하고 르네상스 문화와 학문을 후원했다. 그의 궁정은 중부 유럽의 문화 교류에 기여했지만 재정 부담도 남겼다."),
        ("1526", "근세", "모하치 전투와 분할", "오스만군이 헝가리군을 격파한 뒤 왕국은 합스부르크 지배 지역, 오스만 지배 지역, 트란실바니아 공국으로 나뉘었다. 이 분할은 종교·문화와 정치 경계에 수 세기 동안 영향을 주었다."),
        ("1848~1849", "근대", "혁명과 독립 시도", "라요시 코슈트 등을 중심으로 헝가리 혁명 세력이 합스부르크 지배에 맞서 헌법과 자치를 요구했다. 혁명은 러시아군의 개입으로 진압되었지만 민족주의와 자치 요구를 강화했다."),
        ("1867", "근대", "오스트리아-헝가리 타협", "타협으로 이중제국이 성립하고 헝가리는 내정에서 큰 자치권을 얻었다. 산업화와 도시화가 진행되었으나 제국 내 다른 민족들의 자치 요구와 정치적 긴장은 계속되었다."),
        ("1920", "현대", "트리아농 조약", "제1차 세계대전 패전 뒤 헝가리는 영토와 인구의 상당 부분을 잃었다. 새 국경은 주변국과의 관계 및 헝가리 민족 정체성에 오랫동안 영향을 주었다."),
        ("1956~1989", "현대", "혁명과 체제 전환", "1956년 봉기는 소련의 개입으로 진압되었지만 공산권 통치의 한계를 드러냈다. 1989년 헝가리는 다당제와 시장경제로 전환하고 중부 유럽의 민주화 흐름에 참여했다."),
    ]),
    "ROU": ("루마니아", [
        ("106", "고대", "다키아 정복", "트라야누스 황제의 로마군이 다키아 일부를 정복했다. 로마의 도시·군사·언어 문화가 영향을 주었지만 이후 지역의 인구와 문화는 여러 집단의 이동과 교류 속에서 형성되었다."),
        ("14세기", "중세", "왈라키아·몰다비아 공국", "카르파티아 남쪽과 동쪽에서 공국들이 성장해 헝가리·폴란드·오스만 사이에서 자율성을 지키려 했다. 지역 통치자들은 조공과 외교, 군사적 저항을 병행했다."),
        ("1600", "근세", "미하이 용감공의 일시적 통합", "미하이 용감공은 왈라키아·몰다비아·트란실바니아를 잠시 통합했다. 통합은 오래가지 않았지만 후대 루마니아 민족주의에서 통일의 상징으로 기억되었다."),
        ("1859~1866", "근대", "공국 통합과 국가 형성", "왈라키아와 몰다비아가 알렉산드루 이오안 쿠자의 통치 아래 결합했고, 이후 루마니아라는 국가 체제가 발전했다. 토지 개혁과 행정 현대화가 추진되었지만 사회적 불평등은 남았다."),
        ("1877~1878", "근대", "독립 전쟁", "루마니아는 러시아-오스만 전쟁에 참여해 오스만 제국으로부터 독립을 국제적으로 인정받았다. 독립은 외교적 지위를 강화했지만 다민족 지역의 경계 문제는 계속되었다."),
        ("1918", "현대", "대루마니아 형성", "제1차 세계대전 말 오스트리아-헝가리와 러시아 제국이 붕괴하면서 트란실바니아와 베사라비아 등 여러 지역이 루마니아와 결합했다. 영토 확대는 국가 정체성을 강화하는 한편 소수민족 문제를 복잡하게 했다."),
        ("1947~1989", "현대", "공산주의 정권", "전후 소련의 영향 아래 공산 정권이 수립되었고 산업화와 집단농장화, 정치적 탄압이 진행되었다. 니콜라에 차우셰스쿠의 독재는 생활 통제와 경제 위기를 심화시켰다."),
        ("1989", "현대", "혁명과 민주화", "대중 시위와 군 내부의 이탈 속에서 차우셰스쿠 정권이 무너졌다. 이후 다당제와 시장경제로 전환했으며, 과거 공산 정권의 책임과 경제 전환의 비용이 중요한 과제로 남았다."),
    ]),
    "FIN": ("핀란드", [
        ("12~13세기", "중세", "스웨덴의 영향 확대", "스웨덴 왕국의 동쪽 확장과 기독교 선교로 오늘날 핀란드 지역은 스웨덴의 정치·종교 체계와 연결되었다. 지역 사회는 농업과 발트해 무역을 통해 성장했고 스웨덴어 행정 전통이 자리 잡았다."),
        ("1809", "근대", "러시아 제국의 대공국", "스웨덴이 러시아와의 전쟁에서 패한 뒤 핀란드는 러시아 제국의 자치 대공국이 되었다. 자체 행정과 법 제도를 일부 유지했으며, 핀란드어 문화와 민족 의식이 성장했다."),
        ("1899~1905", "근대", "러시아의 러시아화 정책과 저항", "러시아 제국이 자치권을 제한하려 하자 핀란드에서 언론·시민운동과 정치적 저항이 커졌다. 이 시기는 독립운동과 의회 제도의 발전에 중요한 배경이 되었다."),
        ("1917", "현대", "독립 선언", "러시아 혁명으로 제국 권력이 약화되자 핀란드는 독립을 선언했다. 독립 직후 적군과 백군 사이의 내전이 발생해 사회적 상처를 남겼지만, 이후 의회 민주주의 제도가 발전했다."),
        ("1939~1944", "현대", "겨울전쟁과 계속전쟁", "소련과의 전쟁에서 핀란드는 영토를 잃었지만 독립을 유지했다. 전쟁은 국가 안보와 외교의 방향에 영향을 주었고 전후에는 소련과의 관계를 신중하게 관리했다."),
        ("1948", "현대", "핀란드-소련 우호협력조약", "조약은 전후 핀란드의 외교·안보 정책에 제약을 주면서도 독립적인 제도와 시장경제를 유지할 수 있는 틀을 마련했다. 이 균형 외교는 냉전기 핀란드의 특징으로 알려졌다."),
        ("1995", "현대", "유럽연합 가입", "핀란드는 유럽연합에 가입해 경제·정치 협력을 강화했다. 복지국가와 교육 제도를 발전시키는 동시에 유럽의 안보 변화와 러시아와의 관계를 조정해 왔다."),
        ("2023", "현대", "북대서양조약기구 가입", "러시아의 우크라이나 침공 이후 안보 환경이 바뀌면서 핀란드는 오랜 군사적 비동맹 정책을 전환해 NATO에 가입했다. 이는 북유럽과 유럽 안보 질서의 변화를 보여 준다."),
    ]),
    "AFG": ("아프가니스탄", [
        ("기원전 6~4세기", "고대", "아케메네스·헬레니즘 세계", "오늘날 아프가니스탄 지역은 페르시아 제국의 동쪽 영역과 교역로에 포함되었다. 알렉산드로스의 정복 이후 그리스계 왕국과 중앙아시아·인도 문화가 만나 다양한 종교와 예술 전통이 발전했다."),
        ("1~3세기", "고대", "쿠샨 제국과 실크로드", "쿠샨 제국은 중앙아시아와 인도 북부를 연결하며 불교 미술과 장거리 교역을 후원했다. 바미얀과 간다라 지역의 문화는 그리스·이란·인도 전통이 융합된 사례로 평가된다."),
        ("7~10세기", "중세", "이슬람의 확산", "아랍 정복과 이후 왕조들의 통치 속에서 이슬람이 점차 확산되었다. 지역의 언어·종교·정치 전통은 한 번에 바뀐 것이 아니라 도시와 농촌, 지역별로 서로 다른 속도로 변화했다."),
        ("1747", "근세", "두라니 왕조와 국가 형성", "아흐마드 샤 두라니가 여러 부족과 지역 세력을 결합해 왕조를 세웠다. 이 왕조는 아프가니스탄 국가 형성의 중요한 출발점으로 여겨지지만 중앙 정부의 권력은 지역마다 다르게 작동했다."),
        ("1839~1919", "근대", "영국-아프가니스탄 전쟁", "영국과 러시아의 중앙아시아 경쟁 속에서 아프가니스탄은 여러 차례 영국과 전쟁을 치렀다. 외세의 영향과 국내 권력 투쟁이 맞물렸으며, 1919년 전쟁 뒤 외교적 독립을 확보했다."),
        ("1979~1989", "현대", "소련 침공과 전쟁", "소련군의 개입은 정부군과 무자헤딘 세력 사이의 전쟁을 확대했다. 대규모 난민과 인명 피해, 인프라 파괴가 발생했고 전쟁은 냉전 국제정치와 주변국의 개입을 불러왔다."),
        ("1996~2001", "현대", "첫 탈레반 정권", "탈레반은 내전 속에서 카불을 장악하고 엄격한 사회 규제를 시행했다. 여성과 소녀의 교육·노동·공적 생활이 크게 제한되었고, 국제적으로 고립된 정권이 되었다."),
        ("2001~2021", "현대", "국제 개입과 공화정", "2001년 이후 국제 개입으로 새 헌정 체제가 만들어지고 교육·보건 분야에 변화가 있었지만 부패와 안보 불안, 지역 불평등이 계속되었다. 2021년 탈레반이 다시 권력을 장악하면서 국가 제도와 시민권을 둘러싼 위기가 심화되었다."),
    ]),
    "NPL": ("네팔", [
        ("기원전 6~5세기", "고대", "룸비니와 불교 전통", "전통에 따르면 고타마 싯다르타는 오늘날 네팔의 룸비니에서 태어났다. 룸비니는 불교 순례의 중요한 장소가 되었고 남아시아 종교·문화 교류의 역사를 보여 준다."),
        ("4~8세기", "고대·중세", "리차비 왕조", "리차비 왕조 시기 비문과 조각은 카트만두 계곡에서 행정·종교·예술 문화가 발전했음을 보여 준다. 인도와 티베트 사이의 교역과 불교·힌두교 전통이 함께 영향을 미쳤다."),
        ("1768~1769", "근세", "프리트비 나라얀 샤의 통일", "고르카 왕국의 프리트비 나라얀 샤가 카트만두 계곡을 정복해 통일 왕국의 기반을 만들었다. 다양한 민족과 언어를 가진 지역이 하나의 국가로 묶이면서 중앙 통치와 지역 자치의 관계가 중요한 문제가 되었다."),
        ("1814~1816", "근대", "영국-네팔 전쟁", "전쟁 뒤 수가울리 조약으로 네팔의 영토가 줄었고 영국은 네팔의 외교에 큰 영향력을 행사했다. 네팔은 완전한 식민지가 되지는 않았지만 영국과의 관계 속에서 군사·외교 정책을 조정했다."),
        ("1846~1951", "근대", "라나 가문 통치", "코트 학살 이후 라나 가문이 세습 총리 체제를 구축해 왕권을 제한하고 실권을 장악했다. 교육과 정치 참여가 제한되었으며, 반대 운동과 해외의 민주주의 사상이 개혁 요구를 키웠다."),
        ("1951", "현대", "라나 통치 종식과 정치 개방", "대중 운동과 왕실의 움직임으로 라나 체제가 끝나고 정당 정치가 시작되었다. 그러나 왕권과 정당 사이의 갈등으로 민주 제도가 안정적으로 정착하기까지 여러 차례 정치적 변동이 이어졌다."),
        ("1996~2006", "현대", "마오주의 내전", "마오주의 반군과 정부군의 충돌로 많은 주민이 사망하거나 이주했다. 전쟁은 농촌 빈곤과 사회적 배제 문제를 부각했고, 2006년 평화 협정과 정치 개혁으로 이어졌다."),
        ("2008", "현대", "공화국 선포", "제헌의회는 군주제를 폐지하고 연방 민주 공화국을 선포했다. 새 헌법과 연방제 도입 과정에서 민족·지역 대표성, 권력 분배, 재난 복구가 중요한 과제로 남았다."),
    ]),
    "LKA": ("스리랑카", [
        ("기원전 3세기", "고대", "불교 수용", "데바남피야 티사 왕 시기에 불교가 전해졌다는 전승이 있으며, 불교 수도원과 왕권은 이후 섬의 정치·문화에 깊은 영향을 주었다. 관개 저수지와 농업 체계가 발전하면서 고대 왕국의 경제 기반이 강화되었다."),
        ("5세기", "고대", "시기리야와 왕권 문화", "카샤파 왕과 연결되는 시기리야 유적은 궁전·벽화·정원 설계의 뛰어난 사례다. 이 유적은 고대 스리랑카의 기술과 예술, 왕권의 상징 정치를 보여 준다."),
        ("11~13세기", "중세", "폴론나루와 왕국", "폴론나루와는 관개 시설과 불교 건축이 발전한 수도였다. 남인도 세력과의 전쟁, 농업 생산과 왕실 후원은 국가의 흥망을 좌우했으며 유적은 오늘날 주요 문화유산으로 남아 있다."),
        ("1505~1815", "근세", "포르투갈·네덜란드·영국의 영향", "유럽 열강은 해상 무역과 계피 등 상품을 둘러싸고 해안 지역을 장악했다. 내륙의 캔디 왕국은 한동안 독립을 유지했지만 1815년 영국에 병합되면서 섬 전체가 식민 지배 아래 들어갔다."),
        ("1931", "근대", "보통선거권 도입", "도너모어 헌법은 아시아 식민지 가운데 이른 시기에 넓은 보통선거권을 도입했다. 자치 제도와 정당 정치가 발전했지만 민족·언어 공동체 사이의 대표성과 권력 분배 문제는 남았다."),
        ("1948", "현대", "독립", "실론은 영국으로부터 독립했으며 의회 제도를 이어받았다. 독립 이후 시민권과 언어 정책을 둘러싼 갈등이 커졌고, 타밀계와 싱할라계 공동체 사이의 긴장이 정치적 문제로 발전했다."),
        ("1956", "현대", "싱할라어 단독 공용어 정책", "싱할라어를 공용어로 정한 정책은 다수 집단의 언어 정체성을 강화했지만 타밀어 사용자들의 소외감을 키웠다. 언어·교육·고용 기회에 대한 갈등은 이후 민족 갈등의 한 배경이 되었다."),
        ("1983~2009", "현대", "내전", "정부와 타밀 엘람 해방호랑이(LTTE) 사이의 내전은 장기간 이어지며 민간인 사망과 이주, 인권 침해를 낳았다. 전쟁은 2009년 정부군 승리로 끝났지만 실종자 문제와 화해, 소수자 권리 문제가 계속 논의되고 있다."),
    ]),
    "MMR": ("미얀마", [
        ("849경", "중세", "바간 왕국의 성장", "바간은 이라와디강 유역의 농업과 교역을 바탕으로 성장했다. 아나우라타 왕과 연결되는 불교 후원 전통 아래 수많은 사원과 탑이 건립되었고, 상좌부 불교는 지역의 정치·문화에 큰 영향을 주었다."),
        ("1287경", "중세", "바간 왕국의 쇠퇴", "몽골 세력의 침입과 내부 정치·경제적 변화가 겹치며 바간의 통합 권력이 약해졌다. 이후 여러 지역 왕국이 경쟁했고, 미얀마의 정치 통합은 반복적인 전쟁과 재편을 거쳤다."),
        ("1752~1885", "근세", "꼰바웅 왕조와 영국 전쟁", "알라웅파야가 세운 꼰바웅 왕조는 영토를 확대했지만 영국과의 세 차례 전쟁 끝에 1885년 왕국이 병합되었다. 식민 행정과 쌀 수출 경제의 확대는 사회 구조와 토지 소유에 큰 변화를 가져왔다."),
        ("1930년대~1948", "근대", "민족주의와 독립", "학생·노동자 운동과 아웅산을 비롯한 지도자들의 활동으로 독립 요구가 커졌다. 제2차 세계대전과 일본 점령, 영국의 재진입을 거쳐 1948년 독립했지만 다양한 민족 지역과 중앙 정부의 관계는 불안정했다."),
        ("1962~1988", "현대", "군부 쿠데타와 고립 정책", "네윈 장군의 쿠데타로 군부 통치가 시작되었고 ‘버마식 사회주의’ 아래 경제 국유화와 정치적 통제가 이루어졌다. 경제 침체와 시민 불만이 커져 1988년 대규모 민주화 시위가 발생했다."),
        ("1990", "현대", "선거와 권력 이양 거부", "야당이 선거에서 승리했지만 군부는 결과를 인정하지 않고 권력을 유지했다. 아웅산 수치와 민주화 운동은 국제적 관심을 받았으나 정치적 억압과 민족 분쟁은 계속되었다."),
        ("2011~2020", "현대", "부분적 개혁과 민간 정부", "군부가 통제하는 헌법 구조 아래 제한적 개혁과 선거가 진행되었다. 경제·언론 환경은 일부 개방되었지만 로힝야족에 대한 박해와 군부의 강한 영향력 등 심각한 인권 문제가 지속되었다."),
        ("2021~현재", "현대", "군부 쿠데타와 저항", "군부가 선거 결과를 뒤집고 권력을 장악하자 대규모 시민 불복종과 무장 저항이 확산되었다. 내전과 인도주의 위기가 심화되었으며, 국가의 미래와 민간인 보호가 국제사회의 주요 관심사가 되었다."),
    ]),
    "MYS": ("말레이시아", [
        ("7~13세기", "중세", "스리비자야와 해상 교역", "말레이 반도와 수마트라 주변은 인도양·남중국해 교역로의 핵심이었다. 스리비자야와 여러 항구 세력은 불교·힌두 문화와 상업 네트워크를 연결했고, 항구 도시의 성장에 영향을 주었다."),
        ("15세기", "근세", "말라카 술탄국", "말라카는 해협 무역의 중심지로 성장해 중국·인도·아랍 상인들이 모이는 국제 항구가 되었다. 이슬람이 왕실과 무역망을 통해 확산되었고 말레이어와 말레이 정치 문화가 발전했다."),
        ("1511", "근세", "포르투갈의 말라카 점령", "포르투갈은 해협 무역을 통제하려 말라카를 점령했다. 이후 네덜란드와 영국도 이 지역에 진출했고, 현지 술탄국은 경쟁하는 열강 사이에서 권력을 유지하려 했다."),
        ("1786~1914", "근대", "영국의 영향력 확대", "영국은 페낭·싱가포르·말라카와 말레이 여러 지역에 영향력을 확대했다. 주석과 고무 산업이 성장하면서 중국·인도계 이주 노동자가 유입되었고 다민족 사회와 식민 경제 구조가 형성되었다."),
        ("1941~1945", "현대", "일본 점령", "일본군 점령은 식민 통치의 권위를 약화시키고 주민들에게 식량 부족과 폭력을 초래했다. 점령 경험은 민족주의와 독립 요구를 강화했으며 전후 영국의 복귀와 공산주의 반란이 이어졌다."),
        ("1957", "현대", "말라야 독립", "말라야 연방은 영국으로부터 독립해 입헌군주제와 의회 제도를 마련했다. 민족 간 정치 협상과 경제 개발이 국가 건설의 핵심이 되었고, 공산주의 반란 대응도 중요한 과제였다."),
        ("1963~1965", "현대", "말레이시아 창설과 싱가포르 분리", "말라야·사바·사라왁·싱가포르가 말레이시아를 구성했지만 정치·경제적 갈등으로 싱가포르는 1965년 분리 독립했다. 연방제와 지역 자치, 민족 간 권리 조정은 이후에도 중요한 문제로 남았다."),
        ("1969~현재", "현대", "다민족 정치와 경제 전환", "1969년 인종 폭동 이후 정부는 빈곤 완화와 말레이계 경제 참여 확대를 위한 정책을 추진했다. 산업화와 수출 제조업이 성장했지만 민족 기반 정책과 정치적 자유, 소득 격차를 둘러싼 논쟁이 이어졌다."),
    ]),
    "SGP": ("싱가포르", [
        ("14세기", "중세", "테마섹 항구", "중국·동남아시아 기록에 등장하는 테마섹은 해상 교역의 거점이었다. 섬은 말라카 해협과 남중국해를 연결하는 위치에 있었고, 지역 왕국과 상인 네트워크가 교류했다."),
        ("1819", "근대", "영국 무역 거점 설립", "스탬퍼드 래플스와 영국 동인도회사는 싱가포르를 자유항으로 발전시켰다. 항구 무역이 급속히 성장하면서 중국·인도·말레이 지역에서 이주민이 유입되어 다언어·다종교 사회가 형성되었다."),
        ("1942~1945", "현대", "일본 점령", "일본군의 싱가포르 점령은 영국 제국의 위상을 크게 약화시켰다. 주민들은 강제 동원과 식량 부족, 폭력을 경험했고, 전후 반식민 민족주의가 성장하는 계기가 되었다."),
        ("1959", "현대", "자치 정부 수립", "싱가포르는 내부 자치권을 얻고 인민행동당 정부가 출범했다. 정부는 주택·교육·산업 정책을 통해 국가 건설을 추진했으며 말레이시아와의 관계 및 공산주의 문제를 둘러싼 논쟁이 이어졌다."),
        ("1963~1965", "현대", "말레이시아 합류와 독립", "싱가포르는 말레이시아에 합류했지만 정치적·경제적 갈등이 커져 1965년 분리 독립했다. 작은 도시국가로서 생존하기 위해 항만·제조업·교육·주택에 집중 투자하고 국제 무역과 안보 협력을 강화했다."),
        ("1960~1980년대", "현대", "산업화와 도시 개발", "정부 주도의 산업 정책과 외국인 투자 유치, 공공주택 공급으로 생활환경과 경제 구조가 빠르게 바뀌었다. 성장의 성과와 함께 정치적 경쟁, 언론 자유, 노동권을 둘러싼 논쟁도 이어졌다."),
        ("1990년대~현재", "현대", "세계 금융·물류 중심지", "싱가포르는 항만·금융·기술 산업을 바탕으로 세계 경제와 연결되었다. 국제 인재와 무역에 의존하는 구조는 번영을 가져왔지만 주거비, 소득 격차, 인구 고령화와 같은 과제도 만들었다."),
    ]),
    "GHA": ("가나", [
        ("11~15세기", "중세", "사헬·숲 지역의 무역 국가", "오늘날 가나 지역에서는 금과 콜라 열매, 소금 교역이 내륙과 해안을 연결했다. 여러 아칸 공동체와 정치체가 성장했고, 금 무역은 이후 유럽 상인들이 해안에 진출하는 중요한 배경이 되었다."),
        ("17세기", "근세", "아샨티 왕국의 성장", "아샨티 연합은 오세이 투투와 오콤포 안노케 등과 연결된 전통 속에서 중앙 권력을 강화했다. 금 무역과 군사 조직을 바탕으로 지역 강국이 되었지만 주변 세력과 경쟁했고 대서양 노예무역의 영향도 받았다."),
        ("15~19세기", "근세", "유럽 요새와 대서양 노예무역", "포르투갈을 비롯한 유럽 세력은 해안에 무역 요새를 건설했다. 금과 노예를 둘러싼 교역은 지역 정치와 경제를 바꾸었고, 강제 이송된 사람들의 고통은 대서양 노예무역의 핵심적인 역사적 유산이다."),
        ("1821~1901", "근대", "영국의 영향 확대와 아샨티 전쟁", "영국은 해안 식민지에서 내륙으로 영향력을 넓혔고 아샨티와 여러 차례 전쟁을 벌였다. 전쟁과 조약, 자원 통제는 지역의 정치적 자율성을 약화시키고 식민 통치의 기반을 마련했다."),
        ("1947~1957", "현대", "독립운동과 가나 건국", "콰메 은크루마가 이끈 대중 정치와 노동·청년 운동은 영국 지배에 대한 자치 요구를 확대했다. 골드코스트는 1957년 가나로 독립해 사하라 이남 아프리카에서 초기 독립국 중 하나가 되었고 범아프리카주의의 상징이 되었다."),
        ("1966~1981", "현대", "쿠데타와 정치 불안", "은크루마 축출 뒤 군사정권과 민간정부가 교체되며 경제적 어려움과 정치 불안이 이어졌다. 국가 재정과 수출 작물 의존, 군부의 정치 개입은 안정적인 제도 구축을 어렵게 했다."),
        ("1992", "현대", "제4공화국 헌법", "새 헌법과 선거를 통해 다당제 민주주의가 재정비되었다. 이후 정권 교체가 선거로 이루어지며 서아프리카의 민주적 전환 사례로 평가받았지만 부패와 지역 격차, 경제 의존 문제는 남았다."),
        ("2007~현재", "현대", "석유 생산과 경제 다변화", "상업적 석유 생산은 국가 수입과 투자에 변화를 가져왔다. 동시에 원자재 가격 변동, 공공부채, 환경 보호와 지역사회 이익 배분을 둘러싼 과제가 중요해졌다."),
    ]),
    "KEN": ("케냐", [
        ("수백만 년 전", "선사", "동아프리카 인류 진화 유적", "케냐의 투르카나 호수 주변 등에서는 초기 인류와 인류 조상의 화석이 발견되었다. 이 자료는 인류 진화와 초기 도구 사용, 환경 변화의 관계를 연구하는 데 중요한 증거다."),
        ("1~15세기", "중세", "스와힐리 해안 도시의 성장", "몸바사와 말린디 등 해안 도시들은 인도양 무역망을 통해 아라비아·페르시아·인도와 교류했다. 스와힐리 문화는 아프리카 언어 전통과 이슬람, 해상 교역의 영향이 결합해 발전했다."),
        ("19세기", "근대", "내륙 교역과 유럽 탐험", "상아와 다른 상품을 거래하는 장거리 교역망이 내륙과 해안을 연결했다. 유럽 탐험과 선교 활동은 이후 식민 경쟁의 정보 기반이 되었고 지역 공동체의 정치·경제 관계에 영향을 주었다."),
        ("1895~1920", "근대", "영국령 동아프리카", "영국은 철도 건설과 정착민 농업을 통해 식민 통치를 강화했다. 토지 몰수와 노동 규제는 여러 공동체에 부담을 주었고, 인종에 따른 토지·경제 권력의 불평등이 형성되었다."),
        ("1952~1960", "현대", "마우마우 봉기와 비상사태", "키쿠유를 비롯한 여러 집단의 일부가 토지 상실과 식민 통치에 맞서 무장 봉기를 일으켰다. 영국의 탄압과 구금, 민간인 피해가 발생했으며 이 시기는 독립운동과 식민 폭력에 대한 역사적 논쟁의 핵심이다."),
        ("1963", "현대", "독립과 공화국 수립", "조모 케냐타를 중심으로 케냐가 영국에서 독립했다. 새 정부는 국가 통합과 경제 개발을 추진했지만 토지 분배, 일당 지배, 민족 기반 정치가 중요한 쟁점으로 남았다."),
        ("1991~2002", "현대", "다당제와 정치 개혁", "국내외 압력 속에서 다당제가 회복되었고 2002년 선거에서 여당이 패배하며 정권 교체가 이루어졌다. 선거 경쟁은 확대되었지만 부패와 지역 불평등, 선거 폭력 문제는 지속되었다."),
        ("2010", "현대", "새 헌법과 지방 분권", "국민투표로 채택된 헌법은 권리 보장과 사법 독립, 카운티 정부를 통한 분권을 강화했다. 이는 식민 시대부터 이어진 중앙집권 구조를 바꾸려는 시도였지만 실행 과정에서 재정과 권한 배분 논쟁이 계속되었다."),
    ]),
    "MAR": ("모로코", [
        ("기원전 1천년기", "고대", "베르베르 사회와 지중해 교역", "북아프리카의 아마지그(베르베르) 공동체는 농업·목축과 지중해 교역을 발전시켰다. 페니키아와 카르타고, 로마의 접촉은 해안 도시와 교역망을 바꾸었지만 내륙 지역의 자율성은 오래 유지되었다."),
        ("788경", "중세", "이드리스 왕조", "이드리스 1세와 그 후계자들은 모로코 초기 이슬람 국가 형성에 중요한 역할을 했다. 페스는 종교·상업·학문의 중심지로 성장했고, 아랍어와 이슬람 제도는 아마지그 문화와 상호작용했다."),
        ("11~13세기", "중세", "알모라비드·알모하드 제국", "모로코에서 시작한 왕조들은 마그레브와 이베리아 일부를 지배하며 서지중해의 강국이 되었다. 종교 개혁, 무역, 건축과 학문이 발전했지만 왕조 교체와 지역 반란도 반복되었다."),
        ("1666", "근세", "알라위 왕조", "알라위 왕조는 여러 지역 세력을 통합해 왕권을 강화했다. 유럽 열강과의 외교·무역을 조정하고 사하라 교역로를 관리했으며, 왕실과 부족·도시 사이의 권력 관계가 국가 운영에 중요했다."),
        ("1912", "근대", "프랑스·스페인 보호령", "페스 조약으로 모로코는 프랑스 보호령이 되었고 북부와 남부 일부는 스페인의 영향 아래 놓였다. 식민 행정과 경제 개발은 인프라를 바꾸었지만 토지·자원 통제와 정치적 자율성 상실에 대한 반발을 낳았다."),
        ("1921~1926", "근대", "리프 전쟁", "압델크림이 이끈 리프 지역의 저항 세력은 스페인군에 큰 타격을 주었다. 프랑스와 스페인의 군사 개입으로 저항은 진압되었지만 반식민 민족주의와 지역 자치의 상징으로 남았다."),
        ("1956", "현대", "독립 회복", "모로코는 프랑스로부터 독립을 회복하고 왕정을 중심으로 국가 제도를 재편했다. 교육·행정의 아랍화와 경제 현대화가 추진되었으나 왕권과 정당, 지역 간 불평등의 관계가 정치적 쟁점이 되었다."),
        ("1999~2011", "현대", "개혁과 헌법 변화", "모하메드 6세 시대에 가족법 개혁과 일부 사회·경제 정책 변화가 추진되었다. 2011년 헌법 개정은 의회와 정부의 역할을 조정했지만 왕실의 핵심 권한과 서사하라 문제는 계속 논쟁의 대상이다."),
    ]),
    "DZA": ("알제리", [
        ("기원전 2세기", "고대", "누미디아 왕국", "누미디아는 북아프리카에서 로마와 카르타고 사이의 외교·전쟁에 관여한 왕국이었다. 농업과 기병 전력, 지중해 교역이 발전했고, 로마의 북아프리카 지배가 확대되면서 지역의 정치 질서가 바뀌었다."),
        ("1~5세기", "고대", "로마령 북아프리카", "오늘날 알제리의 일부는 로마 제국의 속주가 되어 도시와 도로, 농업 생산이 발전했다. 로마 유적은 제국 경제와 도시 생활을 보여 주지만 베르베르 지역의 저항과 문화적 지속성도 함께 살펴봐야 한다."),
        ("7~8세기", "중세", "아랍 정복과 이슬람 확산", "아랍 군대와 이후 왕조의 확장으로 이슬람과 아랍어가 점차 퍼졌다. 이 과정은 단순한 교체가 아니라 아마지그 공동체와 이슬람 학문·무역망이 상호작용한 장기적 변화였다."),
        ("1516~1830", "근세", "오스만 알제리", "알제는 오스만 제국의 해상 권력과 지중해 무역·사략 활동의 중심지였다. 지방 통치자와 군사 엘리트는 상당한 자율성을 누렸고, 유럽 국가들과의 전쟁과 외교가 지역 정치에 영향을 주었다."),
        ("1830~1871", "근대", "프랑스 침공과 저항", "프랑스는 1830년 알제를 점령한 뒤 내륙으로 식민 지배를 확대했다. 압델카데르를 비롯한 저항 세력이 장기간 싸웠고, 토지 몰수와 유럽인 정착은 알제리 사회와 경제를 크게 바꾸었다."),
        ("1954~1962", "현대", "알제리 독립전쟁", "민족해방전선(FLN)이 독립전쟁을 시작했고 프랑스군의 강경 진압과 도시·농촌의 폭력이 이어졌다. 전쟁은 대규모 사망과 이주를 낳았으며 1962년 독립으로 끝났지만 식민 과거의 기억은 양국 관계에 계속 영향을 준다."),
        ("1962~1988", "현대", "독립 국가와 일당 체제", "독립 후 정부는 석유·가스 산업을 국유화하고 사회주의적 개발 정책을 추진했다. 교육과 복지 확대가 있었지만 정치적 경쟁은 제한되었고 경제의 에너지 의존과 청년 실업이 중요한 과제가 되었다."),
        ("1988~2000년대", "현대", "시위·내전과 정치 전환", "1988년 시위 이후 다당제 개혁이 추진되었지만 선거 중단과 무장단체의 폭력으로 내전이 발생했다. 민간인 피해가 컸으며 이후 화해 정책과 정치 안정, 시민 자유의 범위를 둘러싼 논쟁이 계속되었다."),
    ]),
    "CUB": ("쿠바", [
        ("기원전 수천 년~15세기", "선사·중세", "타이노 등 원주민 사회", "유럽인이 도착하기 전 쿠바에는 타이노 등 여러 원주민 공동체가 농업·어업·교역을 이어 갔다. 식민화 이후 질병과 강제노동으로 인구가 급격히 줄었으며, 원주민 문화의 유산을 복원하는 연구가 계속되고 있다."),
        ("1492~16세기", "근세", "스페인의 식민 지배", "콜럼버스 원정 이후 스페인은 쿠바를 카리브해 식민 네트워크의 거점으로 삼았다. 원주민 인구 감소 뒤 아프리카 노예 노동이 확대되었고, 설탕 생산과 항구 무역이 사회 구조를 바꾸었다."),
        ("1868~1898", "근대", "독립 전쟁과 미국-스페인 전쟁", "카를로스 마누엘 데 세스페데스의 봉기로 독립운동이 시작되었고 여러 차례 전쟁이 이어졌다. 1898년 미국-스페인 전쟁 뒤 스페인 지배가 끝났지만 미국의 군사·경제적 영향력은 강하게 남았다."),
        ("1902", "현대", "쿠바 공화국 수립", "쿠바는 형식상 독립 공화국이 되었지만 플랫 수정조항과 미국의 개입 권한으로 주권이 제한되었다. 설탕 수출과 외국 자본 의존이 경제를 좌우했고 토지와 소득의 불평등이 지속되었다."),
        ("1933~1952", "현대", "정치 불안과 바티스타의 부상", "쿠데타와 군부 개입이 반복되며 정당 정치가 불안정해졌다. 관광·설탕 산업이 성장했지만 부패와 사회적 격차가 커졌고, 이는 혁명 세력의 지지 기반을 넓혔다."),
        ("1953~1959", "현대", "쿠바 혁명", "피델 카스트로와 혁명 세력은 바티스타 정권에 맞서 무장 투쟁을 벌여 1959년 정권을 무너뜨렸다. 토지 개혁과 국유화가 진행되면서 미국과의 관계가 악화했고 쿠바의 정치·경제 체제가 사회주의 방향으로 바뀌었다."),
        ("1961~1962", "현대", "피그스만 침공과 미사일 위기", "미국의 지원을 받은 망명자들의 침공은 실패했고, 이듬해 소련 핵미사일 배치를 둘러싼 위기가 세계를 핵전쟁 직전까지 몰고 갔다. 쿠바는 냉전의 핵심 무대가 되었고 미국의 금수 조치가 장기화되었다."),
        ("1991~현재", "현대", "소련 붕괴 이후 경제 변화", "소련의 붕괴로 지원과 무역이 급감해 심각한 경제 위기가 발생했다. 관광과 제한적 시장 개혁이 도입되었지만 국가 통제, 이주, 생활 물자 부족, 정치적 자유를 둘러싼 논쟁이 이어지고 있다."),
    ]),
    "COL": ("콜롬비아", [
        ("기원전 수천 년~16세기", "선사·고대", "다양한 원주민 사회", "오늘날 콜롬비아 지역에는 무이스카, 타이로나 등 다양한 원주민 사회가 농업·금속 세공·교역을 발전시켰다. 금 장신구와 의례 유물은 지역의 복잡한 사회 조직과 종교 문화를 보여 준다."),
        ("1499~16세기", "근세", "스페인 정복과 식민 행정", "스페인 정복자들은 카리브해 연안과 안데스 고지대를 점령하고 원주민 노동과 광물 자원을 통제했다. 식민지 사회는 유럽인·원주민·아프리카계 주민이 얽힌 계층 구조로 재편되었다."),
        ("1717·1739", "근세", "누에바그라나다 부왕령", "스페인은 북남미 북부의 행정과 무역을 관리하기 위해 부왕령을 설치했다. 보고타는 행정·교회·교육의 중심지가 되었고, 세금과 무역 규제에 대한 불만이 독립운동의 배경이 되었다."),
        ("1810~1819", "근대", "독립전쟁과 시몬 볼리바르", "스페인 왕정의 위기 속에서 독립운동이 확산되었고 시몬 볼리바르와 여러 지역 지도자가 군사·정치 활동을 이끌었다. 1819년 보야카 전투는 스페인 지배 종식에 결정적 계기가 되었지만 새 국가의 지역 통합은 쉽지 않았다."),
        ("1886", "근대", "중앙집권 헌법", "새 헌법은 강한 중앙 정부와 보수적 국가 체제를 강화했다. 자유주의자와 보수주의자 사이의 갈등은 지역 전쟁으로 이어졌고, 토지 소유와 정치 참여의 불평등이 지속되었다."),
        ("1899~1902", "근대", "천일전쟁", "자유당과 보수당 사이의 내전은 광범위한 사망과 경제적 피해를 낳았다. 전쟁 이후 정치적 분열이 깊어졌고 1903년 파나마 분리와 미국의 영향력 확대 등 지역 질서가 바뀌었다."),
        ("1948~1958", "현대", "라 비올렌시아", "정치 지도자 호르헤 엘리에세르 가이탄 암살 뒤 폭력 사태가 확산되어 정당 지지자와 농촌 공동체가 큰 피해를 입었다. 이 갈등은 토지 문제와 국가 권력, 무장조직의 성장에 장기적인 영향을 주었다."),
        ("1960년대~현재", "현대", "무력 분쟁과 평화 협상", "게릴라 조직과 정부군, 준군사조직, 마약 경제가 얽힌 분쟁으로 민간인 살해와 강제 이주가 이어졌다. 2016년 FARC와의 평화협정은 중요한 전환점이었지만 지역별 폭력과 피해자 권리, 토지 개혁의 과제가 남아 있다."),
    ]),
    "VEN": ("베네수엘라", [
        ("1498~16세기", "근세", "스페인 식민화", "스페인은 카리브해 연안과 내륙에 식민 거점을 세우고 원주민 노동과 토지·자원을 통제했다. 이후 아프리카 노예 노동과 목축·농업 경제가 성장했으며 사회 계층과 인종적 위계가 형성되었다."),
        ("1810~1821", "근대", "독립전쟁", "시몬 볼리바르와 여러 지도자가 스페인 지배에 맞서 독립운동을 이끌었다. 카라보보 전투는 독립에 중요한 계기가 되었지만 전쟁은 인구와 경제에 큰 피해를 남겼다."),
        ("1830", "근대", "그란콜롬비아 해체", "베네수엘라는 콜롬비아·에콰도르와 함께 구성했던 그란콜롬비아에서 분리되었다. 지역 엘리트와 군사 지도자 사이의 경쟁, 연방제와 중앙집권의 논쟁이 새 국가의 정치에 영향을 주었다."),
        ("1908~1935", "근대", "고메스 독재와 석유 산업", "후안 비센테 고메스 정권 시기 석유 산업이 성장하면서 베네수엘라 경제는 세계 시장과 더 강하게 연결되었다. 석유 수입은 국가 재정을 바꾸었지만 정치적 자유는 제한되고 경제가 단일 자원에 의존하는 구조가 강화되었다."),
        ("1958", "현대", "독재 종식과 민주정", "마르코스 페레스 히메네스 정권이 무너진 뒤 정당 간 협약과 선거를 중심으로 민주 정치가 시작되었다. 석유 수입을 활용한 개발이 추진되었지만 부패와 사회적 불평등이 민주 체제의 신뢰를 약화시켰다."),
        ("1998~2013", "현대", "우고 차베스와 볼리바르 혁명", "차베스 정부는 빈곤층을 대상으로 사회 프로그램을 확대하고 석유 산업과 국가의 역할을 강화했다. 지지층의 정치 참여가 확대된 반면 권력 집중, 제도 독립, 경제 관리에 대한 논쟁도 커졌다."),
        ("2014~현재", "현대", "경제·정치 위기와 이주", "석유 가격 하락과 생산 감소, 정책 실패, 제재와 정치 갈등이 겹쳐 심각한 경제 위기가 발생했다. 물자 부족과 대규모 이주가 이어졌고 선거의 정당성, 인권, 경제 회복을 둘러싼 국제적 논의가 계속되고 있다."),
    ]),
    "KAZ": ("카자흐스탄", [
        ("기원전 1천년기", "고대", "초원 유목 문화", "카자흐스탄 초원에서는 스키타이계와 사카 집단을 비롯한 유목 사회가 목축과 금속 공예, 장거리 이동을 발전시켰다. 황금 장식과 무덤 유적은 유라시아 초원 교역과 정치 조직을 연구하는 중요한 자료다."),
        ("6~8세기", "중세", "튀르크계 카간국", "튀르크계 정치체들이 중앙아시아 초원과 실크로드 일부를 지배하며 동서 교역을 연결했다. 튀르크어와 유목 정치 전통은 이후 지역 국가와 민족 정체성 형성에 영향을 주었다."),
        ("13세기", "중세", "몽골 제국의 지배", "몽골 제국의 정복으로 오늘날 카자흐스탄 지역은 유라시아의 넓은 정치·교역 네트워크에 편입되었다. 이후 킵차크 칸국과 여러 후계 정치체가 등장하며 유목 집단과 정착 도시 사이의 관계가 변화했다."),
        ("15~16세기", "근세", "카자흐 칸국", "카자흐 칸국은 여러 유목 집단을 통합해 정치적 정체성을 형성했다. 초원 목축과 교역로 통제가 경제의 핵심이었으며, 주변 러시아·중앙아시아 세력과의 관계가 국가의 자율성에 영향을 주었다."),
        ("18~19세기", "근대", "러시아 제국의 영향 확대", "러시아 제국은 요새와 행정 조직을 확대하고 초원 지역을 점차 통제했다. 토지 이용과 이동 경로가 바뀌면서 유목 경제가 압박을 받았고, 식민 행정과 정착민 이주에 대한 저항이 발생했다."),
        ("1916", "근대", "중앙아시아 봉기", "러시아 제국의 후방 노동 동원령과 토지·행정 정책에 대한 불만이 봉기로 이어졌다. 진압 과정에서 많은 주민이 피해를 입거나 중국으로 피난했으며, 이 사건은 제국 지배에 대한 저항의 중요한 사례다."),
        ("1920~1930년대", "현대", "소비에트화와 집단화", "소련은 국경과 행정 체계를 재편하고 유목민을 집단농장 체제에 편입했다. 강제 정착과 가축 몰수, 기근으로 심각한 인명 피해가 발생했고, 전통적 생활 방식과 사회 구조가 크게 변했다."),
        ("1991~현재", "현대", "독립과 자원 경제", "소련 해체 후 카자흐스탄은 독립 국가가 되었고 석유·가스·광물 개발을 통해 경제를 성장시켰다. 동시에 권력 집중, 지역·소득 격차, 자원 의존, 언어와 국가 정체성을 둘러싼 논쟁이 이어지고 있다."),
    ]),
})

