COMMONS_API = "https://commons.wikimedia.org/w/api.php"
OPENALEX_API = "https://api.openalex.org/works"
LOC_API = "https://www.loc.gov/search/"


def request_json(url, params=None):
    """외부 자료를 안전하게 요청합니다. 실패하면 빈 결과를 반환합니다."""
    try:
        response = requests.get(
            url, params=params,
            headers={"User-Agent": "WorldHistoryTimeline/3.0 (educational history project)"},
            timeout=18,
        )
        response.raise_for_status()
        return response.json()
    except (requests.RequestException, ValueError, TypeError):
        return {}


def scholarly_search_url(query):
    from urllib.parse import quote_plus
    return quote_plus(query)


@st.cache_data(ttl=86400, show_spinner=False)
def academic_works(query):
    """OpenAlex에서 학술 논문·책·학술 자료의 서지정보와 공개 초록을 찾습니다."""
    data = request_json(OPENALEX_API, {
        "search": query,
        "per-page": 5,
        "select": "id,doi,title,publication_year,authorships,primary_location,abstract_inverted_index,type",
    })
    results = []
    for item in data.get("results", []):
        title = (item.get("title") or "").strip()
        if not title:
            continue
        authors = []
        for author in (item.get("authorships") or [])[:3]:
            name = (author.get("author") or {}).get("display_name")
            if name:
                authors.append(name)
        primary = item.get("primary_location") or {}
        source = primary.get("source") or {}
        url = item.get("doi") or primary.get("landing_page_url") or item.get("id")
        abstract = ""
        inverted = item.get("abstract_inverted_index") or {}
        if isinstance(inverted, dict) and inverted:
            indexed = []
            for word, positions in inverted.items():
                for position in positions:
                    indexed.append((position, word))
            indexed.sort(key=lambda pair: pair[0])
            abstract = " ".join(word for _, word in indexed)[:1800]
        results.append({
            "title": title,
            "year": item.get("publication_year"),
            "authors": authors,
            "source": source.get("display_name") or item.get("type") or "학술 자료",
            "url": url,
            "abstract": abstract,
        })
    return results


@st.cache_data(ttl=86400, show_spinner=False)
def loc_records(query):
    """미국 의회도서관(LOC)의 디지털 자료·사진·문서 카탈로그를 검색합니다."""
    data = request_json(LOC_API, {"q": query, "fo": "json", "c": 4})
    results = []
    for item in data.get("results", [])[:4]:
        title = (item.get("title") or "").strip()
        if not title:
            continue
        description = item.get("description") or []
        if isinstance(description, str):
            description = [description]
        results.append({
            "title": title,
            "date": item.get("date") or item.get("dates"),
            "description": " ".join(str(x) for x in description)[:650],
            "url": item.get("url") or item.get("id"),
            "image": (item.get("image_url") or [None])[0] if isinstance(item.get("image_url"), list) else item.get("image_url"),
        })
    return results


def academic_source_links(country_name, topic="history"):
    """학술 백과·대학 도서관·공공 기록관으로 연결되는 검색 링크를 만듭니다."""
    from urllib.parse import quote_plus
    query = quote_plus(f"{country_name} {topic}")
    return [
        ("Encyclopaedia Britannica 전문 백과", f"https://www.britannica.com/search?query={query}"),
        ("Oxford Research Encyclopedias 연구 백과", f"https://www.google.com/search?q=site%3Aoxfordre.com+{query}"),
        ("미국 의회도서관(LOC) 기록·문서", f"https://www.loc.gov/search/?q={query}"),
        ("Google Scholar 학술 논문·인용 검색", f"https://scholar.google.com/scholar?q={query}"),
        ("OpenAlex 학술 논문·책 서지 검색", f"https://openalex.org/works?search={query}"),
        ("JSTOR 학술 논문·도서 검색", f"https://www.jstor.org/action/doBasicSearch?Query={query}"),
        ("UNESCO 세계유산·문화유산 자료", f"https://whc.unesco.org/en/search/?search={query}"),
        ("미국 의회도서관 Country Studies", "https://www.loc.gov/collections/country-studies/about-this-collection/"),
    ]


@st.cache_data(ttl=86400, show_spinner=False)
def commons_image(query):
    """사건 사진은 Wikimedia Commons에서 검색합니다(역사적 설명의 출처와는 구분)."""
    # 사건명+국가명으로 먼저 찾고, 결과가 없으면 사건명만으로 다시 검색합니다.
    # 검색 결과가 해당 사건을 정확히 묘사하는지 여부는 사용자가 원본 페이지에서 확인할 수 있습니다.
    for search_term in (f"filetype:bitmap {query}", f"filetype:bitmap {query.split()[-1] if query.split() else query}"):
        data = request_json(COMMONS_API, {
            "action": "query", "format": "json", "generator": "search",
            "gsrsearch": search_term, "gsrnamespace": 6,
            "gsrlimit": 5, "prop": "imageinfo", "iiprop": "url|mime", "iiurlwidth": 900,
        })
        pages = data.get("query", {}).get("pages", {})
        for page in pages.values():
            info = page.get("imageinfo", [])
            if info and info[0].get("mime", "").startswith("image/"):
                return info[0].get("thumburl") or info[0].get("url")
    return None


def person_detail(name):
    """위키백과 대신 등록된 인물 설명과 학술·공공자료 검색을 제공합니다."""
    from urllib.parse import quote_plus
    known = PEOPLE.get(name)
    query = quote_plus(name)
    return {
        "title": name,
        "extract": known or "이 인물에 대한 설명이 내장되어 있지 않습니다. 아래의 학술 논문·공공 기록 검색 링크에서 자료를 확인할 수 있습니다.",
        "image": commons_image(name),
        "url": f"https://www.britannica.com/search?query={query}",
        "scholar_url": f"https://scholar.google.com/scholar?q={query}",
        "loc_url": f"https://www.loc.gov/search/?q={query}",
    }


@st.cache_data(ttl=86400, show_spinner=False)
def research_event_context(title, country_name):
    """사건의 추가 설명을 학술 서지와 공공 기록물에서 찾습니다."""
    query = f'"{title}" {country_name} history'
    return {
        "works": academic_works(query),
        "records": loc_records(f'"{title}" {country_name}'),
        "links": academic_source_links(country_name, title),
    }


def show_academic_research(country_name):
    """내장 연대기가 없는 나라에도 Wikipedia 대신 연구 자료 검색 경로를 제공합니다."""
    st.info("이 나라에는 아직 상세 연대기가 내장되어 있지 않습니다. 아래에서 학술 논문·공공 기록·전문 백과 자료를 검색할 수 있습니다.")
    query = f"history of {country_name}"
    with st.spinner("학술 자료와 공공 기록을 검색하는 중..."):
        works = academic_works(query)
        records = loc_records(country_name + " history")
    if works:
        st.subheader("학술 자료 (OpenAlex)")
        for work in works:
            st.markdown(f"**[{work['title']}]({work['url']})**")
            meta = " · ".join(str(x) for x in [work.get("year"), ", ".join(work.get("authors", [])), work.get("source")] if x)
            if meta:
                st.caption(meta)
            if work.get("abstract"):
                st.write(work["abstract"][:1000] + ("…" if len(work["abstract"]) > 1000 else ""))
    else:
        st.caption("OpenAlex에서 관련 서지 정보를 찾지 못했습니다. 아래 검색 링크를 이용해 주세요.")
    if records:
        st.subheader("공공 기록·사진·문서 (미국 의회도서관)")
        for record in records:
            st.markdown(f"**[{record['title']}]({record['url']})**")
            if record.get("date"):
                st.caption(str(record["date"]))
            if record.get("description"):
                st.write(record["description"])
    st.subheader("전문 백과·대학·국제기구 자료")
    for label_text, url in academic_source_links(country_name, "history"):
        st.markdown(f"- [{label_text}]({url})")

