HISTORY.update({
 "ATG": ("앤티가 바부다", [
  ("선콜럼버스 시대", "고대", "카리브 원주민 사회", "섬에는 유럽인의 도착 이전부터 원주민 공동체가 살며 어업과 농업, 이웃 섬과의 교류를 이어 갔다. 식민화는 인구와 토지 이용에 큰 변화를 가져왔다."),
  ("1632~1834", "근세", "영국 식민지와 설탕 플랜테이션", "영국은 섬에 식민 거점을 세우고 설탕 생산을 확대했다. 플랜테이션 경제는 아프리카인 노예 노동에 의존했으며 사회와 토지 소유 구조를 크게 바꾸었다."),
  ("1834~1950년대", "근대", "노예제 폐지와 노동운동", "노예제 폐지 뒤에도 농장 노동자들은 낮은 임금과 제한된 권리에 직면했다. 노동조합과 정치 조직의 성장은 자치 요구를 강화했다."),
  ("1981", "현대", "독립", "앤티가 바부다는 영국으로부터 독립했다. 관광업과 국제 서비스가 경제의 중심이 되었으며 섬 생태계와 허리케인 피해에 대한 대비가 중요하다."),
  ("현재", "현대", "관광 경제와 기후 회복력", "관광 수입 의존과 기후 재난 취약성이 주요 과제다. 경제 다변화와 해안 생태계 보호, 재난 대응 기반 강화가 정책의 핵심이다.")]),
 "BRB": ("바베이도스", [
  ("선콜럼버스 시대", "고대", "아라와크·카리브 원주민 사회", "바베이도스에는 유럽인의 도착 이전 원주민 공동체가 살았다. 해상 이동과 농업, 어업이 섬의 초기 생활 기반이었다."),
  ("1627~1834", "근세", "영국 식민지와 설탕 경제", "영국 정착 이후 설탕 플랜테이션이 확대되고 아프리카인 노예 노동이 대규모로 동원되었다. 토지 소유와 인구 구성이 식민 경제에 맞춰 바뀌었다."),
  ("1834~1930년대", "근대", "노예제 폐지와 사회 개혁", "노예제 폐지 뒤에도 정치 참여와 경제적 기회는 불평등하게 분배되었다. 노동운동과 교육 확대 요구가 성장하며 사회 개혁의 기반이 형성되었다."),
  ("1966", "현대", "독립과 영연방 국가", "바베이도스는 영국으로부터 독립했다. 관광과 금융 서비스가 발전했고 의회 민주주의가 국가 운영의 중요한 틀이 되었다."),
  ("2021~현재", "현대", "공화국 전환과 기후 대응", "2021년 바베이도스는 공화국이 되었다. 해수면 상승과 산호초 보호, 관광 경제의 지속가능성은 중요한 정책 과제다.")]),
 "DMA": ("도미니카", [
  ("선콜럼버스 시대", "고대", "칼리나고 공동체", "도미니카에는 카리브해 원주민인 칼리나고 공동체가 살아왔다. 섬의 숲과 해안 자원을 활용한 생활과 지역 항해 전통이 이어졌다."),
  ("15~18세기", "근세", "유럽 세력의 경쟁", "프랑스와 영국이 섬의 지배권을 놓고 경쟁했다. 원주민의 저항과 유럽 전쟁이 식민 정착의 속도와 형태에 영향을 주었다."),
  ("1763~1978", "근대", "영국 통치와 플랜테이션 사회", "영국 통치 아래 농업 경제가 확대되었고 노예 노동과 이후 계약 노동이 사회를 바꾸었다. 자치 요구와 노동운동이 점차 성장했다."),
  ("1978", "현대", "독립", "도미니카는 영국으로부터 독립했다. 농업과 관광, 자연환경을 기반으로 경제를 발전시켰으며 허리케인과 화산 위험에 대비하는 일이 중요하다."),
  ("현재", "현대", "생태관광과 재난 대응", "열대우림과 생물다양성은 중요한 자산이지만 기후 재난에 취약하다. 지속 가능한 관광과 농업 회복력, 재난 대비가 주요 과제다.")]),
 "GRD": ("그레나다", [
  ("선콜럼버스 시대", "고대", "원주민 정착", "그레나다에는 카리브해 원주민 공동체가 살며 농업과 어업, 섬 사이의 교류를 이어 갔다. 유럽 식민화는 원주민 사회의 삶을 크게 바꾸었다."),
  ("17~18세기", "근세", "프랑스·영국 식민 경쟁", "프랑스와 영국이 섬을 두고 경쟁했으며 사탕수수 플랜테이션이 확대되었다. 노예 노동과 대서양 무역은 경제와 사회 구조를 형성했다."),
  ("1834~1950년대", "근대", "노예제 폐지와 노동운동", "노예제 폐지 이후에도 농장 노동자의 처우와 정치적 권리를 둘러싼 갈등이 이어졌다. 노동운동은 자치와 사회 개혁 요구를 키웠다."),
  ("1974", "현대", "독립", "그레나다는 영국으로부터 독립했다. 이후 정치적 갈등과 1979년 혁명, 1983년 외국 군사 개입을 겪으며 국가 제도와 외교 관계가 크게 흔들렸다."),
  ("현재", "현대", "관광·농업과 기후 변화", "관광과 향신료 농업이 경제의 중요한 기반이다. 허리케인 피해와 해안 생태계 보호, 경제 다변화가 주요 과제다.")]),
 "HND": ("온두라스", [
  ("고대", "고대", "마야 문명과 코판", "코판은 마야 문명의 중요한 도시로 비문과 조각, 건축 유산을 남겼다. 마야 사회는 여러 도시국가로 구성되었으며 정치 경쟁과 교역, 농업이 발전을 이끌었다."),
  ("16세기", "근세", "스페인 정복과 식민 통치", "스페인의 정복은 원주민 인구와 토지 소유, 노동 구조를 바꾸었다. 식민 행정과 가톨릭 선교, 농업 생산이 사회를 재편했다."),
  ("1821~1838", "근대", "독립과 중앙아메리카 연방", "스페인으로부터 독립한 뒤 중앙아메리카 연방에 참여했다가 1838년 분리되었다. 지역 엘리트와 자유주의·보수주의 세력의 경쟁이 국가 형성에 영향을 주었다."),
  ("20세기 초", "현대", "바나나 기업과 외국 영향", "바나나 수출 기업과 외국 자본이 경제와 정치에 큰 영향력을 행사했다. 토지 집중과 노동 조건은 사회적 갈등의 중요한 배경이 되었다."),
  ("1980년대~현재", "현대", "민주주의와 사회경제적 과제", "민간 정부 체제가 이어졌지만 빈곤과 이주, 범죄와 허리케인 피해가 사회에 큰 부담을 주었다. 제도 신뢰와 노동 기회, 재난 회복력이 중요한 과제다.")]),
 "LCA": ("세인트루시아", [
  ("선콜럼버스 시대", "고대", "카리브 원주민 사회", "세인트루시아에는 아라와크와 칼리나고 등 원주민 공동체가 살았다. 농업과 어업, 섬 사이의 항해가 생활과 교류의 기반이었다."),
  ("17~18세기", "근세", "프랑스·영국의 식민 경쟁", "프랑스와 영국이 섬의 지배권을 여러 차례 다투었다. 설탕 플랜테이션과 노예 노동은 식민 사회와 인구 구성을 바꾸었다."),
  ("1814~1958", "근대", "영국 식민 통치", "영국이 지배권을 확립한 뒤 농업 수출과 식민 행정이 이어졌다. 노동운동과 자치 요구는 20세기 중반 정치 개혁으로 연결되었다."),
  ("1979", "현대", "독립", "세인트루시아는 영국으로부터 독립했다. 관광과 농업, 서비스 산업이 경제를 이끌며 의회 민주주의를 유지하고 있다."),
  ("현재", "현대", "지속 가능한 섬 경제", "관광 의존과 기후 변화, 허리케인 위험이 주요 과제다. 해양 생태계와 산호초 보호, 청년 고용과 경제 다변화가 중요하다.")]),
 "LIE": ("리히텐슈타인", [
  ("1719", "근세", "공국 성립", "신성로마제국 안에서 리히텐슈타인 공국이 성립했다. 작은 영토였지만 왕조의 권리와 제국의 법적 질서 속에서 독자적 지위를 확보했다."),
  ("1806", "근세", "독립적 주권의 확대", "신성로마제국 해체와 나폴레옹 시대의 재편 속에서 공국의 지위가 달라졌다. 이후 독일권의 정치 변화에 적응하며 주권을 유지했다."),
  ("1866~1920년대", "근대", "중립과 제도 정비", "독일 연방의 해체 뒤 독립성을 유지했고 1차 세계대전 이후 오스트리아와의 관계를 줄이며 스위스와 긴밀한 경제 관계를 맺었다."),
  ("1921", "근대", "헌법과 현대 국가 체제", "헌법을 통해 입헌군주제의 틀이 정비되었다. 주민의 정치 참여와 군주 권한 사이의 균형은 이후에도 국내 정치의 주제가 되었다."),
  ("20세기 후반~현재", "현대", "금융·산업 국가로 발전", "리히텐슈타인은 금융과 고부가가치 제조업을 발전시켰다. 작은 국가의 경제 경쟁력과 국제 금융 규범, 유럽과의 관계가 중요한 의제다.")]),
 "LSO": ("레소토", [
  ("19세기 초", "근세", "바소토 왕국 형성", "모쇼슈 1세는 여러 공동체를 결집해 바소토 왕국의 기반을 마련했다. 지역 전쟁과 이주가 이어지던 시기에 산악 지형은 공동체의 방어와 정치적 통합에 영향을 주었다."),
  ("1868~1966", "근대", "영국 보호령", "영국은 바소토 지역을 보호령으로 만들었고 이후 바수톨란드로 관리했다. 토지와 노동 이동, 남아프리카 경제와의 연결이 주민 생활에 큰 영향을 주었다."),
  ("1966", "현대", "독립", "레소토는 영국으로부터 독립했다. 남아프리카공화국에 둘러싸인 지리적 조건 때문에 이주 노동과 주변국 경제에 대한 의존도가 높았다."),
  ("1970~1990년대", "현대", "정치 갈등과 헌정 변화", "선거와 군부, 왕실 사이의 권력 갈등이 반복되었다. 헌정 질서를 안정시키고 정치적 경쟁을 제도 안에서 해결하는 일이 중요한 과제가 되었다."),
  ("현재", "현대", "물 자원과 경제 다변화", "레소토 고원수 사업은 물과 전력을 주변국에 공급하는 중요한 사업이다. 빈곤과 실업, 기후 변화에 따른 물 관리와 보건 문제가 주요 과제로 남아 있다.")]),
 "MHL": ("마셜제도", [
  ("수천 년 전~", "전근대", "미크로네시아 항해 문화", "마셜제도에는 항해와 별·파도 읽기 지식에 능숙한 공동체가 정착했다. 섬 사이의 교류와 전통 항해 기술은 태평양 해양 문화의 중요한 일부다."),
  ("19세기", "근대", "유럽 상업과 독일 지배", "유럽 상인과 선교사가 방문했고 독일이 식민 지배를 확대했다. 코프라 무역과 외부 행정은 지역 경제와 사회에 변화를 가져왔다."),
  ("1914~1944", "현대", "일본 위임통치와 태평양 전쟁", "제1차 세계대전 뒤 일본이 섬을 통치했고 제2차 세계대전 중 전략적 거점으로 활용했다. 전쟁은 주민의 이동과 생활 환경에 영향을 주었다."),
  ("1946~1958", "현대", "미국의 핵실험", "미국은 비키니 환초와 에니웨톡 환초 등에서 핵실험을 실시해 주민들이 이주해야 했고 환경과 건강에 장기적 우려가 남았다. 핵실험의 기억과 보상 문제는 국가 정체성의 중요한 부분이다."),
  ("1986~현재", "현대", "독립과 기후 외교", "마셜제도는 미국과 자유연합협정을 맺고 독립 국가로 활동한다. 해수면 상승과 핵실험 피해, 기후 변화 대응이 국제 외교의 핵심 의제다.")]),
 "NRU": ("나우루", [
  ("전근대", "전근대", "미크로네시아 섬 공동체", "나우루에는 태평양 항해 네트워크와 연결된 공동체가 오랫동안 살아왔다. 친족 관계와 토지 소유 관습이 사회 조직의 중요한 기반이었다."),
  ("1888~1914", "근대", "독일 식민 통치", "독일이 섬을 식민지로 편입한 뒤 유럽 상업과 행정이 확대되었다. 외부 통치는 토지와 경제 활동에 변화를 가져왔다."),
  ("1900년대~", "근대", "인광석 채굴", "인광석이 발견되면서 섬의 경제는 채굴 산업 중심으로 바뀌었다. 채굴 수익은 생활 수준을 높였지만 토지와 환경을 크게 훼손했다."),
  ("1942~1945", "현대", "일본 점령과 전쟁 피해", "제2차 세계대전 중 일본군이 나우루를 점령했고 주민 일부가 강제로 다른 섬으로 이송되었다. 전쟁은 인구와 생활 기반에 큰 피해를 남겼다."),
  ("1968~현재", "현대", "독립과 환경 복구", "나우루는 1968년 독립했다. 인광석 자원 고갈과 채굴로 훼손된 토지, 공공 재정과 건강 문제를 해결하는 일이 주요 과제다.")]),
 "PSE": ("팔레스타인", [
  ("고대", "고대", "레반트의 고대 도시와 교역", "오늘날 팔레스타인 지역은 이집트와 메소포타미아, 지중해를 잇는 통로였다. 여러 도시와 공동체가 교역·이주·제국의 지배 속에서 변화했다."),
  ("7세기 이후", "중세", "이슬람 시대와 종교적 중심지", "이슬람 정복 이후 아랍어와 이슬람 문화가 확산되었고 예루살렘은 여러 종교의 중요한 성지가 되었다. 이 지역은 순례와 국제 정치의 중심으로 남았다."),
  ("1516~1917", "근세", "오스만 제국의 통치", "팔레스타인 지역은 오스만 제국의 일부로 여러 지방 행정구역에 나뉘어 있었다. 농업과 종교 재단, 도시 상업이 지역 사회를 유지했다."),
  ("1917~1948", "근대", "영국 위임통치와 민족운동", "오스만 제국 붕괴 뒤 영국 위임통치가 시작되었고 유대인 이주와 아랍 주민의 정치적 요구가 충돌했다. 이 과정에서 국가 건설과 토지·이주 문제를 둘러싼 갈등이 커졌다."),
  ("1948~현재", "현대", "난민과 국가 지위 문제", "전쟁과 점령, 이주로 팔레스타인 주민의 삶과 거주지가 크게 영향을 받았다. 국경과 예루살렘, 난민, 안전과 자결권 문제를 둘러싼 협상과 국제 논쟁이 계속되고 있다.")]),
 "SLV": ("엘살바도르", [
  ("고대", "고대", "메소아메리카 문화권", "오늘날 엘살바도르 지역에는 마야와 렌카 등 다양한 공동체가 살았다. 농업과 화산 지형을 활용한 정착, 주변 지역과의 교역이 사회를 형성했다."),
  ("16세기", "근세", "스페인 정복", "스페인의 정복 이후 토지와 노동 체계가 식민 통치에 맞게 바뀌었다. 원주민 공동체는 질병과 강제 노동, 토지 상실의 영향을 받았다."),
  ("1821~1841", "근대", "독립과 중앙아메리카 연방", "스페인으로부터 독립한 뒤 중앙아메리카 연방에 참여했으며 연방 해체 후 독립 국가가 되었다. 토지와 수출 작물을 둘러싼 엘리트 권력의 집중이 지속되었다."),
  ("1932", "현대", "농민 봉기와 대규모 탄압", "농촌의 불평등과 정치적 배제가 봉기로 이어졌고 정부의 진압으로 많은 원주민과 농민이 희생되었다. 사건은 토지 문제와 국가 폭력의 역사에서 중요한 기억으로 남았다."),
  ("1979~1992", "현대", "내전과 평화협정", "정부와 좌파 게릴라 세력의 내전으로 민간인 피해와 이주가 발생했다. 1992년 평화협정 이후 선거 정치가 정착했지만 불평등과 폭력, 이주 문제는 계속 과제로 남았다.")]),
 "SMR": ("산마리노", [
  ("전승상 301년", "고대", "산마리노 공동체의 기원", "전승은 성 마리누스가 공동체를 세웠다고 설명한다. 역사적으로 작은 산악 공동체가 주변 강국 사이에서 자치 전통을 유지해 온 과정이 중요하다."),
  ("중세", "중세", "자치 제도의 성장", "산마리노는 지역 공동체의 규칙과 평의회를 발전시켰다. 주변 이탈리아 도시국가와 교황령의 경쟁 속에서도 자치권을 지키려 했다."),
  ("1600", "근세", "법령과 공화정 전통", "성문 법령이 정비되며 공화정 제도가 제도적으로 자리 잡았다. 소규모 국가의 자치와 외교적 중립이 국가 운영의 중요한 특징이었다."),
  ("19세기", "근대", "이탈리아 통일기와 독립 유지", "이탈리아 통일 운동 과정에서 산마리노는 주변 세력과 관계를 조정하며 독립을 유지했다. 작은 영토와 외교적 인정이 국가 생존의 핵심이었다."),
  ("20세기~현재", "현대", "현대 공화국", "산마리노는 의회와 집정관 제도를 유지하며 관광과 금융, 소규모 산업에 의존한다. 유럽과의 경제 관계와 문화유산 보존이 주요 과제다.")]),
 "SYC": ("세이셸", [
  ("18세기 이전", "전근대", "인도양 항해와 무인도", "세이셸 군도는 장거리 항해자들에게 알려져 있었으나 영구 정착은 늦게 이루어졌다. 인도양 교역망과 해상 항로가 섬의 전략적 위치를 결정했다."),
  ("1756~1814", "근세", "프랑스·영국 식민 경쟁", "프랑스가 정착과 플랜테이션을 시작했고 이후 영국이 지배권을 확보했다. 아프리카 노예와 여러 지역 출신 노동자의 이동이 다문화 사회 형성에 영향을 주었다."),
  ("1814~1976", "근대", "영국 식민지와 자치 운동", "세이셸은 영국 식민지로 관리되며 코프라와 계피 등 농산물 생산이 이루어졌다. 자치와 독립을 요구하는 정치 활동이 점차 확대되었다."),
  ("1976", "현대", "독립", "세이셸은 영국으로부터 독립했다. 관광업과 해양 자원이 경제의 핵심이 되었으며 작은 섬 국가의 개발 과제가 중요해졌다."),
  ("현재", "현대", "해양 보호와 기후 변화", "산호초와 해양 생물다양성은 경제와 환경에 중요하다. 해수면 상승, 해양 오염, 관광 개발과 자연 보호의 균형이 주요 과제다.")]),
 "VAT": ("바티칸 시국", [
  ("1~4세기", "고대", "초기 기독교 공동체", "로마 제국 안에서 기독교 공동체가 성장했고 로마 주교의 권위가 점차 확대되었다. 초기 교회의 역사와 박해, 공인 과정은 유럽 종교사의 중요한 부분이다."),
  ("8~14세기", "중세", "교황권과 교황령", "교황은 종교 지도자이면서 중부 이탈리아의 정치 권력도 행사했다. 교황권은 신성로마제국과 유럽 군주국과 협력하거나 충돌하며 영향력을 넓혔다."),
  ("16세기", "근세", "르네상스와 바티칸 예술", "교황청은 미술과 건축을 후원해 성 베드로 대성당과 시스티나 성당 등 중요한 문화유산을 남겼다. 종교개혁과 가톨릭 개혁은 교황청의 역할을 바꾸었다."),
  ("1870~1929", "근대", "교황령 상실과 로마 문제", "이탈리아 통일 과정에서 교황령이 병합되고 교황의 세속 권력이 크게 줄었다. 이른바 로마 문제는 교황청과 이탈리아 국가 사이의 장기적 갈등으로 이어졌다."),
  ("1929~현재", "현대", "라테라노 조약과 바티칸 시국", "1929년 라테라노 조약으로 바티칸 시국의 주권이 인정되었다. 오늘날 바티칸은 가톨릭 교회의 중심지이자 외교·문화유산 보존의 주체로 활동한다.")]),
})

COUNTRY_OVERVIEWS = {
    "KOR": "한반도의 역사는 여러 국가와 사회가 교류하고 경쟁하며 변화한 과정이다. 고대 국가의 형성, 불교와 유교의 수용, 왕조 교체, 주변 국가와의 전쟁과 외교, 식민 지배와 독립운동, 분단과 민주화가 서로 연결되어 있다. 사건을 볼 때에는 당시의 국제 정세와 백성·민간인의 경험도 함께 살펴보는 것이 중요하다.",
    "JPN": "일본사는 열도 안의 지역 사회와 국가 형성, 중국·한반도와의 교류, 무사 정권의 성장, 에도 시대의 정치 질서, 메이지 유신 이후의 근대화와 제국주의, 전후 헌정 체제와 경제 성장의 흐름으로 볼 수 있다. 각 시대의 변화는 국내 개혁뿐 아니라 동아시아와 세계 정세의 영향도 받았다.",
    "CHN": "중국사는 여러 지역 문명과 왕조의 교체, 통일과 분열, 북방 유목 세력과의 관계, 유교·불교 등 사상과 종교의 변화, 세계 교역의 확대가 함께 작용한 역사다. 근대에는 서구 열강과 일본의 압박, 왕조 체제의 붕괴와 혁명, 공산당 정권 수립, 개혁·개방을 거치며 국가와 사회가 크게 변했다.",
    "USA": "미국사는 원주민 사회의 오랜 역사, 유럽 식민지화, 독립과 헌법 제정, 영토 확장과 노예제, 남북전쟁과 재건, 산업화, 세계대전과 냉전, 시민권 운동을 함께 살펴야 한다. 국가의 성장과 민주주의의 확대가 진행되는 동시에 원주민 강제 이주, 노예제와 인종차별 같은 배제와 불평등도 지속되었다.",
    "GBR": "영국사는 여러 왕국의 통합, 의회와 왕권의 관계 변화, 종교개혁과 혁명, 산업혁명과 제국의 확대, 세계대전 이후 탈식민화와 유럽 통합 논쟁이 중요한 흐름이다.",
    "FRA": "프랑스사는 왕권의 강화와 혁명, 공화정의 성립과 붕괴, 제국주의와 식민지, 세계대전, 전후 민주주의와 유럽 통합이 서로 영향을 주며 전개되었다.",
    "DEU": "독일사는 중부 유럽의 여러 정치체, 신성로마제국, 종교개혁, 프로이센 주도의 통일, 두 차례 세계대전과 나치 범죄, 동서 분단과 재통일을 중심으로 살펴볼 수 있다.",
    "ITA": "이탈리아사는 고대 로마의 유산, 중세와 르네상스의 도시 국가, 외세의 영향, 19세기 통일, 파시즘과 세계대전, 전후 공화국의 형성으로 이어진다.",
    "EGY": "이집트사는 나일강 농업을 바탕으로 한 고대 왕조, 지중해와 서아시아 세력의 지배, 이슬람 문화권의 중심지로서의 발전, 오스만·유럽 열강의 영향, 근대 국가와 현대 정치의 형성을 포함한다.",
    "IND": "인도사는 인더스 문명과 여러 지역 왕국, 불교·힌두교·자이나교의 발전, 이슬람 왕조와 무굴 제국, 영국 식민 지배, 독립과 분할, 헌법 민주주의와 경제 개혁의 흐름으로 이해할 수 있다.",
    "RUS": "러시아사는 키이우 루스와 정교회 수용, 몽골 지배 이후 모스크바의 성장, 차르 제국의 팽창, 농노제와 개혁, 1917년 혁명과 소련, 세계대전과 냉전, 1991년 이후의 국가 재편으로 이어진다.",
    "GRC": "그리스사는 에게해 청동기 문명, 폴리스와 고전기 문화, 헬레니즘과 로마 지배, 비잔티움과 오스만 시대, 19세기 독립과 현대 유럽 국가 형성을 포함한다.",
    "TUR": "오늘날 튀르키예 지역은 히타이트와 그리스·로마·비잔티움 문명, 튀르크계 세력과 오스만 제국, 제1차 세계대전 이후 공화국 수립이 겹쳐 있는 역사적 공간이다.",
    "BRA": "브라질사는 원주민 사회, 포르투갈 식민 지배와 대서양 노예무역, 독립 제국, 노예제 폐지와 공화정, 군사정권과 민주화, 인종·토지·환경 문제를 함께 살펴야 한다.",
}

EVENT_DETAILS = {
    ("KOR", "고조선 건국"): "고조선의 형성 시기는 문헌 전승과 고고학 자료를 구분해 이해해야 한다. 기원전 2333년은 단군 신화에 기반한 전통적 연대이며, 고조선의 실제 국가 형성과 영역에 대해서는 연구자 사이에 논의가 있다. 건국 신화는 후대 사람들이 공동체의 기원과 정체성을 설명하는 방식도 보여 준다.",
    ("KOR", "고조선 멸망"): "한 무제의 군대가 고조선을 공격한 뒤 왕검성이 함락되었고, 한나라는 일부 지역에 군현을 설치했다. 이 사건은 한반도 북부와 만주 지역의 정치 질서를 바꾸었지만, 토착 집단의 사회와 문화가 한순간에 사라진 것은 아니었다. 이후 여러 집단이 성장하며 고대 국가 형성에 영향을 주었다.",
    ("KOR", "삼국 성립"): "고구려·백제·신라는 오랜 기간에 걸쳐 주변 소국과 지역 세력을 통합하며 성장했다. 각 국가는 왕권과 관료 조직을 정비하고 중국 왕조 및 왜와 외교·전쟁을 벌였다. 삼국의 발전은 한반도뿐 아니라 만주와 동아시아 국제 관계 속에서 이해할 필요가 있다.",
    ("KOR", "고구려 불교 공인"): "소수림왕 때 불교 수용과 태학 설립, 율령 정비가 이루어졌다고 전해진다. 불교는 왕권을 뒷받침하는 사상과 국제 교류의 통로가 되었고, 교육과 법 제도의 정비는 국가 운영을 체계화하는 데 기여했다. 다만 당시 변화는 한 번에 완성된 것이 아니라 여러 세대에 걸쳐 진행되었다.",
    ("KOR", "백제·고구려 멸망"): "백제는 660년 나당 연합군의 공격으로 멸망했고, 고구려는 수·당과의 오랜 전쟁 뒤 668년에 무너졌다. 두 나라의 유민과 지배층 일부는 부흥 운동을 벌였고, 고구려 유민 집단은 이후 발해 형성에도 연결된다. 이 사건은 신라와 당이 한반도와 만주 지역을 둘러싸고 경쟁하는 새로운 국면을 열었다.",
    ("KOR", "신라 삼국 통일"): "신라는 당과 연합해 백제와 고구려를 무너뜨렸지만, 이후 한반도 지배권을 둘러싸고 당과 전쟁을 벌였다. 676년 무렵 당 세력을 한반도에서 밀어낸 뒤 신라가 한반도 남부를 통합했으며, 북쪽에서는 고구려 유민과 말갈 세력이 698년 발해를 세웠다. 따라서 이 시기는 '통일'과 함께 북방의 발해가 공존한 남북국 시대로도 설명된다.",
    ("KOR", "고려 건국"): "왕건은 후삼국의 경쟁 속에서 고려를 세우고 936년 후삼국을 통일했다. 고려는 지방 세력과의 연합, 혼인 정책, 불교 후원 등을 활용해 지배 기반을 넓혔다. 이후 문벌 사회와 무신 정권, 몽골과의 전쟁 등으로 정치 질서가 여러 차례 바뀌었다.",
    ("KOR", "몽골 침입"): "13세기 몽골의 침입에 맞서 고려 조정은 강화도로 수도를 옮기고 장기간 항전했다. 전쟁은 농경지와 도시, 민간인 생활에 큰 피해를 주었으며, 이후 고려는 몽골 제국과 강화하고 원 간섭기를 겪었다. 항쟁과 타협은 왕조의 존속, 지배층의 이해관계, 백성의 피해가 복잡하게 얽힌 사건이었다.",
    ("KOR", "조선 건국"): "이성계는 위화도 회군 이후 정치적 주도권을 잡고 1392년 조선을 세웠다. 새 왕조는 유교적 통치 이념과 중앙집권적 관료제를 강화하고 토지·조세 제도를 정비하려 했다. 왕조 교체는 지배층과 제도의 변화를 가져왔지만, 사회의 많은 관행은 오랜 기간에 걸쳐 변화했다.",
    ("KOR", "훈민정음 반포"): "세종은 백성이 한자를 익히기 어려운 현실을 고려해 새 문자 체계를 만들도록 했고, 1443년 창제한 훈민정음을 1446년 반포했다. 해례본은 자음과 모음의 원리, 사용 방법을 설명한다. 문자의 보급과 실제 사용은 계층과 시대에 따라 달랐지만, 한글은 한국어 기록과 교육의 역사에서 중요한 전환점이 되었다.",
    ("KOR", "임진왜란"): "일본군은 1592년 조선을 침략했고 전쟁은 1598년까지 이어졌다. 조선 수군의 해전, 의병 활동, 명의 참전 등이 전쟁의 전개에 영향을 주었으며, 전쟁은 인구와 농업 생산, 문화재에 큰 피해를 남겼다. 전쟁 이후 조선·일본·명 사이의 외교와 동아시아 질서도 크게 바뀌었다.",
    ("KOR", "병자호란"): "후금에서 성장한 청은 조선을 압박했고, 1636년 침입 뒤 조선은 남한산성에서 항전하다가 항복했다. 조선은 청과 군신 관계를 맺었으며, 이 경험은 조정의 대외 인식과 북벌론, 명·청 교체에 대한 논쟁에 오랫동안 영향을 주었다. 전쟁의 피해는 왕실과 군대뿐 아니라 민간 사회에도 미쳤다.",
    ("KOR", "강화도 조약"): "1876년 일본과 체결한 강화도 조약은 조선의 항구 개방과 일본인의 치외법권 등을 규정했다. 조약은 조선이 근대 국제 질서에 편입되는 계기였지만, 일본의 군사적 압박 아래 체결되었고 불평등한 조항을 포함했다. 이후 조선에서는 개혁과 외세 대응을 둘러싼 갈등이 커졌다.",
    ("KOR", "국권 피탈"): "일본은 1905년 을사늑약으로 외교권을 빼앗고 통감부를 설치한 뒤, 1910년 병합 조약을 통해 대한제국을 식민지로 만들었다. 식민 통치는 토지 조사, 산업 정책, 언어·교육 통제와 정치적 탄압을 동반했다. 이에 맞선 의병과 독립운동은 국내외에서 다양한 형태로 전개되었다.",
    ("KOR", "3·1 운동"): "1919년 3월 1일 독립선언과 만세 시위는 전국으로 확산되었고, 일본의 무력 진압으로 많은 희생자가 발생했다. 운동에는 학생·종교인·상인·농민 등 다양한 집단이 참여했으며, 이후 대한민국 임시정부 수립과 국내외 독립운동의 조직화에 영향을 주었다. 식민 당국은 일부 통치 방식을 바꾸었지만 식민 지배 자체는 계속되었다.",
    ("KOR", "광복과 분단"): "1945년 일본의 패전으로 식민 지배가 끝났지만, 한반도는 미군과 소련군의 군정 아래 나뉘었다. 냉전과 국내 정치 세력의 대립 속에서 통일 정부 수립은 실패했고, 남북에 별도의 정부가 만들어지는 방향으로 진행되었다. 광복의 기쁨과 함께 분단의 구조가 형성된 복합적인 시기였다.",
    ("KOR", "6·25 전쟁"): "1950년 북한군의 남침으로 전쟁이 시작되었고, 유엔군과 중국군이 참전하면서 국제전으로 확대되었다. 1953년 정전협정은 전투를 멈추었지만 평화조약은 체결되지 않았다. 전쟁은 대규모 민간인 피해와 이산가족, 도시·산업 기반 파괴를 남겼고 한반도 분단과 군사적 대립을 장기화했다.",
    ("KOR", "4·19 혁명"): "1960년 3·15 부정선거에 대한 항의가 학생과 시민의 시위로 확산되었다. 경찰의 발포와 김주열 열사의 시신 발견은 분노를 키웠고, 이승만 대통령은 하야했다. 4·19 혁명은 시민 참여가 권위주의 정권을 바꾼 사례지만, 이후 정치적 불안과 1961년 군사 쿠데타로 민주주의가 안정적으로 정착하지는 못했다.",
    ("KOR", "경제개발"): "1960년대 이후 수출 중심 산업화와 국가 주도의 경제개발 계획이 빠른 성장을 이끌었다. 도로·항만·공장과 교육이 확대되었지만 노동권 제한, 농촌과 도시의 격차, 재벌 중심 경제 구조 같은 문제도 나타났다. 경제성장은 민주화 운동과 노동운동의 사회적 배경을 이해하는 데 중요한 요소다.",
    ("KOR", "6월 민주항쟁"): "1987년 박종철 고문치사 사건과 4·13 호헌 조치에 대한 반발이 전국적 시위로 확산되었다. 학생과 노동자, 종교계, 시민들이 참여한 항쟁은 대통령 직선제 개헌을 이끌었다. 이후 민주적 선거와 시민사회가 확대되었지만 노동·지역·세대 문제 등은 계속 정치적 과제로 남았다.",
    ("CHN", "하(夏)"): "하 왕조는 중국 고대 문헌에서 초기 왕조로 전해지지만, 기록은 후대에 정리되어 고고학적 자료와의 관계를 신중하게 검토해야 한다. 얼리터우 문화와 하 왕조의 관련성을 두고 다양한 해석이 존재한다. 따라서 전승된 왕조 연대와 확실하게 확인된 고고학적 사실을 구분하는 것이 중요하다.",
    ("CHN", "상(商)"): "상 왕조의 갑골문은 왕실의 점복 기록으로, 초기 중국의 문자·종교·정치 체제를 보여 주는 중요한 1차 자료다. 청동기 제작과 조상 제사는 권력과 의례가 긴밀하게 연결되었음을 보여 준다. 상의 통치 범위와 주변 집단의 관계는 현대 국가의 국경 개념과 같지 않았다는 점도 고려해야 한다.",
    ("CHN", "주(周)"): "주 왕조는 봉건적 분봉 관계를 통해 넓은 영역을 통치했으나 시간이 지나며 제후국의 힘이 커졌다. 춘추·전국 시대의 경쟁은 군사·행정·철학의 변화를 촉진했고, 공자와 여러 사상가가 활동한 배경이 되었다. 이 시기의 사상은 후대 중국과 동아시아의 정치·교육 전통에 큰 영향을 주었다.",
    ("CHN", "진의 통일"): "진시황은 기원전 221년 경쟁 국가들을 정복해 통일 왕조를 세우고 군현제, 문자·도량형·화폐 제도의 통일을 추진했다. 중앙집권 체제는 넓은 영역을 관리하는 기반이 되었지만, 가혹한 부역과 형벌은 사회적 불만을 키웠다. 진 왕조는 짧게 끝났으나 통일 제국의 제도적 모델은 이후 왕조에 큰 영향을 주었다.",
    ("CHN", "한(漢)"): "한 왕조는 진의 중앙집권적 제도를 이어받으면서 유교를 국가 운영의 중요한 이념으로 발전시켰다. 장건의 서역 활동과 실크로드 교역은 중국과 중앙아시아·서아시아의 연결을 넓혔다. 한의 정치·문물은 후대 중국 정체성 형성에 중요한 기준이 되었지만, 왕망의 신 왕조와 농민 반란 등 내부 위기도 겪었다.",
    ("CHN", "삼국·위진남북조"): "한 멸망 뒤 여러 정권이 경쟁하고 남북으로 분열된 시기가 이어졌다. 전쟁과 인구 이동은 사회적 혼란을 낳았지만, 북방 집단과 한족의 교류, 불교의 확산, 문학·철학의 변화도 활발했다. 이후 수 왕조가 재통일할 수 있었던 배경에는 이러한 장기적 통합과 제도 변화가 있었다.",
    ("CHN", "수·당"): "수 왕조는 대운하 건설과 통일을 추진했으나 과도한 동원과 고구려 원정 등이 부담이 되어 붕괴했다. 당 왕조는 관료제와 과거제, 국제 교역을 발전시키며 장안 중심의 국제적 문화를 꽃피웠다. 당의 영향은 한반도·일본·중앙아시아와의 외교·종교·예술 교류에서도 확인된다.",
    ("CHN", "송(宋)"): "송대에는 도시와 상업, 인쇄술, 화약과 나침반의 활용이 발전했고 지식과 상품의 유통이 확대되었다. 경제적 번영에도 북방의 요·금·서하 등과 군사적 경쟁을 벌였으며, 1127년 이후 남송은 남쪽에서 국가를 유지했다. 기술 발전은 단순한 발명 목록이 아니라 시장·행정·교육의 변화와 함께 이해해야 한다.",
    ("CHN", "원(元)"): "몽골의 쿠빌라이가 세운 원 왕조는 중국을 포함한 유라시아 광역 제국의 일부였다. 다양한 민족과 종교가 연결된 교역망이 형성되었고, 마르코 폴로 이야기 등 유럽과 아시아의 접촉에 대한 기록도 남았다. 한편 지배 집단 간 위계와 재정·정치 문제, 반란이 왕조의 안정성을 약화시켰다.",
    ("CHN", "명(明)"): "주원장은 원을 무너뜨리고 명을 세워 한족 왕조를 회복했다. 농업과 관료제를 재정비하고, 정화의 원정처럼 인도양을 향한 대규모 해상 활동도 이루어졌다. 후기로 갈수록 재정 압박과 기후·농업 위기, 반란과 만주 세력의 성장 등이 겹쳐 명은 1644년 무너졌다.",
    ("CHN", "청(淸)"): "만주족이 세운 청은 17~18세기 영토를 넓히며 다민족 제국으로 성장했다. 강희·옹정·건륭 시대에 번영했지만 19세기에는 인구 증가, 재정 문제, 내부 반란과 외세 침략이 겹쳤다. 청의 역사는 중국 내 여러 민족과 지역을 통치한 제국의 성격을 함께 살펴야 한다.",
    ("CHN", "아편전쟁"): "영국과 청 사이의 무역·외교 갈등은 1839~1842년 제1차 아편전쟁으로 이어졌다. 청의 패전 뒤 난징조약으로 항구 개방과 배상금 지급 등이 이루어졌고, 이후 불평등 조약 체제가 확대되었다. 이 사건은 중국의 주권과 경제에 큰 영향을 주었으며 근대 개혁과 반외세 운동의 배경이 되었다.",
    ("CHN", "신해혁명"): "1911년 혁명은 청 왕조를 무너뜨리고 1912년 중화민국 수립으로 이어졌다. 쑨원 등 혁명 세력은 공화정을 추구했지만 군벌 경쟁과 중앙 권력의 약화로 안정적인 통일 국가를 만들기 어려웠다. 왕조 체제의 종말은 정치적 근대화의 출발이었으나 이후 혁명과 내전이 이어졌다.",
    ("CHN", "중화인민공화국"): "국공내전에서 공산당이 승리한 뒤 1949년 중화인민공화국이 수립되었고 국민당 정부는 타이완으로 이동했다. 새 정부는 토지개혁과 사회주의 경제체제를 추진했으며, 이후 대약진운동과 문화대혁명 같은 급격한 정책은 큰 사회적 피해를 낳았다. 현대 중국의 발전을 이해하려면 국가 건설과 정책의 성과·비용을 함께 살펴야 한다.",
    ("CHN", "문화대혁명"): "1966년 시작된 문화대혁명은 마오쩌둥이 정치적 영향력을 재강화하는 과정에서 대중 동원과 권력 투쟁으로 확대되었다. 학교와 문화기관이 혼란을 겪고 지식인과 시민들이 박해를 받았으며, 유물과 문화유산도 파괴되었다. 1976년 이후 지도부는 혼란을 수습하고 정책 방향을 바꾸었다.",
    ("CHN", "개혁·개방"): "1978년 이후 덩샤오핑 지도부는 농업·산업·과학기술·국방의 현대화를 내세우고 시장 요소와 외국인 투자를 확대했다. 경제특구와 수출 제조업은 빠른 경제 성장을 이끌었지만 지역·소득 격차와 노동 환경, 환경 오염 같은 문제도 커졌다. 정치 체제의 지속과 경제 개방의 관계는 현대 중국을 둘러싼 핵심 논쟁이다.",
    ("USA", "제임스타운"): "1607년 버지니아에 세워진 제임스타운은 영국의 북아메리카 식민 지배에서 중요한 초기 거점이었다. 정착민들은 질병과 식량 부족, 원주민 사회와의 갈등을 겪었고 담배 재배가 식민지 경제의 중심이 되었다. 이후 토지 확대와 노동력 수요는 원주민의 토지 상실과 아프리카인의 강제 노예화와 연결되었다.",
    ("USA", "메이플라워호"): "1620년 메이플라워호를 타고 온 영국계 정착민 일부는 플리머스에 정착했다. 메이플라워 서약은 공동체의 규칙을 정한 문서로 기억되지만, 이후 미국 민주주의의 완성된 출발점으로 단순화해서는 안 된다. 원주민 사회와의 관계는 협력과 갈등을 모두 포함했고 식민지 확장으로 원주민의 삶과 영토가 크게 영향을 받았다.",
    ("USA", "독립선언"): "1776년 7월 4일 대륙회의는 독립선언서를 채택해 영국 왕권으로부터 독립을 선언했다. 자연권과 국민 주권을 강조한 선언은 이후 민주주의와 인권 담론에 영향을 주었지만 당시 노예제와 여성·원주민의 정치적 배제는 그대로 남았다. 독립전쟁은 1783년 파리조약으로 미국의 독립을 국제적으로 인정받으며 마무리되었다.",
    ("USA", "미국 헌법"): "1787년 제헌회의에서 마련된 헌법은 연방정부와 주정부의 권한을 나누고 입법·행정·사법의 견제 구조를 설계했다. 헌법은 국가 운영의 틀을 만들었지만 노예제 문제를 타협으로 남겼고, 이후 수정헌법과 정치 운동을 통해 시민권의 범위가 점차 바뀌었다. 헌법 해석을 둘러싼 갈등은 미국 정치의 지속적인 특징이다.",
    ("USA", "루이지애나 매입"): "1803년 미국은 프랑스로부터 루이지애나 영토를 매입해 국토를 크게 넓혔다. 이는 미시시피강과 뉴올리언스의 교역 통로를 확보하는 데 중요했지만, 해당 지역에 살던 원주민 공동체의 주권과 토지 권리를 위협했다. 이후 서부 팽창은 정착민 이동, 강제 이주, 노예제 확대 여부를 둘러싼 갈등과 연결되었다.",
    ("USA", "남북전쟁"): "1861년 남부 여러 주의 연방 탈퇴로 전쟁이 시작되었고, 노예제와 연방의 권한을 둘러싼 갈등이 핵심 배경이었다. 1863년 노예해방선언과 북부의 승리 뒤 노예제가 헌법 수정으로 폐지되었지만, 재건기 이후 인종 분리와 투표권 억압이 오래 지속되었다. 전쟁은 연방의 존속을 확립했지만 인종 평등의 문제를 완전히 해결하지 못했다.",
    ("USA", "대륙횡단철도"): "1869년 동부와 서부를 잇는 대륙횡단철도가 완성되면서 사람과 상품의 이동이 빨라지고 서부 시장이 확대되었다. 중국계 이민 노동자와 아일랜드계 노동자 등 다양한 노동력이 건설에 참여했지만 위험한 노동 환경과 차별을 겪었다. 철도 확장은 경제 성장을 촉진하는 동시에 원주민의 영토 침탈과 정착민 확산을 가속했다.",
    ("USA", "대공황"): "1929년 주식시장 붕괴를 계기로 금융 위기와 생산 감소, 실업이 심각해졌고 위기는 세계 경제로 확산되었다. 프랭클린 루스벨트 정부의 뉴딜 정책은 공공사업과 금융 규제, 사회보장 제도를 확대해 정부 역할을 바꾸었다. 회복은 불균등했고 완전한 경기 회복에는 제2차 세계대전기의 생산 확대도 영향을 주었다.",
    ("USA", "2차 대전"): "미국은 1941년 진주만 공격 이후 전쟁에 본격 참전해 연합국의 군수 생산과 유럽·태평양 전선에 핵심 역할을 했다. 전쟁은 미국의 산업과 국제적 영향력을 크게 키웠지만 일본계 미국인 강제 수용과 히로시마·나가사키 원자폭탄 투하 등 인권·윤리 논쟁도 남겼다. 전후 미국은 유엔과 국제 경제 질서, 냉전의 중심 국가가 되었다.",
    ("USA", "냉전"): "제2차 세계대전 이후 미국과 소련은 서로 다른 정치·경제 체제를 중심으로 군비 경쟁과 동맹 경쟁을 벌였다. 한국전쟁과 베트남전쟁, 핵무기 경쟁, 우주 경쟁은 냉전이 지역 분쟁과 일상 사회에 미친 영향을 보여 준다. 1991년 소련 해체로 냉전은 끝났지만 그 시기의 동맹과 갈등 구조는 여러 지역에 유산을 남겼다.",
    ("USA", "민권법"): "1964년 민권법은 공공시설과 고용 등에서 인종·피부색·종교·성별·출신 국가를 이유로 한 차별을 금지하는 중요한 법률이었다. 마틴 루서 킹 주니어 등 활동가들의 비폭력 운동, 흑인 공동체의 조직화, 연방정부의 개입이 입법에 영향을 주었다. 법 제정 뒤에도 주거·교육·경찰·경제 분야의 구조적 불평등은 계속 쟁점이 되었다.",
    ("USA", "달 착륙"): "1969년 아폴로 11호의 달 착륙은 냉전기의 우주 경쟁 속에서 이루어졌다. 과학자와 기술자, 수많은 기술 노동자가 참여한 이 계획은 컴퓨터·통신·재료공학 발전에도 영향을 주었다. 성취의 상징인 동시에 막대한 비용과 우주 개발의 군사적·정치적 맥락도 함께 연구할 만한 주제다.",
    ("USA", "9·11 테러"): "2001년 9월 11일 알카에다의 테러 공격으로 뉴욕과 워싱턴 등에서 대규모 인명 피해가 발생했다. 미국 정부는 테러와의 전쟁을 선언하고 아프가니스탄에 군사 개입했으며, 안보 정책과 감시 권한이 확대되었다. 이후의 전쟁과 민간인 피해, 시민 자유와 국가 안보의 균형을 둘러싼 논쟁이 국제 사회에 이어졌다.",
    ("USA", "금융위기"): "2007~2008년 미국의 주택 대출 부실과 금융상품 위험이 금융기관 위기로 번지면서 세계 경제가 침체에 빠졌다. 정부와 중앙은행은 금융기관 지원과 경기 부양에 나섰지만 실업과 주택 압류, 불평등이 커졌다. 위기는 금융 규제와 세계 경제의 상호 연결성을 재검토하게 한 계기가 되었다.",

    ("JPN", "메이지 유신"): "1868년 메이지 유신은 도쿠가와 막부의 붕괴와 천황 중심의 새 정부 수립을 가리킨다. 새 정부는 봉건적 번 체제를 폐지하고 징병제·근대 학교·산업 정책을 추진해 중앙집권 국가를 만들었다. 근대화는 국제적 지위 향상과 산업 발전을 가져왔지만, 이후 군사력 확대와 제국주의적 팽창에도 연결되었다.",
    ("JPN", "침략과 패전"): "일본은 1931년 만주사변 이후 중국 대륙에서 침략을 확대했고, 1937년 중일전쟁과 1941년 태평양전쟁으로 전쟁 범위가 넓어졌다. 전쟁은 중국과 아시아·태평양 지역의 민간인에게 막대한 피해를 주었으며, 일본 내에서도 공습과 원자폭탄 투하 등으로 큰 희생이 발생했다. 1945년 항복 뒤 일본은 점령과 헌법 개정을 거쳐 전후 체제를 형성했다.",
    ("GBR", "마그나카르타"): "1215년 마그나카르타는 귀족들이 존 왕에게 요구해 승인받은 문서로, 왕권이 법과 관습의 제약을 받는다는 원칙의 상징으로 후대에 해석되었다. 당시에는 모든 국민의 평등한 권리를 보장한 현대적 헌법이 아니었지만, 왕과 정치 공동체 사이의 권한을 둘러싼 갈등을 보여 준다. 이후 영국의 의회와 법치 전통을 설명할 때 자주 언급된다.",
    ("GBR", "산업혁명"): "18세기 후반 영국에서는 방직업과 증기기관, 석탄·철 생산의 변화가 공장제 생산과 도시화를 촉진했다. 생산량과 교통이 확대되었지만 도시 빈곤, 아동 노동, 위험한 노동 환경, 환경 오염도 심각해졌다. 산업혁명은 영국의 경제력과 제국 확대를 뒷받침했고 세계 여러 지역의 경제 구조를 바꾸었다.",
    ("GBR", "브렉시트"): "2016년 국민투표에서 EU 탈퇴가 다수로 결정되었고, 영국은 협상 끝에 2020년 EU를 공식 탈퇴했다. 이 과정에는 주권과 이민, 경제 규제, 지역 간 격차에 대한 다양한 의견이 작용했다. 탈퇴 이후 무역·이동·북아일랜드 문제 등에서 새로운 제도적 조정이 필요해졌다.",
    ("FRA", "프랑스 혁명"): "1789년 혁명은 재정 위기와 신분제에 대한 불만, 계몽사상의 영향을 배경으로 시작되었다. 봉건적 특권의 폐지와 인권선언은 시민권과 국민 주권 논의에 큰 영향을 주었지만, 혁명은 공포정치와 전쟁, 정치 체제의 급격한 변화도 동반했다. 혁명의 유산은 자유와 평등의 확대뿐 아니라 폭력과 정치적 배제의 문제도 함께 포함한다.",
    ("FRA", "나폴레옹 시대"): "나폴레옹은 쿠데타로 권력을 잡고 행정·법률 체계를 정비했으며, 나폴레옹 법전은 여러 국가의 법제에 영향을 주었다. 동시에 프랑스의 군사적 팽창은 유럽 전역의 전쟁과 점령, 징병을 낳았다. 1815년 워털루 전투 뒤 나폴레옹이 패배했지만, 혁명과 제국 시기의 제도 변화는 유럽 정치에 오래 남았다.",
    ("DEU", "독일 통일"): "프로이센 총리 비스마르크는 덴마크·오스트리아·프랑스와의 전쟁 및 외교를 활용해 독일 통일을 추진했다. 1871년 독일 제국의 성립은 중부 유럽의 세력 균형을 바꾸고 산업화를 촉진했다. 그러나 통일 제국 내부에는 종교·계급·지역 차이가 남았고, 유럽 열강 사이의 경쟁도 심화되었다.",
    ("DEU", "나치 독일"): "1933년 히틀러가 총리가 된 뒤 나치 정권은 민주 제도를 해체하고 반대 세력을 탄압했으며 반유대주의와 인종주의를 국가 정책으로 만들었다. 홀로코스트에서는 유대인 약 600만 명을 비롯한 수많은 사람들이 박해와 학살을 당했다. 나치 독일의 침략은 제2차 세계대전을 확대했으며, 전후 독일 사회의 기억·책임·배상 논의에 깊은 영향을 주었다.",
    ("ITA", "로마 공화정"): "로마 전승에 따르면 기원전 509년 왕정이 끝나고 공화정이 시작되었다. 공화정에서는 집정관과 원로원, 민회 등 여러 기관이 권력을 나누었지만 실제 정치 참여는 시민권과 재산, 성별에 따라 제한되었다. 로마는 이탈리아 반도와 지중해로 세력을 넓혔고, 정복과 노예제, 부의 집중은 공화정 말기의 갈등을 심화시켰다.",
    ("ITA", "이탈리아 통일"): "19세기 리소르지멘토 운동 속에서 사르데냐-피에몬테 왕국의 외교, 카보우르의 정책, 가리발디의 군사 활동 등이 결합해 통일이 진행되었다. 1861년 이탈리아 왕국이 선포되었지만 로마와 베네치아는 뒤에 편입되었고 남북 간 경제 격차와 지역 정체성의 차이는 계속 남았다. 통일은 새로운 국가의 기반을 마련했지만 사회 통합은 장기 과제였다.",
    ("EGY", "이집트 통일"): "나일강 유역의 상·하 이집트가 기원전 3천년기 무렵 통합되면서 초기 왕조 국가가 형성되었다. 나일강의 범람과 관개 농업은 농업 생산과 조세, 노동 동원을 가능하게 했고 파라오 왕권과 종교 의례가 국가 운영을 뒷받침했다. 통일 시기와 과정은 고고학 자료와 후대 기록을 함께 검토해야 한다.",
    ("EGY", "수에즈 운하"): "1869년 개통한 수에즈 운하는 지중해와 홍해를 연결해 유럽과 아시아 사이의 항해 거리를 크게 줄였다. 운하는 세계 무역과 제국주의 경쟁의 전략적 요충지가 되었고, 이집트의 재정과 외국의 개입에도 큰 영향을 주었다. 1956년 나세르의 국유화 선언과 수에즈 위기는 탈식민주의와 냉전의 상징적 사건이었다.",
    ("EGY", "이집트 혁명"): "1952년 자유장교단의 쿠데타로 왕정이 무너졌고, 이후 나세르가 주도하는 공화정이 자리 잡았다. 정부는 토지 개혁과 산업화, 아랍 민족주의를 추진했으며 수에즈 운하 국유화는 국제적 위기를 일으켰다. 사회 개혁과 국가 주도의 발전이 이루어졌지만 정치적 다원주의는 제한되었다.",
    ("IND", "인더스 문명"): "인더스 문명은 하라파와 모헨조다로 등 계획도시, 배수 시설, 표준화된 벽돌과 장거리 교역으로 알려져 있다. 문자 체계는 아직 확실히 해독되지 않아 정치 체제와 종교에 대한 해석에는 한계가 있다. 이 문명은 남아시아의 도시화와 고대 교역을 이해하는 핵심 고고학 자료다.",
    ("IND", "마우리아 왕조"): "찬드라굽타가 세운 마우리아 왕조는 남아시아의 넓은 지역을 통합했고 아소카 왕 때 강력한 제국으로 성장했다. 칼링가 전쟁 이후 아소카는 불교를 후원하고 통치 윤리를 새긴 비문을 세웠다. 비문은 왕의 정책과 행정, 종교적 관용을 연구하는 중요한 사료지만 왕의 이상과 실제 사회를 구분해 읽어야 한다.",
    ("IND", "독립과 분리"): "영국 식민 지배에 대한 독립운동은 간디의 비폭력 운동, 네루와 국민회의, 무슬림 연맹 등 다양한 세력의 활동으로 전개되었다. 1947년 독립과 동시에 인도와 파키스탄이 종교적 기준을 중심으로 분리되면서 대규모 인구 이동과 공동체 폭력이 발생했다. 독립은 식민 지배의 종식을 뜻했지만 국경과 난민, 카슈미르 문제는 이후에도 큰 영향을 미쳤다.",
    ("RUS", "러시아 혁명"): "1917년 2월 혁명으로 차르 니콜라이 2세가 퇴위했고, 임시정부와 노동자·병사 소비에트가 권력을 나누는 불안정한 상황이 이어졌다. 같은 해 10월 볼셰비키가 권력을 장악했지만 이후 내전과 외국의 개입, 경제적 혼란이 발생했다. 혁명은 세계 사회주의 운동과 국제 정치에 큰 영향을 주었으나 권력 집중과 정치적 탄압도 확대되었다.",
    ("RUS", "소련 해체"): "1980년대 후반 고르바초프의 개혁과 공개 정책, 경제 침체, 공화국들의 민족주의와 독립 요구가 겹치며 소련 체제가 약화되었다. 1991년 소련이 해체되면서 러시아와 여러 독립국이 등장했고 계획경제에서 시장경제로의 전환이 진행되었다. 전환 과정은 물가 상승과 불평등, 국가 권력 재편을 동반했으며 냉전 이후 국제 질서를 바꾸었다.",
    ("GRC", "아테네 민주정"): "기원전 6세기 말 클레이스테네스의 개혁은 아테네 시민의 정치 참여 구조를 바꾸고 민주정 발전의 토대가 되었다. 그러나 시민권은 성인 남성 시민에게 제한되었고 여성·노예·외국인 거주자는 정치 참여에서 배제되었다. 아테네 민주정은 직접 민주주의의 중요한 사례인 동시에 고대 사회의 한계를 보여 준다.",
    ("GRC", "페르시아 전쟁"): "기원전 5세기 초 페르시아 제국의 그리스 원정에 맞서 아테네·스파르타 등 여러 폴리스가 저항했다. 마라톤과 살라미스 전투의 승리는 그리스 폴리스의 독립을 유지하는 데 중요했지만, 이후 아테네의 해상 동맹과 스파르타의 경쟁이 심화되었다. 전쟁은 고전기 그리스 정치와 문화의 발전 배경이 되었다.",
    ("TUR", "오스만 제국 건국"): "오스만 왕조는 아나톨리아의 여러 튀르크계 정치 세력 가운데 성장해 비잔티움과 발칸 지역으로 세력을 넓혔다. 초기 오스만의 성공에는 군사 조직, 국경 지역의 동맹, 행정과 세금 체계가 함께 작용했다. 이후 제국은 유럽·아시아·아프리카를 잇는 다민족 국가로 발전했다.",
    ("TUR", "튀르키예 공화국"): "제1차 세계대전에서 오스만 제국이 패배하고 분할 위기에 놓이자 무스타파 케말 아타튀르크가 이끈 민족운동이 독립전쟁을 벌였다. 1923년 공화국이 선포된 뒤 칼리프제 폐지, 법률·교육 개혁, 문자 개혁 등 세속화와 근대화 정책이 추진되었다. 개혁은 국가 제도를 크게 바꾸었지만 종교·정체성·정치 권력에 대한 논쟁도 남겼다.",
    ("BRA", "독립 선언"): "1822년 페드루가 독립을 선언하면서 브라질은 포르투갈 왕실과 연결된 제국으로 독립했다. 스페인령 아메리카의 여러 지역이 공화국을 세운 것과 달리 브라질은 군주제를 유지했고, 지역별 갈등과 노예제도 계속되었다. 독립은 식민 통치의 종식이었지만 사회적 평등이나 노예제 폐지를 곧바로 의미하지는 않았다.",
    ("BRA", "노예제 폐지"): "브라질은 1888년 황금법으로 아메리카 대륙에서 노예제를 폐지한 마지막 국가가 되었다. 노예제 폐지는 노예 저항과 폐지운동, 국제적 압력, 경제 구조 변화의 결과였다. 그러나 토지와 교육, 정치적 권리의 평등한 분배가 뒤따르지 않아 흑인 공동체는 폐지 이후에도 차별과 빈곤에 직면했다.",

}

def build_map(names, selected):
    isos, z = list(names.keys()), []
    for iso in isos:
        z.append(2 if iso == selected else (1 if iso in HISTORY else 0))
    hover = [label(i, names) for i in isos]
    colors = [[0, "#d8d9d7"], [0.5, "#526b82"], [1, "#b08a45"]]
    fig = go.Figure(go.Choropleth(
        locations=isos, z=z, zmin=0, zmax=2, text=hover,
        hovertemplate="%{text}<extra></extra>", colorscale=colors,
        showscale=False, marker_line_color="white", marker_line_width=0.4,
    ))
    fig.update_layout(
        height=520, margin=dict(l=0, r=0, t=0, b=0),
        geo=dict(
            showframe=False, showcoastlines=True, coastlinecolor="#b08a45",
            showcountries=True, countrycolor="#f7f0e3",
            showocean=True, oceancolor="#d9e1e4",
            showland=True, landcolor="#d8cfbc",
            showlakes=True, lakecolor="#d9e1e4",
            projection_type="robinson", bgcolor="rgba(0,0,0,0)",
        ),
        paper_bgcolor="rgba(0,0,0,0)", clickmode="event+select",
    )
    return fig

def render_person(name, key):
    """굵게+밑줄이 적용된 클릭 버튼으로 인물 설명을 펼칩니다."""
    st.markdown(
        "<style>div[data-testid='stButton'] button p {font-weight:700;text-decoration:underline;}</style>",
        unsafe_allow_html=True,
    )
    safe_key = re.sub(r"[^a-zA-Z0-9가-힣]+", "_", f"{key}_{name}")[:180]
    if st.button(f"**{name}**", key=f"person_{safe_key}", help="클릭하면 인물 상세 설명이 표시됩니다"):
        st.session_state["active_person"] = name
    if st.session_state.get("active_person") == name:
        with st.container(border=True):
            with st.spinner(f"{name}의 정보를 불러오는 중..."):
                info = person_detail(name)
            st.subheader(info["title"])
            if info.get("image"):
                st.image(info["image"], width=220)
            st.write(info.get("extract") or "설명을 찾지 못했습니다.")
            st.markdown(f"[관련 문서 열기]({info['url']})")
            if st.button("상세 설명 닫기", key=f"close_{safe_key}"):
                st.session_state["active_person"] = None
                st.rerun()

def _add_custom_keyword(iso):
    """Form callback: add a user-defined timeline keyword before rerender."""
    value = str(st.session_state.get(f"new_keyword_{iso}", "")).strip()
    suggested = ["전쟁", "혁명", "독립", "왕조", "제국", "민주주의", "식민지", "개혁", "종교", "무역", "경제", "문화", "과학", "헌법", "통일", "외교", "인권", "이주"]
    all_keywords = suggested + st.session_state.get("custom_history_keywords", [])
    if not value:
        st.session_state["keyword_notice"] = ("warning", "먼저 키워드를 입력해 주세요.")
    elif any(k.casefold() == value.casefold() for k in all_keywords):
        st.session_state["keyword_notice"] = ("info", "이미 있는 키워드예요. 위의 키워드 필터에서 선택해 주세요.")
    else:
        custom = list(st.session_state.get("custom_history_keywords", []))
        custom.append(value)
        st.session_state["custom_history_keywords"] = custom
        key = f"keywords_{iso}"
        current = list(st.session_state.get(key, []))
        current.append(value)
        st.session_state[key] = current
        st.session_state["keyword_notice"] = ("success", f"‘{value}’ 키워드를 추가했어요.")
    st.session_state[f"new_keyword_{iso}"] = ""


def _delete_custom_keyword(iso):
    selected = st.session_state.get(f"delete_keyword_{iso}", "선택 안 함")
    custom = list(st.session_state.get("custom_history_keywords", []))
    if selected in custom:
        custom.remove(selected)
        st.session_state["custom_history_keywords"] = custom
        for state_key in list(st.session_state.keys()):
            if state_key.startswith("keywords_") and isinstance(st.session_state[state_key], list):
                st.session_state[state_key] = [k for k in st.session_state[state_key] if k != selected]
        st.session_state["keyword_notice"] = ("success", f"‘{selected}’ 키워드를 삭제했어요.")


def show_curated_timeline(iso, events, country_name):
    eras = list(dict.fromkeys(ev[1] for ev in events))
    st.markdown('<div class="section-kicker">TIMELINE ARCHIVE · 연대기 자료실</div>', unsafe_allow_html=True)
    era_col, keyword_col = st.columns([1, 1.6])
    with era_col:
        chosen_eras = st.multiselect("시대 필터", eras, default=eras, key=f"eras_{iso}")
    suggested_keywords = [
        "전쟁", "혁명", "독립", "왕조", "제국", "민주주의", "식민지", "개혁",
        "종교", "무역", "경제", "문화", "과학", "헌법", "통일", "외교", "인권", "이주"
    ]
    custom_keywords = st.session_state.setdefault("custom_history_keywords", [])
    available_keywords = list(dict.fromkeys(suggested_keywords + custom_keywords))
    with keyword_col:
        selected_keywords = st.multiselect(
            "키워드 필터", available_keywords,
            default=st.session_state.get(f"keywords_{iso}", []),
            key=f"keywords_{iso}",
            help="선택한 키워드가 연도·시대·사건 제목·설명에 포함된 사건만 표시합니다. 여러 키워드는 OR 조건으로 검색합니다."
        )
    notice = st.session_state.pop("keyword_notice", None)
    if notice:
        level, message = notice
        getattr(st, level)(message)
    with st.expander("＋ 나만의 역사 키워드 만들기", expanded=False):
        st.caption("예: 해상 무역, 시민권, 왕위 계승, 산업화. 만든 키워드는 현재 세션에서 다른 국가를 볼 때도 선택할 수 있습니다.")
        with st.form(f"add_keyword_form_{iso}"):
            st.text_input("추가할 키워드", placeholder="예: 시민권 운동", max_chars=40, key=f"new_keyword_{iso}")
            st.form_submit_button("키워드 추가", on_click=_add_custom_keyword, args=(iso,))
        if custom_keywords:
            st.markdown("**내가 만든 키워드**")
            delete_col, action_col = st.columns([2, 1])
            with delete_col:
                st.selectbox("삭제할 키워드", ["선택 안 함"] + custom_keywords, key=f"delete_keyword_{iso}")
            with action_col:
                st.write("")
                st.button("키워드 삭제", key=f"delete_keyword_button_{iso}", on_click=_delete_custom_keyword, args=(iso,), disabled=st.session_state.get(f"delete_keyword_{iso}", "선택 안 함") == "선택 안 함")

    filtered_events = []
    for idx, event_data in enumerate(events):
        year, era, title, desc = event_data
        if era not in chosen_eras:
            continue
        searchable = f"{year} {era} {title} {desc} {EVENT_DETAILS.get((iso, title), '')}".casefold()
        if selected_keywords and not any(keyword.casefold() in searchable for keyword in selected_keywords):
            continue
        filtered_events.append((idx, event_data))

    st.caption(f"표시 중인 사건 {len(filtered_events)}개 / 전체 {len(events)}개 · 키워드를 여러 개 선택하면 하나라도 일치하는 사건을 표시합니다.")
    if not filtered_events:
        st.info("선택한 시대와 키워드에 맞는 사건이 없어요. 키워드를 지우거나 다른 단어를 선택해 보세요.")
        return

    for idx, (year, era, title, desc) in filtered_events:
        st.markdown(f'<div class="event-meta">{year}　·　{era}</div>', unsafe_allow_html=True)
        left, right = st.columns([1, 2.7], gap="large")
        with left:
            image_key = f"{iso}_{idx}"
            st.markdown('<div class="flag-plaque">🖼️ 사건 이미지</div>', unsafe_allow_html=True)
            st.caption("자동 사진은 표시하지 않습니다. 이 사건에 맞는 이미지를 직접 올려 주세요.")
            st.session_state.setdefault("custom_event_images", {})
            st.session_state.setdefault("event_image_revisions", {})
            revision = st.session_state["event_image_revisions"].get(image_key, 0)
            uploaded_event_image = st.file_uploader(
                f"{title} 이미지 추가", type=["png", "jpg", "jpeg", "webp"],
                key=f"event_image_upload_{image_key}_{revision}",
                help="이 사건의 설명 옆에 표시할 사진이나 자료 이미지를 선택하세요."
            )
            if uploaded_event_image is not None:
                st.session_state["custom_event_images"][image_key] = uploaded_event_image.getvalue()
            saved_image = st.session_state["custom_event_images"].get(image_key)
            if saved_image:
                st.image(saved_image, use_container_width=True, caption=f"{title} · 직접 추가한 이미지")
                if st.button("이 사건 이미지 삭제", key=f"delete_event_image_{image_key}_{revision}"):
                    st.session_state["custom_event_images"].pop(image_key, None)
                    st.session_state["event_image_revisions"][image_key] = revision + 1
                    st.rerun()
            else:
                st.info("아직 추가된 이미지가 없습니다.")
        with right:
            st.subheader(title)
            st.write(desc)

            with st.expander("📖 자세한 설명 보기", expanded=False):
                event_note = EVENT_DETAILS.get((iso, title))
                if event_note:
                    st.write(event_note)
                else:
                    st.markdown("**이 사건을 이해하는 역사적 맥락**")
                    st.write(COUNTRY_OVERVIEWS.get(iso, f"{country_name}의 역사는 이 사건 이전의 정치·사회적 변화와 주변 지역과의 관계 속에서 이해할 수 있습니다."))
                    st.markdown("**사건을 살펴볼 때 확인할 점**")
                    st.write(f"먼저 위의 요약에서 제시한 사실을 확인한 뒤, 당시의 권력 관계와 사회 구성원에게 미친 영향을 함께 살펴보세요. 특히 {title}의 원인과 결과를 하나로 단정하기보다, 여러 요인과 서로 다른 집단의 경험을 학술 자료에서 비교하는 것이 좋습니다.")
                    st.caption("더 구체적인 배경과 영향은 아래의 별도 출처 및 참고 자료 영역에서 관련 연구와 기록을 확인해 보세요.")

            source_key = f"source_{iso}_{idx}"
            with st.expander("⋯ 출처 및 참고 자료 선택", expanded=False):
                st.caption("설명과 분리된 참고 자료 영역입니다. 자료 유형을 선택한 뒤 검색 버튼을 누르면 관련 자료를 불러옵니다.")
                source_type = st.radio(
                    "확인할 자료 유형",
                    ["학술 논문·서적", "공공 기록·원자료", "전문 백과·국제기구"],
                    horizontal=True,
                    key=f"source_type_{source_key}",
                )
                if st.button("선택한 자료 검색", key=f"search_{source_key}"):
                    with st.spinner("관련 자료를 검색하는 중..."):
                        extra = research_event_context(title, country_name)
                    if source_type == "학술 논문·서적":
                        st.markdown("**OpenAlex 학술 서지정보**")
                        if extra["works"]:
                            for work in extra["works"][:6]:
                                st.markdown(f"- [{work['title']}]({work['url']})")
                                meta = " · ".join(str(x) for x in [work.get("year"), ", ".join(work.get("authors", [])), work.get("source")] if x)
                                if meta:
                                    st.caption(meta)
                                if work.get("abstract"):
                                    st.write(work["abstract"][:1000] + ("…" if len(work["abstract"]) > 1000 else ""))
                        else:
                            st.info("자동 검색에서 관련 학술 서지정보를 찾지 못했습니다. 아래의 직접 검색 링크를 이용해 주세요.")
                        scholar_query = requests.utils.quote(f'"{title}" {country_name} history')
                        st.markdown(f"[Google Scholar에서 직접 검색](https://scholar.google.com/scholar?q={scholar_query})")
                        st.markdown(f"[OpenAlex에서 직접 검색](https://openalex.org/works?search={scholar_query})")
                    elif source_type == "공공 기록·원자료":
                        st.markdown("**미국 의회도서관(LOC) 기록·문서**")
                        if extra["records"]:
                            for record in extra["records"][:6]:
                                st.markdown(f"- [{record['title']}]({record['url']})")
                                if record.get("date"):
                                    st.caption(str(record["date"]))
                                if record.get("description"):
                                    st.write(record["description"])
                        else:
                            st.info("LOC 자동 검색에서 관련 기록을 찾지 못했습니다. 직접 검색 링크를 이용해 주세요.")
                        loc_query = requests.utils.quote(f'"{title}" {country_name}')
                        st.markdown(f"[미국 의회도서관에서 직접 검색](https://www.loc.gov/search/?q={loc_query})")
                    else:
                        st.markdown("**전문 백과·대학·국제기구 자료**")
                        for source_label, source_url in extra["links"]:
                            st.markdown(f"- [{source_label}]({source_url})")
                        st.caption("전문 백과와 기관 페이지는 주제 소개나 추가 자료 탐색에 유용하지만, 모든 링크가 해당 사건을 직접 다루는 것은 아닙니다. 원문과 발행 정보를 확인하세요.")

            people = [person for person in PEOPLE if person in title or person in desc]
            if people:
                st.markdown("**주요 인물 (이름을 클릭하면 상세 설명 표시):**")
                for person in people:
                    render_person(person, f"{country_name}_{idx}")
        st.divider()


# 추가 국가 연대기: 기존 자료를 덮어쓰지 않고, 아직 상세 연대기가 없던 국가를 보강합니다.
