st.markdown(
    '<div class="archive-hero"><div class="build-stamp">ATLAS ARCHIVE · USER IMAGES + ROBINSON MAP 3.0</div>'
    '<div class="section-kicker" style="color:#d4b574">WORLD HISTORY · TIMELINE COLLECTION</div>'
    '<h1>세계 역사 연대기 지도</h1>'
    '<p>문명의 흐름을 따라, 국가와 사건을 탐색하는 디지털 역사 아카이브</p></div>',
    unsafe_allow_html=True,
)
st.markdown('<div class="filter-panel"><strong>⌕ 시대·키워드 탐색실</strong><br><span>아래에서 국가를 선택한 뒤 시대를 좁히거나, 기존 키워드를 고르고 직접 만든 키워드로 사건을 찾아보세요.</span></div>', unsafe_allow_html=True)
with st.expander("📚 자료 출처와 사용 방법", expanded=False):
    st.markdown("""
    **역사 정보는 Wikipedia에서 가져오지 않습니다.** 국가별 연대기는 프로그램에 내장된 편집 자료이며, 사건별 추가 조사 기능은 OpenAlex 학술 서지정보와 미국 의회도서관(LOC)의 기록·문서 검색 결과를 불러옵니다. 참고 링크에는 Britannica, Oxford Research Encyclopedias, JSTOR, Google Scholar, UNESCO도 포함됩니다.

    - **학술 자료:** OpenAlex, Google Scholar, JSTOR, Oxford Research Encyclopedias
    - **공공 기록·1차 자료:** 미국 의회도서관(Country Studies 및 디지털 컬렉션)
    - **문화유산:** UNESCO 세계유산 자료
    - **이미지:** 사건 카드의 기존 자동 사진은 제거했습니다. 사용자가 각 사건에 맞는 이미지를 직접 업로드할 수 있습니다. 업로드한 이미지는 현재 앱 세션에 보관됩니다.

    자동 검색 결과는 사건과 관련성이 완벽하지 않을 수 있습니다. 보고서나 발표에 활용할 때는 원문을 열어 저자, 발행처, 발행 연도와 해당 주장을 직접 확인하세요.
    """)
st.info("청회색: 상세 연대기가 내장된 국가 · 회색: 학술 자료 검색을 제공하는 국가 · 금색: 현재 선택한 국가")

names = country_table()
st.session_state.setdefault("iso", "KOR")
st.session_state.setdefault("last_click", None)
st.session_state.setdefault("active_person", None)
st.session_state.setdefault("custom_flags", {})
st.session_state.setdefault("flag_upload_revision", {})
with st.sidebar:
    st.markdown("## 🏛️ 역사 자료실")
    st.caption("WORLD HISTORY ARCHIVE")
    st.markdown("국가를 선택한 뒤 시대와 키워드를 조합해 사건을 탐색하세요.")
    st.divider()
    st.markdown("**지도 범례**")
    st.markdown("🟡 현재 선택한 국가  \n🔵 연대기가 등록된 국가  \n⚪ 추가 자료 검색 국가")
    st.divider()
    st.markdown("**국기 이미지 관리**")
    st.caption("선택한 국가의 국기 이미지를 직접 올릴 수 있습니다. 업로드한 이미지는 국가 선택 영역 옆과 연대기 제목에 표시됩니다. 지도에 마우스를 올리면 국가명이 표시됩니다.")
    flag_iso = st.session_state["iso"]
    upload_revision = st.session_state["flag_upload_revision"].get(flag_iso, 0)
    uploaded_flag = st.file_uploader(
        f"{label(flag_iso, names)} 국기 이미지 업로드",
        type=["png", "jpg", "jpeg", "webp"],
        key=f"flag_upload_{flag_iso}_{upload_revision}",
        help="PNG, JPG, JPEG, WEBP 이미지 파일을 올려 주세요. 업로드 이미지는 현재 앱 세션에 저장됩니다."
    )
    if uploaded_flag is not None:
        st.session_state["custom_flags"][flag_iso] = uploaded_flag.getvalue()
        st.success(f"{label(flag_iso, names)} 국기를 등록했습니다.")
    if flag_iso in st.session_state["custom_flags"]:
        st.image(st.session_state["custom_flags"][flag_iso], caption=f"{label(flag_iso, names)} 국기 미리보기", width=150)
        if st.button("이 국가의 업로드 국기 삭제", key=f"delete_flag_{flag_iso}"):
            st.session_state["custom_flags"].pop(flag_iso, None)
            st.session_state["flag_upload_revision"][flag_iso] = upload_revision + 1
            st.rerun()

fig = build_map(names, st.session_state["iso"])
event = st.plotly_chart(fig, key="world_map", on_select="rerun",
                        selection_mode="points", use_container_width=True)
points = []
try:
    points = event.selection.points
except Exception:
    pass
if points:
    clicked = points[0].get("location")
    if clicked and clicked != st.session_state["last_click"]:
        st.session_state["last_click"] = clicked
        st.session_state["iso"] = clicked
        st.session_state["picker"] = clicked
        st.rerun()

def sort_key(i):
    return (i not in HISTORY, label(i, names))

sorted_isos = sorted(names, key=sort_key)
def on_pick():
    st.session_state["iso"] = st.session_state["picker"]

st.session_state.setdefault("picker", st.session_state["iso"])
pick_col, flag_col = st.columns([5, 1])
with pick_col:
    st.selectbox("또는 목록에서 나라 선택", sorted_isos,
                 format_func=lambda i: label(i, names),
                 key="picker", on_change=on_pick)
iso = st.session_state["iso"]
country_name = label(iso, names)
with flag_col:
    if iso in st.session_state["custom_flags"]:
        st.image(st.session_state["custom_flags"][iso], caption="등록된 국기", width=100)
    else:
        st.caption("등록된 국기 없음")
st.divider()
title_col, title_text_col = st.columns([1, 8])
with title_col:
    if iso in st.session_state["custom_flags"]:
        st.image(st.session_state["custom_flags"][iso], width=90)
with title_text_col:
    st.markdown(f'<div class="flag-plaque">{country_name}</div>', unsafe_allow_html=True)
    st.header(f"📜 {country_name}의 역사 연대기")
if iso in HISTORY:
    show_curated_timeline(iso, HISTORY[iso][1], country_name)
    st.caption("역사 설명은 프로그램에 내장된 편집 자료입니다. Wikipedia 본문이나 API는 사용하지 않으며, 사건별 추가 조사에서는 OpenAlex·미국 의회도서관 기록을 검색하고 Britannica·Oxford Research Encyclopedias·JSTOR·UNESCO 등의 참고 링크를 제공합니다. 사건 사진은 자동으로 불러오지 않으며, 각 사건 옆에서 사용자가 직접 업로드할 수 있습니다.")
else:
    show_academic_research(country_name)
